#!/usr/bin/env node
// ===========================================================================
// KobPay installer: kobpay-update-2.mjs
//
// Needs 031-036 applied.
//
// 1. PLAIN ENGLISH EVERYWHERE
//    "Susu without the organiser holding your money" meant nothing outside
//    West Africa. The dashboard drawers were crypto-speak AND untrue of
//    KobPay: "decentralized nodes" (there are none), "validators and
//    consensus health" (none), "average gas cost" (sending is free), "Mint
//    Sovereign Asset", "Proof-of-Engagement", "Token Emission", "dApps".
//    All 14 rewritten. Sovereign Vault -> Your wallet. Sovereign
//    Infrastructure -> What you can do, in all six languages.
//
// 2. THE PHONE MENU NEVER WORKED
//    Nothing in the app ever set isMobileMenuOpen to true. The only toggle
//    was the close button INSIDE the off-canvas sidebar, so below lg there
//    was no way to reach any page. A shared menu now ships on all 16 pages.
//
// 3. /score SAID "PERMISSION DENIED"
//    It called the RPC before supabase-js had restored the session, so it
//    went out as anon, which 032 revokes. Every other page waits for
//    getSession() first; this one did not.
//
// 4. "PLEASE SIGN IN" WAS A RED ERROR BOX on four pages. It is a normal
//    state, not a failure.
//
// 5. THE APP DIRECTORY LISTED FOUR APPS THAT DO NOT EXIST
//    KobBot AI, KobPlay, Ready Markets, AegisProp. It reads public_apps()
//    now, and says so plainly when the list is empty. (036)
//
// NOTE: replaces several pages. Each is copied to <name>.backup first.
//
// Run from C:\\kobpay:   node kobpay-update-2.mjs
// ===========================================================================

import fs from 'node:fs';
import path from 'node:path';
const root=process.cwd();
if(!fs.existsSync(path.join(root,'app'))){console.error('Run this from C:\\\\kobpay.');process.exit(1);}
let wrote=0,skipped=0;
function write(rel,body){
  const full=path.join(root,rel);
  fs.mkdirSync(path.dirname(full),{recursive:true});
  if(fs.existsSync(full)&&fs.readFileSync(full,'utf8')===body){console.log('  unchanged  '+rel);skipped++;return;}
  if(fs.existsSync(full)){
    const bak=full+'.backup';
    if(!fs.existsSync(bak)){fs.copyFileSync(full,bak);}
  }
  fs.writeFileSync(full,body);console.log('  written    '+rel);wrote++;
}
console.log('');
console.log('KobPay update 2 — plain English, working phone menu, real app list');
console.log('');

write("app/explorer/page.tsx", "\"use client\";\n\nimport React, { useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport { ArrowLeft, Activity, ShieldCheck, AlertTriangle, Scale, Landmark, Info } from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\nimport AppMenu from \"../components/AppMenu\";\n\n// This page used to stream Ethereum mainnet: latest block, miner addresses,\n// 0.0000 ETH transfers, \"Active Nodes 1,245\" and \"Finality: Instant\" — for a\n// Postgres ledger that has no nodes and no blocks. It was a borrowed feed\n// with nothing to do with KobPay.\n//\n// What a stablecoin issuer can honestly show, and what is far more\n// interesting, is its own supply: how much KPC exists, how much is backed,\n// and whether the books reconcile. Those are facts nobody else can publish\n// and they are the thing a customer actually wants to know.\n//\n// public_stats() is anon-callable by design — this page is read by people who\n// have not signed in. It exposes totals only; nothing identifies a customer.\n\ntype Stats = {\n  price_usd: number;\n  holders: number;\n  in_circulation: number;\n  total_supply: number;\n  volume_24h: number;\n  transactions_24h: number;\n  apps: number;\n  merchants: number;\n  currencies_supported: number;\n  savings_book: number;\n  as_of: string;\n};\n\nconst n = (v: unknown) => (typeof v === \"number\" ? v : Number(v ?? 0));\nconst kpc = (v: unknown) =>\n  n(v).toLocaleString(undefined, { maximumFractionDigits: 2 });\n\ntype ReserveAccount = {\n  name: string; kind: string; currency: string;\n  balance: number; usd: number; as_of: string; days_old: number;\n  stale: boolean; unvalued?: boolean;\n};\ntype ReserveInstrument = { name: string; issuer: string; value: number };\ntype ReserveComposition = {\n  currency: string; tier: string; usd_value: number;\n  share_percent: number; cannot_value: boolean;\n};\ntype ReserveHistory = { at: string; account: string; balance: number; previous: number };\ntype Reserve = {\n  owed_to_customers: number;\n  owed_breakdown: { wallets: number; savings: number; escrow: number };\n  backing_total: number;\n  coverage_percent: number | null;\n  accounts: ReserveAccount[];\n  composition: ReserveComposition[];\n  instruments: ReserveInstrument[];\n  history: ReserveHistory[];\n  reconciliations_total: number;\n  first_reconciliation: string | null;\n  assurance_note: string;\n};\n\nexport default function ExplorerPage() {\n  const [stats, setStats] = useState<Stats | null>(null);\n  const [reserve, setReserve] = useState<Reserve | null>(null);\n  const [loading, setLoading] = useState(true);\n\n  useEffect(() => {\n    Promise.all([\n      supabase.rpc(\"public_stats\"),\n      supabase.rpc(\"public_reserve\"),\n    ]).then(([a, b]) => {\n      setStats((a.data as Stats) ?? null);\n      setReserve((b.data as Reserve) ?? null);\n      setLoading(false);\n    });\n  }, []);\n\n  const backed = stats ? n(stats.total_supply) : 0;\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white font-sans p-5 lg:p-10\">\n      <div className=\"max-w-[1000px] mx-auto\">\n        <div className=\"flex items-center gap-3 lg:gap-4 mb-2\">\n          <Link\n            href=\"/\"\n            className=\"text-[#94A3B8] hover:text-[#22D3EE] p-2.5 lg:p-3 bg-[#111827] rounded-xl border border-[#1F2937]\"\n          >\n            <ArrowLeft size={18} />\n          </Link>\n          <AppMenu />\n          <h1 className=\"text-xl lg:text-3xl font-black uppercase tracking-widest flex items-center gap-3\">\n            <Activity className=\"text-[#22D3EE]\" /> The ledger\n          </h1>\n        </div>\n        <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mb-8 ml-1\">\n          Every KPC that exists, and what stands behind it\n        </p>\n\n        {loading ? (\n          <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-20 text-center\">\n            Loading...\n          </p>\n        ) : !stats ? (\n          <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-8 text-center\">\n            <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.15em]\">\n              The ledger could not be read just now.\n            </p>\n          </div>\n        ) : (\n          <>\n            {/* The peg is the claim everything else rests on, so it leads. */}\n            <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-6 lg:p-8 mb-5\">\n              <div className=\"flex items-start justify-between flex-wrap gap-4\">\n                <div>\n                  <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n                    One KPC is worth\n                  </p>\n                  <p className=\"text-4xl lg:text-5xl font-black text-[#FDB813]\">\n                    ${n(stats.price_usd).toFixed(2)}\n                  </p>\n                  <p className=\"text-[10px] font-mono text-[#10B981] uppercase tracking-[0.15em] mt-2 flex items-center gap-1.5\">\n                    <ShieldCheck size={12} /> Fixed by design, not by a market\n                  </p>\n                </div>\n                <div className=\"text-right\">\n                  <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n                    KPC in existence\n                  </p>\n                  <p className=\"text-2xl lg:text-3xl font-black\">{kpc(stats.total_supply)}</p>\n                  <p className=\"text-[10px] font-mono text-[#4B5563] uppercase tracking-[0.15em] mt-1\">\n                    ${kpc(backed)} of claims\n                  </p>\n                </div>\n              </div>\n            </div>\n\n            <div className=\"grid grid-cols-2 lg:grid-cols-4 gap-3 mb-5\">\n              <Stat label=\"Held by people\" value={kpc(stats.in_circulation)} suffix=\"KPC\" />\n              <Stat label=\"Wallets holding KPC\" value={String(n(stats.holders))} />\n              <Stat label=\"Moved in 24h\" value={kpc(stats.volume_24h)} suffix=\"KPC\" />\n              <Stat label=\"Payments in 24h\" value={String(n(stats.transactions_24h))} />\n            </div>\n\n            <div className=\"grid grid-cols-2 lg:grid-cols-4 gap-3 mb-8\">\n              <Stat label=\"Apps on the rail\" value={String(n(stats.apps))} />\n              <Stat label=\"Businesses\" value={String(n(stats.merchants))} />\n              <Stat label=\"Currencies priced\" value={String(n(stats.currencies_supported))} />\n              <Stat label=\"In savings\" value={kpc(stats.savings_book)} suffix=\"KPC\" />\n            </div>\n\n            {reserve && (\n              <div className=\"mb-8\">\n                <h2 className=\"text-sm font-black uppercase tracking-widest mb-1\">\n                  What backs it\n                </h2>\n                <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] mb-4\">\n                  Every KPC is a claim on KobPay for one dollar. This is what we hold\n                  against those claims.\n                </p>\n\n                {/* Coverage leads and is the only number that can end the\n                    company. Green at 100 or above, red below — no softening. */}\n                <div\n                  className={`rounded-2xl p-6 border mb-3 ${\n                    n(reserve.coverage_percent) >= 100\n                      ? \"bg-[#10B981]/5 border-[#10B981]/30\"\n                      : \"bg-[#EF4444]/10 border-[#EF4444]/40\"\n                  }`}\n                >\n                  <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n                    Coverage\n                  </p>\n                  <p\n                    className={`text-4xl font-black ${\n                      n(reserve.coverage_percent) >= 100 ? \"text-[#10B981]\" : \"text-[#EF4444]\"\n                    }`}\n                  >\n                    {reserve.coverage_percent == null\n                      ? \"—\"\n                      : `${n(reserve.coverage_percent).toFixed(2)}%`}\n                  </p>\n                  <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] mt-2\">\n                    ${kpc(reserve.backing_total)} held · ${kpc(reserve.owed_to_customers)} owed\n                  </p>\n                </div>\n\n                {/* Which currency the backing is in. Every KPC is a claim\n                    for one US dollar, so backing held in another currency\n                    moves with the exchange rate while the claim does not.\n                    An issuer publishing one total can never show that, and\n                    it is the thing most worth knowing. */}\n                {(reserve.composition ?? []).length > 0 && (\n                  <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-5 mb-3\">\n                    <p className=\"text-[9px] font-mono text-[#FDB813] uppercase tracking-[0.2em] mb-1\">\n                      What it is held in\n                    </p>\n                    <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] mb-3 leading-relaxed\">\n                      KPC is a claim for one US dollar. Backing held in another\n                      currency moves with the exchange rate.\n                    </p>\n                    {(reserve.composition ?? []).map((c, i) => (\n                      <div key={i} className=\"py-2 border-b border-[#1F2937] last:border-0\">\n                        <div className=\"flex justify-between items-baseline gap-3\">\n                          <p className=\"text-[11px] font-bold\">\n                            {c.currency}\n                            <span\n                              className={`ml-2 text-[8px] font-mono uppercase tracking-[0.15em] px-1.5 py-0.5 rounded ${\n                                c.tier === \"matched\"\n                                  ? \"bg-[#10B981]/10 text-[#10B981]\"\n                                  : c.tier === \"hard\"\n                                    ? \"bg-[#22D3EE]/10 text-[#22D3EE]\"\n                                    : \"bg-[#FDB813]/10 text-[#FDB813]\"\n                              }`}\n                            >\n                              {c.tier === \"matched\" ? \"matches the claim\" : c.tier}\n                            </span>\n                          </p>\n                          <p className=\"text-xs font-mono font-bold shrink-0\">\n                            {c.cannot_value ? \"—\" : `${n(c.share_percent).toFixed(1)}%`}\n                          </p>\n                        </div>\n                        <div className=\"mt-1.5 h-1.5 bg-[#1F2937] rounded-full\">\n                          <div\n                            className={`h-1.5 rounded-full ${\n                              c.tier === \"matched\"\n                                ? \"bg-[#10B981]\"\n                                : c.tier === \"hard\"\n                                  ? \"bg-[#22D3EE]\"\n                                  : \"bg-[#FDB813]\"\n                            }`}\n                            style={{ width: `${Math.min(100, n(c.share_percent))}%` }}\n                          />\n                        </div>\n                      </div>\n                    ))}\n                  </div>\n                )}\n\n                {reserve.accounts.length > 0 && (\n                  <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-5 mb-3\">\n                    <p className=\"text-[9px] font-mono text-[#FDB813] uppercase tracking-[0.2em] mb-3\">\n                      Where it is held\n                    </p>\n                    {reserve.accounts.map((a, i) => (\n                      <div key={i} className=\"flex justify-between items-start gap-3 py-2 border-b border-[#1F2937] last:border-0\">\n                        <div>\n                          <p className=\"text-[11px] font-bold flex items-center gap-1.5\">\n                            <Landmark size={11} className=\"text-[#94A3B8]\" />\n                            {a.name}\n                          </p>\n                          <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] mt-0.5\">\n                            {a.kind.replace(/_/g, \" \")} · {a.currency}\n                          </p>\n                        </div>\n                        <div className=\"text-right\">\n                          <p className=\"text-xs font-mono font-bold\">\n                            {a.unvalued ? \"not valued\" : `$${kpc(a.usd)}`}\n                          </p>\n                          {/* A figure nobody has refreshed in six weeks proves\n                              very little, and hiding its age is how a\n                              transparency page becomes marketing. */}\n                          <p className={`text-[9px] font-mono uppercase tracking-[0.12em] ${a.stale ? \"text-[#EF4444]\" : \"text-[#4B5563]\"}`}>\n                            {a.stale ? \"out of date · \" : \"\"}\n                            {n(a.days_old) < 1 ? \"today\" : `${Math.round(n(a.days_old))}d ago`}\n                          </p>\n                        </div>\n                      </div>\n                    ))}\n                    {reserve.instruments.map((inst, i) => (\n                      <div key={`i${i}`} className=\"flex justify-between items-start gap-3 py-2 border-b border-[#1F2937] last:border-0\">\n                        <div>\n                          <p className=\"text-[11px] font-bold\">{inst.name}</p>\n                          <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] mt-0.5\">\n                            held with {inst.issuer}\n                          </p>\n                        </div>\n                        <p className=\"text-xs font-mono font-bold\">${kpc(inst.value)}</p>\n                      </div>\n                    ))}\n                  </div>\n                )}\n\n                {/* The track record. Consistency over time is checkable in a\n                    way a single snapshot is not — and it is the part an\n                    issuer cannot manufacture later. */}\n                {reserve.reconciliations_total > 0 && (\n                  <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-5 mb-3\">\n                    <p className=\"text-[9px] font-mono text-[#FDB813] uppercase tracking-[0.2em] mb-1\">\n                      Checked {reserve.reconciliations_total} times\n                    </p>\n                    <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] mb-3\">\n                      since {reserve.first_reconciliation\n                        ? new Date(reserve.first_reconciliation).toLocaleDateString()\n                        : \"—\"}\n                    </p>\n                    {reserve.history.slice(0, 6).map((h, i) => (\n                      <div key={i} className=\"flex justify-between items-baseline py-1\">\n                        <span className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.1em]\">\n                          {new Date(h.at).toLocaleDateString()} · {h.account}\n                        </span>\n                        <span className=\"text-[10px] font-mono font-bold\">{kpc(h.balance)}</span>\n                      </div>\n                    ))}\n                  </div>\n                )}\n\n                {/* Said plainly. Overstating what these numbers prove is the\n                    exact failure other issuers are known for. */}\n                <div className=\"bg-[#1F2937]/40 border border-[#374151] rounded-2xl p-5 flex gap-3\">\n                  <Info size={16} className=\"text-[#94A3B8] shrink-0 mt-0.5\" />\n                  <div>\n                    <p className=\"text-[11px] font-bold mb-1\">Self-reported, not audited</p>\n                    <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] leading-relaxed\">\n                      {reserve.assurance_note}\n                    </p>\n                  </div>\n                </div>\n              </div>\n            )}\n\n            {/* The honest note. A number nobody can check is marketing; the\n                point of this page is that these can be checked. */}\n            <div className=\"bg-[#1F2937]/40 border border-[#374151] rounded-2xl p-5 flex gap-3\">\n              <Scale size={16} className=\"text-[#94A3B8] shrink-0 mt-0.5\" />\n              <div>\n                <p className=\"text-[11px] font-bold mb-1\">Counted, not estimated</p>\n                <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] leading-relaxed\">\n                  Every figure here is read from the ledger when you load the page.\n                  KobPay runs a double-entry ledger: each payment writes two matching\n                  entries, and no account can go below zero. Last read{\" \"}\n                  {new Date(stats.as_of).toLocaleTimeString()}.\n                </p>\n              </div>\n            </div>\n\n            {n(stats.total_supply) === 0 && (\n              <div className=\"mt-5 bg-[#FDB813]/5 border border-[#FDB813]/30 rounded-2xl p-5 flex gap-3\">\n                <AlertTriangle size={16} className=\"text-[#FDB813] shrink-0 mt-0.5\" />\n                <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] leading-relaxed\">\n                  No KPC has been issued yet. These numbers start moving when the\n                  first deposit settles.\n                </p>\n              </div>\n            )}\n          </>\n        )}\n      </div>\n    </div>\n  );\n}\n\nfunction Stat({ label, value, suffix }: { label: string; value: string; suffix?: string }) {\n  return (\n    <div className=\"bg-[#111827] border border-[#1F2937] rounded-xl p-4\">\n      <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mb-1.5\">\n        {label}\n      </p>\n      <p className=\"text-lg lg:text-xl font-black\">\n        {value}\n        {suffix && <span className=\"text-[10px] font-mono text-[#4B5563] ml-1.5\">{suffix}</span>}\n      </p>\n    </div>\n  );\n}\n");

write("app/score/page.tsx", "\"use client\";\n\nimport React, { useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport { ArrowLeft, Gauge, ChevronDown, TrendingUp } from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\nimport AppMenu from \"../components/AppMenu\";\n\n// The copy lesson from /invest applies here more than anywhere: a score is a\n// judgement about a person, and the page has to read like it is on their side.\n// So the number leads, the one thing that would raise it comes second, and the\n// workings go behind a tap for whoever wants them.\n//\n// What this page must NOT do is imply a bureau score. It is KobPay's own, and\n// saying so plainly costs nothing and is the difference between a useful\n// feature and a misleading one.\n\ntype Component = { name: string; points: number; detail: string };\ntype Score = {\n  score: number;\n  band: string;\n  min: number;\n  max: number;\n  components: Component[];\n  improve: string;\n  as_of: string;\n};\n\nconst BANDS: Record<string, { label: string; color: string; ring: string }> = {\n  excellent: { label: \"Excellent\", color: \"#10B981\", ring: \"#10B981\" },\n  good: { label: \"Good\", color: \"#22D3EE\", ring: \"#22D3EE\" },\n  fair: { label: \"Fair\", color: \"#FDB813\", ring: \"#FDB813\" },\n  building: { label: \"Building\", color: \"#94A3B8\", ring: \"#94A3B8\" },\n  \"needs work\": { label: \"Needs work\", color: \"#EF4444\", ring: \"#EF4444\" },\n};\n\nexport default function ScorePage() {\n  const [data, setData] = useState<Score | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [signedIn, setSignedIn] = useState(false);\n  const [error, setError] = useState(\"\");\n  const [showWorkings, setShowWorkings] = useState(false);\n\n  // WAIT FOR THE SESSION BEFORE CALLING.\n  //\n  // supabase-js restores the session from storage asynchronously. Firing the\n  // RPC straight from useEffect sends it before that finishes, so PostgREST\n  // runs it as `anon` — and 032 revokes my_credit_score from anon on purpose.\n  // The result was a signed-in customer being shown\n  // \"permission denied for function my_credit_score\".\n  //\n  // Every other authenticated page here (/limits, /invest) already gets this\n  // right. This one did not, which is what made it look like a grant problem\n  // rather than a race.\n  useEffect(() => {\n    supabase.auth.getSession().then(({ data: s }) => {\n      setSignedIn(Boolean(s.session));\n      if (!s.session) {\n        setLoading(false);\n        return;\n      }\n      supabase.rpc(\"my_credit_score\").then(({ data: d, error: e }) => {\n        // Never show a customer a Postgres message. If it still happens the\n        // console keeps the real one for us.\n        if (e) {\n          console.error(\"my_credit_score\", e);\n          setError(\"Your score could not be worked out just now.\");\n        } else {\n          setData(d as Score);\n        }\n        setLoading(false);\n      });\n    });\n  }, []);\n\n  const band = data ? BANDS[data.band] ?? BANDS.building : BANDS.building;\n  // Position on the dial, clamped so a floor or ceiling score still draws.\n  const pct = data\n    ? Math.max(0, Math.min(1, (data.score - data.min) / (data.max - data.min)))\n    : 0;\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white font-sans p-5 lg:p-10\">\n      <div className=\"max-w-[640px] mx-auto\">\n        <div className=\"flex items-center gap-3 lg:gap-4 mb-8\">\n          <Link\n            href=\"/\"\n            className=\"text-[#94A3B8] hover:text-[#22D3EE] p-2.5 lg:p-3 bg-[#111827] rounded-xl border border-[#1F2937]\"\n          >\n            <ArrowLeft size={18} />\n          </Link>\n          <AppMenu />\n          <h1 className=\"text-xl lg:text-3xl font-black uppercase tracking-widest flex items-center gap-3\">\n            <Gauge className=\"text-[#FDB813]\" /> Your score\n          </h1>\n        </div>\n\n        {loading ? (\n          <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-20 text-center\">\n            Loading...\n          </p>\n        ) : !signedIn ? (\n          <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-8 text-center\">\n            <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.15em]\">\n              Please{\" \"}\n              <Link href=\"/auth\" className=\"text-[#FDB813] underline\">\n                sign in\n              </Link>{\" \"}\n              to see your score.\n            </p>\n          </div>\n        ) : error || !data ? (\n          <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-8 text-center\">\n            <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.15em]\">\n              {error || \"Your score could not be read just now.\"}\n            </p>\n          </div>\n        ) : (\n          <>\n            <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-7 lg:p-9 mb-4 text-center\">\n              <p\n                className=\"text-6xl lg:text-7xl font-black leading-none\"\n                style={{ color: band.color }}\n              >\n                {data.score}\n              </p>\n              <p\n                className=\"text-[11px] font-mono uppercase tracking-[0.25em] mt-3 font-bold\"\n                style={{ color: band.color }}\n              >\n                {band.label}\n              </p>\n\n              <div className=\"mt-6 h-2 bg-[#1F2937] rounded-full relative\">\n                <div\n                  className=\"h-2 rounded-full transition-all duration-700\"\n                  style={{ width: `${pct * 100}%`, backgroundColor: band.ring }}\n                />\n              </div>\n              <div className=\"flex justify-between mt-2\">\n                <span className=\"text-[9px] font-mono text-[#4B5563]\">{data.min}</span>\n                <span className=\"text-[9px] font-mono text-[#4B5563]\">{data.max}</span>\n              </div>\n            </div>\n\n            {/* The single most useful thing we can tell them, given pride of\n                place rather than buried under the breakdown. */}\n            <div className=\"bg-[#FDB813]/5 border border-[#FDB813]/30 rounded-2xl p-5 mb-4 flex gap-3\">\n              <TrendingUp size={18} className=\"text-[#FDB813] shrink-0 mt-0.5\" />\n              <div>\n                <p className=\"text-[9px] font-mono text-[#FDB813] uppercase tracking-[0.2em] mb-1\">\n                  What would raise it\n                </p>\n                <p className=\"text-sm font-bold\">{data.improve}</p>\n              </div>\n            </div>\n\n            <button\n              onClick={() => setShowWorkings((v) => !v)}\n              className=\"w-full bg-[#111827] border border-[#1F2937] rounded-2xl p-4 flex items-center justify-between hover:border-[#22D3EE]/40 transition-colors\"\n            >\n              <span className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.2em]\">\n                How this is worked out\n              </span>\n              <ChevronDown\n                size={16}\n                className={`text-[#94A3B8] transition-transform ${showWorkings ? \"rotate-180\" : \"\"}`}\n              />\n            </button>\n\n            {showWorkings && (\n              <div className=\"mt-3 bg-[#111827] border border-[#1F2937] rounded-2xl p-5\">\n                {data.components.map((c, i) => (\n                  <div\n                    key={i}\n                    className=\"flex justify-between items-start gap-4 py-2.5 border-b border-[#1F2937] last:border-0\"\n                  >\n                    <div>\n                      <p className=\"text-[11px] font-bold\">{c.name}</p>\n                      <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] mt-0.5\">\n                        {c.detail}\n                      </p>\n                    </div>\n                    <p\n                      className={`text-xs font-mono font-bold shrink-0 ${\n                        Number(c.points) > 0\n                          ? \"text-[#10B981]\"\n                          : Number(c.points) < 0\n                            ? \"text-[#EF4444]\"\n                            : \"text-[#4B5563]\"\n                      }`}\n                    >\n                      {Number(c.points) > 0 ? \"+\" : \"\"}\n                      {c.points}\n                    </p>\n                  </div>\n                ))}\n                <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] leading-relaxed mt-4 pt-4 border-t border-[#1F2937]\">\n                  Everyone starts at 500. A new account is not a bad one — there is\n                  simply nothing to go on yet.\n                </p>\n              </div>\n            )}\n\n            {/* Not a bureau score, and saying so is the difference between a\n                useful feature and a misleading one. */}\n            <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] leading-relaxed mt-5 text-center\">\n              This is KobPay&apos;s own score, built from how you use KobPay. It is not\n              a credit bureau rating and is not shared with other lenders. Updated{\" \"}\n              {new Date(data.as_of).toLocaleTimeString()}.\n            </p>\n          </>\n        )}\n      </div>\n    </div>\n  );\n}\n");

write("app/admin/page.tsx", "\"use client\";\n\nimport React, { useCallback, useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport {\n  ArrowLeft,\n  Scale,\n  Coins,\n  Activity,\n  ShieldAlert,\n  Vault,\n  UserCheck,\n  Siren,\n  Percent,\n  Check,\n  Loader2,\n  AlertTriangle,\n} from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\nimport AppMenu from \"../components/AppMenu\";\nimport toast, { Toaster } from \"react-hot-toast\";\n\ntype Dispute = {\n  id: string;\n  reference: string;\n  status: string;\n  amount: number;\n  secured: boolean;\n  reason: string;\n  created_at: string;\n  respond_by: string;\n  resolve_by: string;\n  response_overdue: boolean;\n  decision_overdue: boolean;\n  raised_by: string;\n  raiser_phone: string;\n  against: string | null;\n};\n\ntype Row = Record<string, unknown>;\ntype Disputes = { queue: Dispute[]; pool: Row[] };\ntype Money = {\n  supply: Row[];\n  pools: Row[];\n  savings: Row[];\n  rewards: Row[];\n  drift: { accounts: Row[]; savings: Row[]; circles: Row[]; safe: Row[] };\n};\ntype Ops = { fx: Row[]; jobs: Row[] };\ntype CurrencySummary = {\n  total: number; switched_on: number; can_be_valued: number;\n  can_take_money_in: number; no_rate_yet: number; rate_too_old: number;\n};\ntype CurrencyRow = { code: string; name: string; blocked_by: string };\ntype Currencies = { summary: CurrencySummary; rows: CurrencyRow[] };\ntype Reserve = { health: Row; economics: Row; deployments: Row[] };\ntype FxTier = { matched_usd: number; hard: number; soft: number;\n                matched_percent: number; hard_percent: number; soft_percent: number };\ntype FxBreach = { setting: string; says: string; actual: string; fix: string };\ntype FxRow = { currency: string; tier: string; balance: number; usd_value: number;\n               share_percent: number; cannot_value: boolean };\ntype ReserveFx = {\n  has_reserve: boolean; verdict: string; by_tier?: FxTier; breaches?: FxBreach[];\n  composition?: FxRow[]; coverage_percent?: number; coverage_percent_stressed?: number;\n  buffer_needed_usd?: number; coverage_needed_percent?: number; stress_case?: string;\n};\ntype Rates = { rates: Row[]; yields: Row[]; history: Row[] };\ntype Kyc = { queue: Row[]; tiers: Row[] };\ntype Risk = { queue: Row[]; recent: Row[] };\n\nconst n = (v: unknown) => (typeof v === \"number\" ? v : Number(v ?? 0));\nconst money = (v: unknown) =>\n  n(v).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n\n// The view returns reason as a code. Nobody wants to read 'not_as_described'\n// at 2am while deciding whether to refund somebody.\nconst REASONS: Record<string, string> = {\n  not_received: \"Never arrived\",\n  wrong_amount: \"Wrong amount\",\n  duplicate: \"Charged twice\",\n  unauthorised: \"Didn't authorise it\",\n  not_as_described: \"Not as described\",\n  wrong_recipient: \"Went to the wrong person\",\n  other: \"Other\",\n};\n\nconst since = (iso: string) => {\n  const ms = Date.now() - new Date(iso).getTime();\n  const h = Math.floor(ms / 3600000);\n  if (h < 1) return \"just now\";\n  if (h < 48) return `${h}h ago`;\n  return `${Math.floor(h / 24)}d ago`;\n};\n\nconst until = (iso: string) => {\n  const ms = new Date(iso).getTime() - Date.now();\n  if (ms <= 0) return \"overdue\";\n  const h = Math.floor(ms / 3600000);\n  return h < 48 ? `${h}h left` : `${Math.floor(h / 24)}d left`;\n};\n\nexport default function AdminPage() {\n  const [staff, setStaff] = useState<boolean | null>(null);\n  const [tab, setTab] = useState<\"disputes\" | \"kyc\" | \"risk\" | \"money\" | \"reserve\" | \"rates\" | \"ops\">(\"disputes\");\n  const [disputes, setDisputes] = useState<Disputes | null>(null);\n  const [moneyData, setMoneyData] = useState<Money | null>(null);\n  const [ops, setOps] = useState<Ops | null>(null);\n  const [reserve, setReserve] = useState<Reserve | null>(null);\n  const [reserveFx, setReserveFx] = useState<ReserveFx | null>(null);\n  const [currencies, setCurrencies] = useState<Currencies | null>(null);\n  const [rates, setRates] = useState<Rates | null>(null);\n  const [kyc, setKyc] = useState<Kyc | null>(null);\n  const [risk, setRisk] = useState<Risk | null>(null);\n  const [working, setWorking] = useState<string | null>(null);\n\n  const load = useCallback(async () => {\n    const { data: isStaff } = await supabase.rpc(\"am_i_staff\");\n    setStaff(Boolean(isStaff));\n    if (!isStaff) return;\n\n    const [d, m, o, rv, rfx, rt, ky, rk, cu] = await Promise.all([\n      supabase.rpc(\"admin_disputes\"),\n      supabase.rpc(\"admin_money\"),\n      supabase.rpc(\"admin_ops\"),\n      supabase.rpc(\"admin_reserve\"),\n      supabase.rpc(\"admin_reserve_fx\"),\n      supabase.rpc(\"admin_rates\"),\n      supabase.rpc(\"admin_kyc\"),\n      supabase.rpc(\"admin_risk\"),\n      supabase.rpc(\"admin_currencies\"),\n    ]);\n    if (d.data) setDisputes(d.data as Disputes);\n    if (m.data) setMoneyData(m.data as Money);\n    if (o.data) setOps(o.data as Ops);\n    if (rv.data) setReserve(rv.data as Reserve);\n    if (rfx.data) setReserveFx(rfx.data as ReserveFx);\n    if (rt.data) setRates(rt.data as Rates);\n    if (ky.data) setKyc(ky.data as Kyc);\n    if (rk.data) setRisk(rk.data as Risk);\n    if (cu.data) setCurrencies(cu.data as Currencies);\n  }, []);\n\n  useEffect(() => {\n    load();\n  }, [load]);\n\n  const decideRisk = async (id: string, status: \"cleared\" | \"escalated\") => {\n    const note = window.prompt(\n      status === \"cleared\"\n        ? \"Why is this fine? This is the record if anyone asks later.\"\n        : \"What are you escalating, and to whom?\",\n    );\n    if (!note || !note.trim()) return;\n    setWorking(id);\n    const { error } = await supabase.rpc(\"resolve_risk\", {\n      p_event: id,\n      p_status: status,\n      p_note: note.trim(),\n    });\n    setWorking(null);\n    if (error) {\n      toast.error(error.message.replace(/^.*?:\\s*/, \"\"));\n      return;\n    }\n    toast.success(status === \"cleared\" ? \"Cleared\" : \"Escalated\");\n    load();\n  };\n\n  const decideKyc = async (id: string, decision: \"approved\" | \"more_info\" | \"rejected\") => {\n    let note: string | null = null;\n    if (decision !== \"approved\") {\n      note = window.prompt(\n        decision === \"rejected\"\n          ? \"Why are you rejecting this? They see this.\"\n          : \"What else do you need from them? They see this.\",\n      );\n      if (!note || !note.trim()) return;\n    }\n    setWorking(id);\n    const { error } = await supabase.rpc(\"review_kyc\", {\n      p_submission: id,\n      p_decision: decision,\n      p_note: note?.trim() ?? null,\n    });\n    setWorking(null);\n    if (error) {\n      toast.error(error.message.replace(/^.*?:\\s*/, \"\"));\n      return;\n    }\n    toast.success(decision === \"approved\" ? \"Approved\" : \"Sent back to them\");\n    load();\n  };\n\n  const decide = async (d: Dispute, outcome: \"refund\" | \"reject\" | \"partial\") => {\n    const note = window.prompt(\n      outcome === \"reject\"\n        ? `Why are you rejecting ${d.reference}? The customer sees this.`\n        : `Note for ${d.reference} — the customer sees this.`,\n    );\n    if (!note || !note.trim()) return;\n\n    let amount: number | null = null;\n    if (outcome === \"partial\") {\n      const raw = window.prompt(`How much of the ${money(d.amount)} KPC to return?`);\n      if (!raw) return;\n      amount = Number(raw);\n      if (!Number.isFinite(amount) || amount <= 0 || amount > n(d.amount)) {\n        toast.error(\"That amount isn't within the disputed amount\");\n        return;\n      }\n    }\n\n    setWorking(d.id);\n    const { error } = await supabase.rpc(\"resolve_dispute\", {\n      p_dispute: d.id,\n      p_outcome: outcome,\n      p_note: note.trim(),\n      p_amount: amount,\n    });\n    setWorking(null);\n\n    if (error) {\n      toast.error(error.message.replace(/^.*?:\\s*/, \"\"));\n      return;\n    }\n    toast.success(`${d.reference} ${outcome === \"reject\" ? \"rejected\" : \"refunded\"}`);\n    load();\n  };\n\n  if (staff === null) {\n    return (\n      <Shell>\n        <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-20 text-center\">\n          Loading...\n        </p>\n      </Shell>\n    );\n  }\n\n  if (!staff) {\n    return (\n      <Shell>\n        <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-8 text-center\">\n          <ShieldAlert size={28} className=\"text-[#94A3B8] mx-auto mb-4\" />\n          <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-[0.15em] leading-relaxed\">\n            This page is for KobPay staff.\n            <br />\n            If that should be you, your profile needs a staff role.\n          </p>\n        </div>\n      </Shell>\n    );\n  }\n\n  const driftRows = moneyData\n    ? [\n        ...moneyData.drift.accounts,\n        ...moneyData.drift.savings,\n        ...moneyData.drift.circles,\n        ...moneyData.drift.safe,\n      ]\n    : [];\n\n  return (\n    <Shell>\n      <Toaster position=\"top-center\" />\n\n      <div className=\"flex flex-wrap gap-2 mb-6\">\n        {(\n          [\n            [\"disputes\", \"Disputes\", Scale],\n            [\"kyc\", \"Identity\", UserCheck],\n            [\"risk\", \"Risk\", Siren],\n            [\"money\", \"Money\", Coins],\n            [\"reserve\", \"Reserve\", Vault],\n            [\"rates\", \"Rates\", Percent],\n            [\"ops\", \"Jobs\", Activity],\n          ] as const\n        ).map(([key, label, Icon]) => (\n          <button\n            key={key}\n            onClick={() => setTab(key)}\n            className={`flex-1 min-w-[92px] flex items-center justify-center gap-1.5 py-3 rounded-xl border text-[9px] font-mono uppercase tracking-[0.15em] transition-colors ${\n              tab === key\n                ? \"bg-[#FDB813]/10 border-[#FDB813]/50 text-[#FDB813]\"\n                : \"bg-[#1F2937] border-[#374151] text-[#94A3B8] hover:text-white\"\n            }`}\n          >\n            <Icon size={13} />\n            {label}\n            {key === \"risk\" && risk && risk.queue.length > 0 && (\n              <span className=\"ml-1 px-1.5 py-0.5 rounded bg-[#EF4444] text-white font-black\">\n                {risk.queue.length}\n              </span>\n            )}\n            {key === \"kyc\" && kyc && kyc.queue.length > 0 && (\n              <span className=\"ml-1 px-1.5 py-0.5 rounded bg-[#FDB813] text-[#0A0E14] font-black\">\n                {kyc.queue.length}\n              </span>\n            )}\n            {key === \"disputes\" && disputes && disputes.queue.length > 0 && (\n              <span className=\"ml-1 px-1.5 py-0.5 rounded bg-[#FDB813] text-[#0A0E14] font-black\">\n                {disputes.queue.length}\n              </span>\n            )}\n          </button>\n        ))}\n      </div>\n\n      {/* The single most important thing on this page: if any drift view has a\n          row, the ledger and the balances disagree and nothing else matters. */}\n      {driftRows.length > 0 && (\n        <div className=\"mb-6 bg-[#EF4444]/10 border border-[#EF4444]/40 rounded-xl p-4 flex items-start gap-3\">\n          <AlertTriangle size={18} className=\"text-[#EF4444] shrink-0 mt-0.5\" />\n          <div>\n            <p className=\"text-[10px] font-mono text-[#EF4444] uppercase tracking-[0.15em] font-bold\">\n              {driftRows.length} account{driftRows.length === 1 ? \"\" : \"s\"} out of balance\n            </p>\n            <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] mt-1 leading-relaxed\">\n              The ledger and the stored balances disagree. Stop and investigate before\n              approving anything.\n            </p>\n          </div>\n        </div>\n      )}\n\n      {tab === \"disputes\" && disputes && (\n        <>\n          {disputes.pool.map((p, i) => (\n            <div key={i} className=\"mb-5 grid grid-cols-2 gap-2\">\n              <Stat label=\"Dispute pool\" value={`${money(p.pool)} KPC`} />\n              <Stat\n                label=\"Float available\"\n                value={`${money(p.float_available)} KPC`}\n                bad={Boolean(p.shortfall) || Boolean(p.float_below_exposure)}\n              />\n            </div>\n          ))}\n\n          {disputes.queue.length === 0 ? (\n            <Empty>Nothing waiting on a decision</Empty>\n          ) : (\n            <div className=\"space-y-3\">\n              {disputes.queue.map((d) => (\n                <div\n                  key={d.id}\n                  className={`bg-[#111827] border rounded-xl p-4 ${\n                    d.decision_overdue\n                      ? \"border-[#EF4444]/50\"\n                      : d.response_overdue\n                        ? \"border-[#FDB813]/40\"\n                        : \"border-[#1F2937]\"\n                  }`}\n                >\n                  <div className=\"flex justify-between items-start mb-3\">\n                    <div>\n                      <p className=\"text-sm font-black\">{money(d.amount)} KPC</p>\n                      <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mt-0.5\">\n                        {REASONS[d.reason] ?? d.reason} · {d.reference}\n                      </p>\n                    </div>\n                    <span\n                      className={`text-[9px] font-mono uppercase tracking-[0.15em] px-2 py-1 rounded ${\n                        d.decision_overdue\n                          ? \"bg-[#EF4444]/15 text-[#EF4444]\"\n                          : \"bg-[#1F2937] text-[#94A3B8]\"\n                      }`}\n                    >\n                      {until(d.resolve_by)}\n                    </span>\n                  </div>\n\n                  <div className=\"text-[10px] font-mono text-[#94A3B8] leading-relaxed mb-3\">\n                    <span className=\"text-white\">{d.raised_by}</span> ({d.raiser_phone})\n                    {d.against && (\n                      <>\n                        {\" \"}\n                        against <span className=\"text-white\">{d.against}</span>\n                      </>\n                    )}\n                    <br />\n                    Raised {since(d.created_at)} ·{\" \"}\n                    {d.secured ? \"money is held\" : \"money already left\"} ·{\" \"}\n                    {d.status === \"answered\" ? \"they replied\" : \"no reply yet\"}\n                  </div>\n\n                  <div className=\"grid grid-cols-3 gap-2\">\n                    <Act\n                      onClick={() => decide(d, \"refund\")}\n                      busy={working === d.id}\n                      tone=\"good\"\n                    >\n                      Refund all\n                    </Act>\n                    <Act onClick={() => decide(d, \"partial\")} busy={working === d.id}>\n                      Part\n                    </Act>\n                    <Act onClick={() => decide(d, \"reject\")} busy={working === d.id} tone=\"bad\">\n                      Reject\n                    </Act>\n                  </div>\n                </div>\n              ))}\n            </div>\n          )}\n        </>\n      )}\n\n      {tab === \"money\" && moneyData && (\n        <div className=\"space-y-5\">\n          {moneyData.supply.map((s, i) => (\n            <Panel key={i} title=\"KPC in existence\">\n              <KV k=\"Issued\" v={`${money(s.issued)} KPC`} />\n              <KV k=\"Redeemed\" v={`${money(s.redeemed)} KPC`} />\n              <KV k=\"In customer hands\" v={`${money(s.in_customer_hands)} KPC`} />\n              <KV k=\"In pools\" v={`${money(s.held_in_pools)} KPC`} />\n              <KV k=\"In escrow\" v={`${money(s.in_escrow)} KPC`} />\n              <KV\n                k=\"Unexplained\"\n                v={`${money(s.unexplained)} KPC`}\n                bad={n(s.unexplained) !== 0}\n              />\n            </Panel>\n          ))}\n\n          <Panel title=\"Pools\">\n            {moneyData.pools.map((p, i) => (\n              <KV key={i} k={String(p.label ?? p.ref)} v={`${money(p.balance)} KPC`} />\n            ))}\n          </Panel>\n\n          {moneyData.savings.map((s, i) => (\n            <Panel key={i} title=\"Savings\">\n              <KV k=\"Customer principal\" v={`${money(s.customer_principal)} KPC`} />\n              <KV k=\"Interest accrued, unpaid\" v={`${money(s.interest_accrued_unpaid)} KPC`} />\n              <KV k=\"Interest overdue\" v={`${money(s.interest_overdue)} KPC`} bad={n(s.interest_overdue) > 0} />\n              <KV k=\"Costs per day\" v={`${money(s.daily_interest_cost)} KPC`} />\n              <KV\n                k=\"Pool surplus\"\n                v={`${money(s.pool_surplus_or_shortfall)} KPC`}\n                bad={n(s.pool_surplus_or_shortfall) < 0}\n              />\n            </Panel>\n          ))}\n\n          {moneyData.rewards.map((r, i) => (\n            <Panel key={i} title=\"Rewards\">\n              <KV k=\"Points outstanding\" v={String(r.points_outstanding ?? 0)} />\n              <KV k=\"Owed if all redeemed\" v={`${money(r.owed_if_all_redeemed)} KPC`} />\n              <KV\n                k=\"Pool surplus\"\n                v={`${money(r.surplus_or_shortfall)} KPC`}\n                bad={n(r.surplus_or_shortfall) < 0}\n              />\n            </Panel>\n          ))}\n\n          {driftRows.length === 0 && (\n            <div className=\"flex items-center justify-center gap-2 py-4 text-[9px] font-mono uppercase tracking-[0.15em] text-[#10B981]\">\n              <Check size={13} /> Every balance matches its ledger\n            </div>\n          )}\n        </div>\n      )}\n\n      {tab === \"kyc\" && kyc && (\n        <div className=\"space-y-3\">\n          {kyc.queue.length === 0 ? (\n            <Empty>Nobody waiting to be verified</Empty>\n          ) : (\n            kyc.queue.map((k, i) => (\n              <div key={i} className=\"bg-[#111827] border border-[#1F2937] rounded-xl p-4\">\n                <div className=\"flex justify-between items-start mb-2\">\n                  <div>\n                    <p className=\"text-sm font-bold\">{String(k.full_name)}</p>\n                    <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mt-0.5\">\n                      {String(k.phone)} · {String(k.tier_now)} → {String(k.tier_wanted)}\n                    </p>\n                  </div>\n                  <span className=\"text-[9px] font-mono uppercase tracking-[0.15em] px-2 py-1 rounded bg-[#1F2937] text-[#94A3B8]\">\n                    {n(k.hours_waiting) < 1 ? \"just now\" : `${Math.round(n(k.hours_waiting))}h`}\n                  </span>\n                </div>\n\n                <div className=\"bg-[#0A0E14] border border-[#1F2937] rounded-lg p-3 mb-3 space-y-1\">\n                  <KV k=\"ID\" v={`${String(k.id_type).replace(/_/g, \" \")} · ${String(k.id_reference ?? \"—\")}`} />\n                  {k.address ? <KV k=\"Address\" v={String(k.address)} /> : null}\n                  {/* Blank is normal — it is optional on the form and asked\n                      for with 'More info' only when the amounts warrant it. */}\n                  <KV k=\"Source of funds\" v={String(k.source_of_funds ?? \"not given\")} />\n                </div>\n\n                <div className=\"grid grid-cols-3 gap-2\">\n                  <Act onClick={() => decideKyc(String(k.id), \"approved\")} busy={working === k.id} tone=\"good\">\n                    Approve\n                  </Act>\n                  <Act onClick={() => decideKyc(String(k.id), \"more_info\")} busy={working === k.id}>\n                    More info\n                  </Act>\n                  <Act onClick={() => decideKyc(String(k.id), \"rejected\")} busy={working === k.id} tone=\"bad\">\n                    Reject\n                  </Act>\n                </div>\n              </div>\n            ))\n          )}\n\n          <Panel title=\"Who is on what\">\n            {kyc.tiers.map((t, i) => (\n              <KV\n                key={i}\n                k={`${String(t.name)} · ${kpcShort(t.daily_kpc)}/day`}\n                v={`${n(t.people)} ${n(t.people) === 1 ? \"person\" : \"people\"}`}\n              />\n            ))}\n          </Panel>\n        </div>\n      )}\n\n      {tab === \"risk\" && risk && (\n        <div className=\"space-y-3\">\n          {risk.queue.length === 0 ? (\n            <Empty>Nothing flagged</Empty>\n          ) : (\n            risk.queue.map((r, i) => (\n              <div\n                key={i}\n                className={`bg-[#111827] border rounded-xl p-4 ${\n                  r.severity === \"high\" ? \"border-[#EF4444]/50\" : \"border-[#1F2937]\"\n                }`}\n              >\n                <div className=\"flex justify-between items-start mb-2\">\n                  <div>\n                    <p className=\"text-sm font-bold capitalize\">\n                      {String(r.kind).replace(/_/g, \" \")}\n                    </p>\n                    <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mt-0.5\">\n                      {String(r.full_name ?? \"unknown\")} · {String(r.phone ?? \"—\")} ·{\" \"}\n                      {String(r.kyc_tier ?? \"—\")}\n                    </p>\n                  </div>\n                  <span\n                    className={`text-[9px] font-mono uppercase tracking-[0.15em] px-2 py-1 rounded ${\n                      r.severity === \"high\"\n                        ? \"bg-[#EF4444]/15 text-[#EF4444]\"\n                        : \"bg-[#1F2937] text-[#94A3B8]\"\n                    }`}\n                  >\n                    {String(r.severity)}\n                  </span>\n                </div>\n\n                <p className=\"text-[10px] font-mono text-[#94A3B8] leading-relaxed mb-3\">\n                  {String(r.detail)}\n                </p>\n\n                {/* Nothing here froze anybody. A flag is a question for a\n                    person, and these two buttons are the answer. */}\n                <div className=\"grid grid-cols-2 gap-2\">\n                  <Act onClick={() => decideRisk(String(r.id), \"cleared\")} busy={working === r.id} tone=\"good\">\n                    Looks fine\n                  </Act>\n                  <Act onClick={() => decideRisk(String(r.id), \"escalated\")} busy={working === r.id} tone=\"bad\">\n                    Escalate\n                  </Act>\n                </div>\n              </div>\n            ))\n          )}\n\n          {risk.recent.length > 0 && (\n            <Panel title=\"Recently closed\">\n              {risk.recent.map((r, i) => (\n                <KV\n                  key={i}\n                  k={String(r.kind).replace(/_/g, \" \")}\n                  v={`${String(r.status)} · ${String(r.note ?? \"\")}`.slice(0, 48)}\n                  bad={r.status === \"escalated\"}\n                />\n              ))}\n            </Panel>\n          )}\n        </div>\n      )}\n\n      {tab === \"reserve\" && reserve && (\n        <div className=\"space-y-5\">\n          {/* Coverage is the only number on this page that can end the company.\n              It leads, and it is red the moment it drops under 100. */}\n          <div\n            className={`rounded-xl p-5 border ${\n              n(reserve.health.coverage_percent) >= 100\n                ? \"bg-[#10B981]/5 border-[#10B981]/30\"\n                : \"bg-[#EF4444]/10 border-[#EF4444]/40\"\n            }`}\n          >\n            <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n              Every KPC backed?\n            </p>\n            <p\n              className={`text-3xl font-black ${\n                n(reserve.health.coverage_percent) >= 100 ? \"text-[#10B981]\" : \"text-[#EF4444]\"\n              }`}\n            >\n              {reserve.health.coverage_percent == null\n                ? \"—\"\n                : `${n(reserve.health.coverage_percent).toFixed(2)}%`}\n            </p>\n            <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] mt-2 leading-relaxed\">\n              {money(reserve.health.total_backing)} held against{\" \"}\n              {money(reserve.health.owed_to_customers)} owed\n            </p>\n          </div>\n\n          {/* Liquid share: the books can balance and a withdrawal still fail. */}\n          {reserve.health.liquid_percent != null &&\n            n(reserve.health.liquid_percent) < n(reserve.health.liquid_floor_percent) && (\n              <div className=\"bg-[#EF4444]/10 border border-[#EF4444]/40 rounded-xl p-4 flex gap-3\">\n                <AlertTriangle size={16} className=\"text-[#EF4444] shrink-0 mt-0.5\" />\n                <p className=\"text-[10px] font-mono text-[#EF4444] uppercase tracking-[0.12em] leading-relaxed\">\n                  Only {n(reserve.health.liquid_percent).toFixed(1)}% liquid, under the{\" \"}\n                  {n(reserve.health.liquid_floor_percent).toFixed(0)}% floor. A withdrawal\n                  could fail even though the books balance.\n                </p>\n              </div>\n            )}\n\n          {/* Currency mismatch. Coverage above is measured at today's rate,\n              so a reserve held entirely in cedis reads 100% right up until\n              the cedi moves — and it has, from ~5.8 to ~12 against the\n              dollar between 2021 and 2024. This panel is the only place\n              that difference is visible. */}\n          {reserveFx?.has_reserve && reserveFx.by_tier && (\n            <>\n              <div\n                className={`rounded-xl p-4 border ${\n                  n(reserveFx.coverage_percent_stressed) >= 100\n                    ? \"bg-[#10B981]/5 border-[#10B981]/30\"\n                    : \"bg-[#EF4444]/10 border-[#EF4444]/40\"\n                }`}\n              >\n                <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n                  Covered after a currency move?\n                </p>\n                <p\n                  className={`text-3xl font-black ${\n                    n(reserveFx.coverage_percent_stressed) >= 100\n                      ? \"text-[#10B981]\"\n                      : \"text-[#EF4444]\"\n                  }`}\n                >\n                  {reserveFx.coverage_percent_stressed == null\n                    ? \"—\"\n                    : `${n(reserveFx.coverage_percent_stressed).toFixed(2)}%`}\n                </p>\n                <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] mt-2 leading-relaxed\">\n                  {reserveFx.stress_case}\n                </p>\n                <p className=\"text-[10px] font-mono text-white uppercase tracking-[0.12em] mt-3 leading-relaxed\">\n                  {reserveFx.verdict}\n                </p>\n              </div>\n\n              <Panel title=\"What the reserve is made of\">\n                <KV\n                  k=\"In USD (the currency owed)\"\n                  v={`${money(reserveFx.by_tier.matched_usd)} · ${n(reserveFx.by_tier.matched_percent).toFixed(1)}%`}\n                  bad={n(reserveFx.by_tier.matched_percent) < 60}\n                />\n                {n(reserveFx.by_tier.hard) > 0 && (\n                  <KV\n                    k=\"Hard currency\"\n                    v={`${money(reserveFx.by_tier.hard)} · ${n(reserveFx.by_tier.hard_percent).toFixed(1)}%`}\n                  />\n                )}\n                <KV\n                  k=\"Soft currency\"\n                  v={`${money(reserveFx.by_tier.soft)} · ${n(reserveFx.by_tier.soft_percent).toFixed(1)}%`}\n                  bad={n(reserveFx.by_tier.soft_percent) > 25}\n                />\n                {n(reserveFx.buffer_needed_usd) > 0 && (\n                  <KV\n                    k=\"Buffer still needed\"\n                    v={`${money(reserveFx.buffer_needed_usd)} — hold ${n(reserveFx.coverage_needed_percent).toFixed(1)}% today`}\n                    bad\n                  />\n                )}\n                {(reserveFx.composition ?? []).map((c, i) => (\n                  <KV\n                    key={i}\n                    k={`${c.currency} (${c.tier})`}\n                    v={\n                      c.cannot_value\n                        ? \"no fresh rate — counts as zero backing\"\n                        : `${money(c.usd_value)} · ${n(c.share_percent).toFixed(1)}%`\n                    }\n                    bad={c.cannot_value}\n                  />\n                ))}\n              </Panel>\n\n              {(reserveFx.breaches ?? []).length > 0 && (\n                <Panel title=\"Policy breaches\">\n                  {(reserveFx.breaches ?? []).map((b, i) => (\n                    <div key={i} className=\"py-2 border-b border-[#1F2937] last:border-0\">\n                      <p className=\"text-[10px] font-bold text-[#EF4444]\">\n                        {b.says} — now {b.actual}\n                      </p>\n                      <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] mt-1\">\n                        {b.fix}\n                      </p>\n                      <p className=\"text-[8px] font-mono text-[#4B5563] tracking-[0.12em] mt-0.5\">\n                        {b.setting}\n                      </p>\n                    </div>\n                  ))}\n                </Panel>\n              )}\n            </>\n          )}\n\n          <Panel title=\"Where the backing sits\">\n            <KV k=\"Liquid\" v={money(reserve.health.liquid)} />\n            <KV k=\"Deployed\" v={money(reserve.health.deployed)} />\n            <KV\n              k=\"Unrealised gain\"\n              v={money(reserve.health.unrealised_gain)}\n              bad={n(reserve.health.unrealised_gain) < 0}\n            />\n            <KV\n              k=\"Surplus\"\n              v={money(reserve.health.surplus_or_shortfall)}\n              bad={n(reserve.health.surplus_or_shortfall) < 0}\n            />\n          </Panel>\n\n          <Panel title=\"Does it pay for itself\">\n            <KV\n              k=\"Verdict\"\n              v={String(reserve.economics.verdict ?? \"—\")}\n              bad={String(reserve.economics.verdict ?? \"\").startsWith(\"LOSING\")}\n            />\n            <KV k=\"Savings book\" v={`${money(reserve.economics.savings_book)} KPC`} />\n            <KV\n              k=\"Owed to savers / year\"\n              v={`${money(reserve.economics.owed_to_savers_per_year)} KPC`}\n            />\n            <KV k=\"Reserve deployed\" v={money(reserve.economics.reserve_deployed)} />\n            {reserve.economics.reserve_yield_percent != null && (\n              <KV\n                k=\"Reserve yield\"\n                v={`${n(reserve.economics.reserve_yield_percent).toFixed(2)}% over ${n(\n                  reserve.economics.days_deployed,\n                ).toFixed(0)} days`}\n              />\n            )}\n            <KV k=\"Fee income to date\" v={money(reserve.economics.fee_income_to_date)} />\n          </Panel>\n\n          {reserve.deployments.length > 0 && (\n            <Panel title=\"Deployments\">\n              {reserve.deployments.map((d, i) => (\n                <KV\n                  key={i}\n                  k={String(d.name)}\n                  v={`${money(d.worth_now)} · ${n(d.unrealised) >= 0 ? \"+\" : \"\"}${money(\n                    d.unrealised,\n                  )}`}\n                  bad={n(d.unrealised) < 0}\n                />\n              ))}\n            </Panel>\n          )}\n        </div>\n      )}\n\n      {tab === \"rates\" && rates && (\n        <div className=\"space-y-5\">\n          <Panel title=\"What funds what\">\n            {rates.yields.map((y, i) => (\n              <KV\n                key={i}\n                k={`${y.bucket} (${y.basis})`}\n                v={`${(n(y.yield_bps) / 100).toFixed(2)}%`}\n              />\n            ))}\n          </Panel>\n\n          {rates.rates.map((r, i) => {\n            const losing = String(r.verdict ?? \"\").startsWith(\"LOSING\");\n            return (\n              <div\n                key={i}\n                className={`bg-[#111827] border rounded-xl p-4 ${\n                  losing ? \"border-[#EF4444]/50\" : \"border-[#1F2937]\"\n                }`}\n              >\n                <div className=\"flex justify-between items-start mb-2\">\n                  <div>\n                    <p className=\"text-sm font-bold capitalize\">{String(r.product)}</p>\n                    <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mt-0.5\">\n                      funded from {String(r.funded_from)} · {String(r.basis)}\n                    </p>\n                  </div>\n                  <p\n                    className={`text-xl font-black ${losing ? \"text-[#EF4444]\" : \"text-[#FDB813]\"}`}\n                  >\n                    {(n(r.current_bps) / 100).toFixed(2)}%\n                  </p>\n                </div>\n                <KV k=\"Funding yield\" v={`${(n(r.yield_bps) / 100).toFixed(2)}%`} />\n                <KV k=\"Most it can pay\" v={`${(n(r.max_bps) / 100).toFixed(2)}%`} />\n                <KV k=\"Target, with margin\" v={`${(n(r.ceiling_bps) / 100).toFixed(2)}%`} />\n                <p\n                  className={`text-[10px] font-mono uppercase tracking-[0.12em] mt-2 ${\n                    losing ? \"text-[#EF4444]\" : \"text-[#94A3B8]\"\n                  }`}\n                >\n                  {String(r.verdict)}\n                </p>\n              </div>\n            );\n          })}\n\n          {rates.history.length > 0 && (\n            <Panel title=\"Rate changes\">\n              {rates.history.map((h, i) => (\n                <KV\n                  key={i}\n                  k={`${h.product_id} ${h.from_bps == null ? \"\" : `${n(h.from_bps) / 100}% →`} ${\n                    n(h.to_bps) / 100\n                  }%`}\n                  v={h.forced ? `forced · ${String(h.reason ?? \"\")}` : \"within ceiling\"}\n                  bad={Boolean(h.forced)}\n                />\n              ))}\n            </Panel>\n          )}\n        </div>\n      )}\n\n      {tab === \"ops\" && ops && (\n        <div className=\"space-y-5\">\n          {/* Only the currencies that are actually switched on. Listing all\n              96 put 94 red \"off\" lines on the screen for currencies nobody\n              has enabled, which buried the one line that matters: an active\n              rate going stale. fx_rate() fails closed, so a stale rate stops\n              payments in that currency. */}\n          {/* Why each currency is not live. The old panel could say a\n              currency was off but not what was blocking it, so 94 rows of\n              \"off\" looked like a setting nobody had flipped rather than a\n              closed loop: no rate meant never refreshed, and never refreshed\n              meant no rate. (035) */}\n          {currencies && (\n            <Panel title=\"Currency pipeline\">\n              <KV k=\"On the books\" v={String(currencies.summary.total)} />\n              <KV\n                k=\"Switched on\"\n                v={String(currencies.summary.switched_on)}\n                bad={currencies.summary.switched_on < 3}\n              />\n              <KV k=\"Can be priced\" v={String(currencies.summary.can_be_valued)} />\n              <KV\n                k=\"Can take money in\"\n                v={String(currencies.summary.can_take_money_in)}\n                bad={currencies.summary.can_take_money_in === 0}\n              />\n              {currencies.summary.rate_too_old > 0 && (\n                <KV\n                  k=\"Live but rate too old\"\n                  v={`${currencies.summary.rate_too_old} — payments in these are refused`}\n                  bad\n                />\n              )}\n              {currencies.summary.no_rate_yet > 0 && (\n                <KV\n                  k=\"Never had a rate\"\n                  v={`${currencies.summary.no_rate_yet} — run the FX refresh`}\n                  bad\n                />\n              )}\n              {Object.entries(\n                (currencies.rows ?? []).reduce<Record<string, number>>((acc, r) => {\n                  acc[r.blocked_by] = (acc[r.blocked_by] ?? 0) + 1;\n                  return acc;\n                }, {}),\n              )\n                .sort((a, b) => b[1] - a[1])\n                .map(([reason, count]) => (\n                  <KV key={reason} k={reason} v={String(count)} />\n                ))}\n            </Panel>\n          )}\n\n          <Panel title=\"Exchange rates\">\n            {ops.fx\n              .filter((f) => f.state !== \"switched off\")\n              .map((f, i) => {\n                const hours = Math.round(n(f.age_minutes) / 60);\n                const pegged = f.state === \"the peg\";\n                // 48h is where fx_rate() refuses. Warn with a day to spare.\n                const stale = !pegged && hours >= 24;\n                return (\n                  <KV\n                    key={i}\n                    k={String(f.code)}\n                    v={`${n(f.units_per_usd).toLocaleString()} / $ · ${\n                      pegged ? \"pegged\" : `${hours}h old`\n                    }`}\n                    bad={stale}\n                  />\n                );\n              })}\n            {(() => {\n              const off = ops.fx.filter((f) => f.state === \"switched off\").length;\n              const stale = ops.fx.filter(\n                (f) => f.state === \"usable\" && n(f.age_minutes) >= 24 * 60,\n              ).length;\n              return (\n                <>\n                  {stale > 0 && (\n                    <p className=\"text-[9px] font-mono text-[#EF4444] uppercase tracking-[0.12em] mt-3 pt-3 border-t border-[#1F2937] leading-relaxed\">\n                      {stale} rate{stale === 1 ? \"\" : \"s\"} over a day old. At 48 hours\n                      payments in {stale === 1 ? \"that currency\" : \"those currencies\"}{\" \"}\n                      stop.\n                    </p>\n                  )}\n                  {off > 0 && (\n                    <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] mt-3 pt-3 border-t border-[#1F2937]\">\n                      {off} other currencies not switched on\n                    </p>\n                  )}\n                </>\n              );\n            })()}\n          </Panel>\n\n          <Panel title=\"Nightly jobs\">\n            {ops.jobs.length === 0 ? (\n              <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.15em] py-2\">\n                No runs recorded yet\n              </p>\n            ) : (\n              ops.jobs.map((j, i) => (\n                <KV\n                  key={i}\n                  k={`${j.step ?? j.job} · ${since(String(j.ran_at))}`}\n                  v={j.ok ? `ok · ${n(j.ms)}ms` : String(j.detail ?? \"failed\")}\n                  bad={!j.ok}\n                />\n              ))\n            )}\n          </Panel>\n        </div>\n      )}\n    </Shell>\n  );\n}\n\nfunction Shell({ children }: { children: React.ReactNode }) {\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white font-sans p-5 selection:bg-[#AA771C]/30\">\n      <div className=\"max-w-xl mx-auto\">\n        <div className=\"flex items-center gap-3 mb-6\">\n          <Link\n            href=\"/wallet\"\n            className=\"text-[#94A3B8] hover:text-[#FDB813] p-2 bg-[#1F2937] rounded-lg border border-[#374151]\"\n          >\n            <ArrowLeft size={18} />\n          </Link>\n          <AppMenu />\n          <h1 className=\"text-lg font-black uppercase tracking-widest\">Operations</h1>\n        </div>\n        {children}\n      </div>\n    </div>\n  );\n}\n\nconst kpcShort = (v: unknown) =>\n  `${Number(v ?? 0).toLocaleString(undefined, { maximumFractionDigits: 0 })} KPC`;\n\nfunction Panel({ title, children }: { title: string; children: React.ReactNode }) {\n  return (\n    <div className=\"bg-[#111827] border border-[#1F2937] rounded-xl p-4\">\n      <p className=\"text-[9px] font-mono text-[#FDB813] uppercase tracking-[0.2em] mb-3\">\n        {title}\n      </p>\n      <div className=\"space-y-1.5\">{children}</div>\n    </div>\n  );\n}\n\nfunction KV({ k, v, bad }: { k: string; v: string; bad?: boolean }) {\n  return (\n    <div className=\"flex justify-between items-baseline gap-3\">\n      <span className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em]\">{k}</span>\n      <span\n        className={`text-xs font-mono font-bold ${bad ? \"text-[#EF4444]\" : \"text-white\"}`}\n      >\n        {v}\n      </span>\n    </div>\n  );\n}\n\nfunction Stat({ label, value, bad }: { label: string; value: string; bad?: boolean }) {\n  return (\n    <div className=\"bg-[#111827] border border-[#1F2937] rounded-xl p-3\">\n      <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mb-1\">\n        {label}\n      </p>\n      <p className={`text-sm font-black ${bad ? \"text-[#EF4444]\" : \"text-white\"}`}>{value}</p>\n    </div>\n  );\n}\n\nfunction Act({\n  children,\n  onClick,\n  busy,\n  tone,\n}: {\n  children: React.ReactNode;\n  onClick: () => void;\n  busy: boolean;\n  tone?: \"good\" | \"bad\";\n}) {\n  const colour =\n    tone === \"good\"\n      ? \"hover:bg-[#10B981]/15 hover:border-[#10B981]/50 hover:text-[#10B981]\"\n      : tone === \"bad\"\n        ? \"hover:bg-[#EF4444]/15 hover:border-[#EF4444]/50 hover:text-[#EF4444]\"\n        : \"hover:bg-[#FDB813]/10 hover:border-[#FDB813]/50 hover:text-[#FDB813]\";\n  return (\n    <button\n      disabled={busy}\n      onClick={onClick}\n      className={`flex items-center justify-center gap-1.5 py-2.5 bg-[#1F2937] border border-[#374151] text-[#94A3B8] rounded-lg text-[9px] font-mono uppercase tracking-[0.12em] transition-colors disabled:opacity-40 ${colour}`}\n    >\n      {busy && <Loader2 size={11} className=\"animate-spin\" />}\n      {children}\n    </button>\n  );\n}\n\nfunction Empty({ children }: { children: React.ReactNode }) {\n  return (\n    <div className=\"flex items-center justify-center gap-2 py-12 text-[10px] font-mono uppercase tracking-[0.15em] text-[#4B5563]\">\n      <Check size={14} /> {children}\n    </div>\n  );\n}\n");

write("app/api/cron/fx/route.ts", "import { NextResponse } from \"next/server\";\nimport { supabaseAdmin } from \"@/app/lib/supabaseServer\";\n\n// Daily FX refresh.\n//\n// WHY THIS EXISTS\n//\n// fx_rate() fails closed: past price_max_age it raises rather than guessing.\n// That is the right design, but it means a rate nobody refreshes does not\n// degrade — it stops payments in that currency outright. Until now nothing\n// refreshed anything. The GHS rate was set by hand and was counting down.\n//\n// WHY A BAD RATE IS WORSE THAN A STALE ONE\n//\n// A stale rate stops payments, loudly. A WRONG rate prices every payment\n// wrongly, silently, until somebody notices the money does not add up. So\n// this refuses more often than it accepts:\n//\n//   - the provider must say it succeeded\n//   - the rate must be a finite number greater than zero\n//   - it must be within MAX_MOVE of the rate we already hold\n//\n// A currency that fails any of those keeps its old rate and is reported. If\n// the old rate then goes stale, payments stop — which is the correct failure,\n// because at that point we genuinely do not know the price.\n\nexport const dynamic = \"force-dynamic\";\n\n// A real currency can move several percent in a day. It does not move 25%\n// without something being wrong with either the country or the feed, and\n// this cannot tell which — so it stops and asks for a human.\nconst MAX_MOVE = 0.25;\n\nconst PROVIDER = \"https://open.er-api.com/v6/latest/USD\";\n\ntype Outcome = {\n  code: string;\n  from: number | null;\n  to: number | null;\n  status: \"updated\" | \"seeded\" | \"unchanged\" | \"rejected\" | \"missing\";\n  why?: string;\n};\n\nexport async function GET(request: Request) {\n  // Vercel Cron sends this header when CRON_SECRET is set. Without the check\n  // the endpoint is a public button that repoints every exchange rate.\n  const secret = process.env.CRON_SECRET;\n  if (secret) {\n    const auth = request.headers.get(\"authorization\");\n    if (auth !== `Bearer ${secret}`) {\n      return NextResponse.json({ error: \"Unauthorized\" }, { status: 401 });\n    }\n  }\n\n  let payload: { result?: string; rates?: Record<string, number> };\n  try {\n    const res = await fetch(PROVIDER, { cache: \"no-store\" });\n    if (!res.ok) {\n      return NextResponse.json(\n        { error: `rate provider returned ${res.status}`, updated: 0 },\n        { status: 502 },\n      );\n    }\n    payload = await res.json();\n  } catch (err) {\n    console.error(\"fx cron: provider unreachable\", err);\n    return NextResponse.json({ error: \"rate provider unreachable\", updated: 0 }, { status: 502 });\n  }\n\n  if (payload.result && payload.result !== \"success\") {\n    return NextResponse.json({ error: `provider said ${payload.result}`, updated: 0 }, { status: 502 });\n  }\n  const rates = payload.rates;\n  if (!rates || typeof rates !== \"object\") {\n    return NextResponse.json({ error: \"provider returned no rates\", updated: 0 }, { status: 502 });\n  }\n\n  // EVERY currency on the books, not just the switched-on ones.\n  //\n  // This used to intersect fx_rates with the active currencies, on the\n  // reasoning that writing rates for currencies nothing can be charged in\n  // widens the blast radius of a bad feed for no benefit. The benefit turned\n  // out to be the whole product. That filter was a closed loop:\n  //\n  //   a currency with no rate was never refreshed, so it never got a rate\n  //   fx_rate() raises for a switched-off currency, so it could not be\n  //   switched on until it had one\n  //\n  // Ninety-four currencies sat in the table unable to escape it, and the\n  // landing page printed \"Currencies: 1\" under \"Send Globally\" as a result.\n  //\n  // The blast-radius worry is still answered, just not by this filter: a\n  // rate only decides what KobPay can quote, hold and send. Taking money in\n  // additionally needs an active payment provider carrying the code\n  // (chargeable_currencies), and widening rates does not add one.\n  const [{ data: held, error: heldErr }, { data: known, error: knownErr }] = await Promise.all([\n    supabaseAdmin.from(\"fx_rates\").select(\"currency, units_per_usd\"),\n    supabaseAdmin.from(\"currencies\").select(\"code, active\"),\n  ]);\n\n  if (heldErr || knownErr) {\n    console.error(\"fx cron: cannot read current rates\", heldErr ?? knownErr);\n    return NextResponse.json({ error: \"cannot read current rates\", updated: 0 }, { status: 500 });\n  }\n\n  const prevByCode = new Map(\n    (held ?? []).map((r) => [String(r.currency), Number(r.units_per_usd)]),\n  );\n\n  const outcomes: Outcome[] = [];\n\n  for (const row of known ?? []) {\n    const code = String(row.code);\n\n    // USD is the peg, not a quote. Nothing to refresh.\n    if (code === \"USD\") continue;\n\n    const next = Number(rates[code]);\n    const prev = prevByCode.has(code) ? Number(prevByCode.get(code)) : NaN;\n\n    if (!Number.isFinite(next) || next <= 0) {\n      outcomes.push({\n        code,\n        from: Number.isFinite(prev) ? prev : null,\n        to: null,\n        status: \"missing\",\n        why: \"provider has no usable rate\",\n      });\n      continue;\n    }\n\n    if (Number.isFinite(prev) && prev > 0) {\n      const move = Math.abs(next - prev) / prev;\n      if (move > MAX_MOVE) {\n        outcomes.push({\n          code,\n          from: prev,\n          to: next,\n          status: \"rejected\",\n          why: `moved ${(move * 100).toFixed(1)}% — kept the old rate`,\n        });\n        continue;\n      }\n      // Writing an identical rate every day buries real changes in history.\n      if (move === 0) {\n        outcomes.push({ code, from: prev, to: next, status: \"unchanged\" });\n        continue;\n      }\n    }\n\n    const { error } = await supabaseAdmin.rpc(\"fx_set_rate\", {\n      p_currency: code,\n      p_units_per_usd: next,\n      p_source: \"open.er-api.com daily\",\n    });\n\n    if (error) {\n      outcomes.push({\n        code,\n        from: Number.isFinite(prev) ? prev : null,\n        to: next,\n        status: \"rejected\",\n        why: error.message,\n      });\n      continue;\n    }\n    outcomes.push({\n      code,\n      from: Number.isFinite(prev) ? prev : null,\n      to: next,\n      // A currency getting its first rate is worth telling apart from one\n      // being refreshed: it is a currency entering the product.\n      status: Number.isFinite(prev) ? \"updated\" : \"seeded\",\n    });\n  }\n\n  // Now that rates exist, switch on whatever has become usable. Holding and\n  // pricing only — chargeable_currencies() still gates taking money in. (035)\n  let activated: unknown = null;\n  const { data: act, error: actErr } = await supabaseAdmin.rpc(\"activate_priced_currencies\");\n  if (actErr) {\n    console.error(\"fx cron: could not activate priced currencies\", actErr);\n  } else {\n    activated = act;\n  }\n\n  const updated = outcomes.filter((o) => o.status === \"updated\").length;\n  const seeded = outcomes.filter((o) => o.status === \"seeded\").length;\n  const problems = outcomes.filter((o) => o.status === \"rejected\" || o.status === \"missing\");\n\n  // Rejections are the interesting case: the rate is now ageing toward the\n  // point where it stops payments, and only a human can decide why the feed\n  // disagreed with us.\n  if (problems.length > 0) {\n    console.error(\"fx cron: rates not refreshed\", problems);\n  }\n\n  return NextResponse.json({\n    updated,\n    seeded,\n    activated,\n    problems: problems.length,\n    outcomes,\n    at: new Date().toISOString(),\n  });\n}\n");

write("app/dashboard/ClientDashboard.tsx", "// app/dashboard/ClientDashboard.tsx\n\"use client\";\n\nimport React, { useEffect, useState, useRef } from 'react';\nimport Link from 'next/link';\nimport { usePathname } from 'next/navigation';\nimport { motion, AnimatePresence, useMotionValue, useTransform, animate } from 'framer-motion';\nimport { translations, LanguageCode } from '../translations';\nimport AppMenu from '../components/AppMenu';\nimport { \n  LayoutDashboard, Search, Wallet, TrendingUp, Send, \n  ShoppingCart, BarChart2, Layers, Code, Shield, User, Globe,\n  Activity, Globe2, Menu, X, ChevronDown, ChevronRight, Zap, Lock, Server, Coins,\n  BarChart, PieChart, Users, HardDrive, Loader2,\n  PiggyBank, LineChart as LineChartIcon, Receipt, ShieldCheck, Store, Scale, Gauge\n} from 'lucide-react';\nimport { \n  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend \n} from 'recharts';\nimport { ConnectButton } from '@rainbow-me/rainbowkit';\nimport toast, { Toaster } from 'react-hot-toast';\nimport BuyKpcModal from '../components/BuyKpcModal';\nimport { supabase } from '../lib/supabaseClient';\n\n// --- HYDRATION SHIELD ---\nconst useIsMounted = () => {\n  const [mounted, setMounted] = useState(false);\n  useEffect(() => setMounted(true), []);\n  return mounted;\n};\n\n// --- THE ENGINE: ROLLING MONOSPACE NUMBERS ---\nfunction RollingNum({ value, decimals = 0, prefix = \"\", suffix = \"\" }: { value: number, decimals?: number, prefix?: string, suffix?: string }) {\n  const count = useMotionValue(0);\n  const rounded = useTransform(count, (latest) => \n    `${prefix}${new Intl.NumberFormat('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals }).format(latest)}${suffix}`\n  );\n  useEffect(() => {\n    const controls = animate(count, value, { duration: 2.5, ease: [0.16, 1, 0.3, 1] });\n    return controls.stop;\n  }, [value, count]);\n  return <motion.span className=\"font-mono tracking-tighter\">{rounded}</motion.span>;\n}\n\n// --- INITIAL CHART DATA ---\nconst initialChartData = [\n  { month: 'Jan 24', KPC: 1.00, GHS: 1.00, NGN: 1.00, ZAR: 1.00 },\n  { month: 'Apr 24', KPC: 1.00, GHS: 0.88, NGN: 0.75, ZAR: 0.92 },\n  { month: 'Jul 24', KPC: 1.00, GHS: 0.76, NGN: 0.55, ZAR: 0.85 },\n  { month: 'Oct 24', KPC: 1.00, GHS: 0.65, NGN: 0.40, ZAR: 0.78 },\n  { month: 'Jan 25', KPC: 1.00, GHS: 0.60, NGN: 0.35, ZAR: 0.75 },\n  { month: 'Current', KPC: 1.00, GHS: 0.55, NGN: 0.30, ZAR: 0.70 },\n];\n\nconst initialTxns = [\n  { id: \"tx1\", hash: \"0x8f...3c9a\", from: \"0x12...99a1\", to: \"0x44...bb2c\", amount: 1500, type: \"TRANSFER\", app: \"KobPay Coins\", time: \"Just now\" },\n  { id: \"tx2\", hash: \"0x2a...11f8\", from: \"0x77...ee33\", to: \"0x99...dd44\", amount: 32, type: \"SUBSCRIPTION\", app: \"KobBot\", time: \"2s ago\" },\n  { id: \"tx3\", hash: \"0x9c...bb21\", from: \"0x22...cc11\", to: \"0x55...ff88\", amount: 45000, type: \"ESCROW\", app: \"Ready Markets\", time: \"5s ago\" },\n  { id: \"tx4\", hash: \"0x1d...aa44\", from: \"0x88...dd22\", to: \"0x33...aa99\", amount: 250, type: \"REWARD\", app: \"KobPlay\", time: \"8s ago\" },\n  { id: \"tx5\", hash: \"0x5e...cc77\", from: \"0x44...aa55\", to: \"0x11...bb66\", amount: 8900, type: \"TRANSFER\", app: \"Direct\", time: \"12s ago\" },\n];\n\n// Was six invented products carrying invented metrics, scrolling across the\n// top of a live payments site:\n//\n//   KobBot 2.0 — 2,341 active today      Axiom Oracle — 892 users today\n//   KobPlay — 45,230 KC earned           RANKR LIVE — 12,450 rankings\n//   Ready Markets — 1,204 KPC escrow     AegisProp — 14,000 KPC settled\n//\n// None of those apps exist. Two apps are registered on the rail, and neither\n// is named there. A regulator reading that banner alongside the ledger finds\n// six products and ~76,000 KPC of activity that cannot be reconciled to\n// anything — which is a representation, not decoration.\n//\n// Replaced with facts the ledger can produce. Anything still at zero is left\n// out rather than printed as \"0 countries\", so the banner is short before\n// launch and grows on its own.\nconst staticTickerItems = [\n  \"⚡ 1 KPC = $1.00, always\",\n  \"💸 Sending KPC is free\",\n  \"🔍 Reserve published on the Ledger page\",\n];\n\n// WHAT THESE USED TO SAY\n//\n// Every one of these was crypto-speak, and several were untrue of KobPay:\n// \"aggregate price feed from decentralized nodes\" (there are no nodes, the\n// price is fixed at a dollar by design), \"live status of validators and\n// consensus health\" (no validators), \"average gas cost\" (no gas — sending is\n// free), \"one currency for all integrated dApps\" (they are apps), \"Mint\n// Sovereign Asset\", \"Proof-of-Engagement\", \"Token Emission\".\n//\n// A customer in New York, Accra or Lagos has to be able to read these. The\n// test applied to every line: would somebody who has never heard of a\n// stablecoin know what this means, and is it actually true of KobPay?\nconst drawerContent: Record<string, any> = {\n  \"buy\": { title: \"Add money\", subtitle: \"Turn cash into KPC\", icon: <Coins className=\"text-[#FDB813]\" size={24} />, color: \"text-[#FDB813]\", bg: \"bg-[#FDB813]/10\", border: \"border-[#FDB813]/30\", details: \"Pay with mobile money or a card and the same value lands in your wallet as KPC. One KPC costs one dollar.\", metrics: [] },\n  \"live_price\": { title: \"What 1 KPC is worth\", subtitle: \"Always one dollar\", icon: <Activity className=\"text-[#10B981]\" size={24} />, color: \"text-[#10B981]\", bg: \"bg-[#10B981]/10\", border: \"border-[#10B981]/30\", details: \"KPC does not go up and down. One KPC is one US dollar, and we hold money to back every one that exists. The Ledger page shows what we hold.\", metrics: [] },\n  \"volume\": { title: \"Moved in 24 hours\", subtitle: \"Between wallets\", icon: <BarChart className=\"text-[#22D3EE]\" size={24} />, color: \"text-[#22D3EE]\", bg: \"bg-[#22D3EE]/10\", border: \"border-[#22D3EE]/30\", details: \"How much KPC people sent each other in the last day, counted from the ledger.\", metrics: [] },\n  \"market_cap\": { title: \"KPC in existence\", subtitle: \"All wallets and savings\", icon: <PieChart className=\"text-[#FDB813]\" size={24} />, color: \"text-[#FDB813]\", bg: \"bg-[#FDB813]/10\", border: \"border-[#FDB813]/30\", details: \"Every KPC that exists. Each one is a dollar we owe somebody, so this is also the size of what we have to back.\", metrics: [] },\n  \"txns\": { title: \"Payments today\", subtitle: \"In the last 24 hours\", icon: <Zap className=\"text-[#8B5CF6]\" size={24} />, color: \"text-[#8B5CF6]\", bg: \"bg-[#8B5CF6]/10\", border: \"border-[#8B5CF6]/30\", details: \"How many payments went through in the last day.\", metrics: [] },\n  \"holders\": { title: \"People holding KPC\", subtitle: \"Wallets with money in them\", icon: <Users className=\"text-[#F472B6]\" size={24} />, color: \"text-[#F472B6]\", bg: \"bg-[#F472B6]/10\", border: \"border-[#F472B6]/30\", details: \"How many wallets have some KPC in them right now.\", metrics: [] },\n  \"network\": { title: \"Countries\", subtitle: \"Where you can send\", icon: <Globe2 className=\"text-[#10B981]\" size={24} />, color: \"text-[#10B981]\", bg: \"bg-[#10B981]/10\", border: \"border-[#10B981]/30\", details: \"You can send KPC to a phone number in any of these countries. Putting money in needs a payment provider that covers your country, which is fewer places for now.\", metrics: [] },\n  \"fee\": { title: \"What sending costs\", subtitle: \"Nothing\", icon: <Code className=\"text-[#94A3B8]\" size={24} />, color: \"text-[#94A3B8]\", bg: \"bg-[#1F2937]/50\", border: \"border-[#374151]/50\", details: \"Sending KPC to another person is free. Moving money out to a bank or mobile money has a small fee, and you see it before you confirm.\", metrics: [] },\n  \"circulating\": { title: \"Held by people\", subtitle: \"Not counting savings\", icon: <Layers className=\"text-[#FDB813]\" size={24} />, color: \"text-[#FDB813]\", bg: \"bg-[#FDB813]/10\", border: \"border-[#FDB813]/30\", details: \"KPC sitting in everyday wallets, ready to spend. Money locked in savings plans is counted separately.\", metrics: [] },\n  \"global\": { title: \"Send anywhere\", subtitle: \"A phone number is enough\", icon: <Globe2 className=\"text-[#22D3EE]\" size={24} />, color: \"text-[#22D3EE]\", bg: \"bg-[#22D3EE]/10\", border: \"border-[#22D3EE]/30\", details: \"You need the other person\\u2019s phone number, not their bank details. It arrives straight away, and it does not cost anything to send.\", metrics: [] },\n  \"hedge\": { title: \"Protect your savings\", subtitle: \"Hold dollars instead\", icon: <Shield className=\"text-[#FDB813]\" size={24} />, color: \"text-[#FDB813]\", bg: \"bg-[#FDB813]/10\", border: \"border-[#FDB813]/30\", details: \"When your local currency loses value against the dollar, money you hold as KPC keeps its dollar value. That is the whole idea.\", metrics: [] },\n  \"earn\": { title: \"Earn points\", subtitle: \"For using KobPay\", icon: <TrendingUp className=\"text-[#10B981]\" size={24} />, color: \"text-[#10B981]\", bg: \"bg-[#10B981]/10\", border: \"border-[#10B981]/30\", details: \"You collect KC points as you use KobPay. Points are not money and do not hold a value \\u2014 you swap them for KPC when you have enough.\", metrics: [] },\n  \"pay\": { title: \"Pay with KPC\", subtitle: \"Shops and apps\", icon: <ShoppingCart className=\"text-[#8B5CF6]\" size={24} />, color: \"#8B5CF6\", bg: \"bg-[#8B5CF6]/10\", border: \"border-[#8B5CF6]/30\", details: \"Any business or app signed up to KobPay can take KPC, so the same balance works everywhere.\", metrics: [] },\n  \"protect\": { title: \"Keep your value\", subtitle: \"Swap into dollars\", icon: <Lock className=\"text-[#10B981]\" size={24} />, color: \"text-[#10B981]\", bg: \"bg-[#10B981]/10\", border: \"border-[#10B981]/30\", details: \"Change your local currency into KPC and it stops tracking the local currency. A dollar today is still a dollar later.\", metrics: [] }\n};\n\nexport default function KPCSovereignDashboard() {\n  const mounted = useIsMounted();\n  const pathname = usePathname(); \n  const [isBuyModalOpen, setIsBuyModalOpen] = useState(false);\n  const [currentUser, setCurrentUser] = useState<{ id: string; email: string; accessToken: string } | null>(null);\n\n  useEffect(() => {\n    supabase.auth.getSession().then(({ data }) => {\n      if (data.session) {\n        setCurrentUser({\n          id: data.session.user.id,\n          email: data.session.user.email ?? '',\n          accessToken: data.session.access_token,\n        });\n      }\n    });\n  }, []);\n  \n  const [liveChartData, setLiveChartData] = useState(initialChartData);\n  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);\n  // Staff-only nav entry. am_i_staff() is the same gate the admin readers\n  // use, so this can never show a door that will not open — and the page\n  // enforces it server-side regardless of what the client believes.\n  const [isStaff, setIsStaff] = useState(false);\n\n  useEffect(() => {\n    supabase.auth.getSession().then(({ data }) => {\n      if (!data.session) return;\n      supabase.rpc(\"am_i_staff\").then(({ data: staff }) => setIsStaff(Boolean(staff)));\n    });\n  }, []);\n  const [activeDrawer, setActiveDrawer] = useState<string | null>(null);\n  const [liveTxns, setLiveTxns] = useState(initialTxns);\n\n  // Was: the latest Ethereum block height, polled from a public RPC and\n  // printed as \"MAINNET: #26227870\" — a number from a chain KobPay does not\n  // run, has no account on, and settles nothing through. \"NETWORK: OFFLINE\"\n  // meant that RPC was unreachable, which said nothing about whether KobPay\n  // was up. Now it reports whether our own ledger answered.\n  const [ledgerLive, setLedgerLive] = useState<boolean | null>(null);\n  // These were hardcoded: 84,210 holders, $12.4M volume, 142,850 daily\n  // transactions, 54 corridors, 23 apps, 450 merchants. The ledger said 2\n  // profiles and 2 apps. Published figures a regulator can test against the\n  // database are representations, not marketing — so they now come from\n  // public_stats(), which counts from the ledger at call time.\n  //\n  // Zeros until Paystack settles the first real deposit. That is the correct\n  // reading, and every one of them moves the day it does.\n  const [networkStats, setNetworkStats] = useState({\n    price: 1.00,\n    volume: 0,\n    marketCap: 0,\n    txnsToday: 0,\n    holders: 0,\n    circulating: 0,\n    corridors: 0,\n    countries: 0,\n    transferFeeBps: 0,\n    activeApps: 0,\n    merchants: 0\n  });\n\n  useEffect(() => {\n    supabase.rpc(\"public_stats\").then(({ data }) => {\n      if (!data) { setLedgerLive(false); return; }\n      setLedgerLive(true);\n      const d = data as Record<string, number>;\n      setNetworkStats((prev) => ({\n        ...prev,\n        price: Number(d.price_usd ?? 1),\n        volume: Number(d.volume_24h ?? 0),\n        // Market cap for a pegged unit is simply what exists, times $1.\n        marketCap: Number(d.total_supply ?? 0),\n        txnsToday: Number(d.transactions_24h ?? 0),\n        holders: Number(d.holders ?? 0),\n        circulating: Number(d.in_circulation ?? 0),\n        // The \"Send Globally\" card was reading currencies_supported, which\n        // counts what you can FUND an account in — one provider, Paystack,\n        // GHS, so: 1. Sending has nothing to do with Paystack; KPC moves on\n        // our own ledger between two phone numbers. currencies_priced is the\n        // number that belongs under a claim about sending. (033)\n        corridors: Number(d.currencies_priced ?? d.currencies_supported ?? 0),\n        countries: Number(d.countries ?? 0),\n        transferFeeBps: Number(d.transfer_fee_bps ?? 0),\n        activeApps: Number(d.apps ?? 0),\n        merchants: Number(d.merchants ?? 0),\n      }));\n    });\n  }, []);\n\n  // Only facts with a number behind them. A zero is dropped, not printed.\n  const tickerItems = React.useMemo(() => {\n    const live: string[] = [];\n    if (networkStats.countries > 0) live.push(`🌍 ${networkStats.countries} countries`);\n    if (networkStats.corridors > 0) live.push(`💱 ${networkStats.corridors} currencies priced`);\n    if (networkStats.holders > 0) live.push(`👥 ${networkStats.holders.toLocaleString()} wallets holding KPC`);\n    if (networkStats.activeApps > 0) live.push(`📱 ${networkStats.activeApps} apps on the rail`);\n    if (networkStats.merchants > 0) live.push(`🛒 ${networkStats.merchants} businesses accepting KPC`);\n    return [...staticTickerItems, ...live];\n  }, [networkStats]);\n\n  const [currentLang, setCurrentLang] = useState<LanguageCode>('en');\n  const [isLangMenuOpen, setIsLangMenuOpen] = useState(false);\n  const t = translations[currentLang];\n\n  // REMOVED: a 12-second poll of a public Ethereum RPC that, on every tick,\n  // did this to the figures 025 had just made honest —\n  //\n  //   txnsToday: prev.txnsToday + Math.floor(Math.random() * 5),\n  //   holders:   prev.holders   + (blockNum % 5 === 0 ? 1 : 0),\n  //   volume:    prev.volume    + (Math.random() * 500)\n  //\n  // So the counts came from the ledger and were then walked upward by random\n  // numbers, every twelve seconds, for as long as the tab stayed open. Leave\n  // the page open an hour and it invents roughly 150,000 KPC of volume and\n  // several hundred payments that never happened. That is the exact thing\n  // 025 was written to stop, and it was undoing it on the client.\n  //\n  // Nothing replaces it. The figures move when the ledger moves.\n  useEffect(() => {\n    const refresh = setInterval(() => {\n      supabase.rpc(\"public_stats\").then(({ data }) => {\n        if (!data) return;\n        const d = data as Record<string, number>;\n        setNetworkStats((prev) => ({\n          ...prev,\n          volume: Number(d.volume_24h ?? prev.volume),\n          txnsToday: Number(d.transactions_24h ?? prev.txnsToday),\n          holders: Number(d.holders ?? prev.holders),\n          circulating: Number(d.in_circulation ?? prev.circulating),\n          marketCap: Number(d.total_supply ?? prev.marketCap),\n        }));\n      });\n    }, 60000);\n    return () => clearInterval(refresh);\n  }, []);\n\n  useEffect(() => {\n    const chartInterval = setInterval(() => {\n      setLiveChartData(prev => {\n        const newData = [...prev];\n        const last = { ...newData[newData.length - 1] };\n        last.GHS = Math.max(0.1, last.GHS + (Math.random() * 0.02 - 0.01));\n        last.NGN = Math.max(0.1, last.NGN + (Math.random() * 0.02 - 0.01));\n        last.ZAR = Math.max(0.1, last.ZAR + (Math.random() * 0.02 - 0.01));\n        newData[newData.length - 1] = last;\n        return newData;\n      });\n    }, 2500);\n\n    const generateTxn = () => {\n      setLiveTxns(prev => {\n        const types = [\"TRANSFER\", \"ESCROW\", \"SWAP\", \"MINT\", \"REWARD\"];\n        const apps = [\"KobPay Coins\", \"Ready Markets\", \"KobPlay\", \"Axiom\", \"Direct\"];\n        const newTxn = {\n          id: `tx-${Date.now()}`,\n          hash: `0x${Math.random().toString(16).slice(2, 10)}`,\n          from: `0x${Math.random().toString(16).slice(2, 6)}..${Math.random().toString(16).slice(2, 6)}`,\n          to: `0x${Math.random().toString(16).slice(2, 6)}..${Math.random().toString(16).slice(2, 6)}`,\n          amount: Math.floor(Math.random() * 25000) + 10,\n          type: types[Math.floor(Math.random() * types.length)],\n          app: apps[Math.floor(Math.random() * apps.length)],\n          time: \"Just now\"\n        };\n        return [newTxn, ...prev.slice(0, 5)];\n      });\n      setTimeout(generateTxn, Math.random() * 1700 + 800);\n    };\n\n    const initialTimeout = setTimeout(generateTxn, 1000);\n\n    return () => {\n      clearInterval(chartInterval);\n      clearTimeout(initialTimeout);\n    };\n  }, []);\n\n  useEffect(() => {\n    if (isMobileMenuOpen || activeDrawer) {\n      document.body.style.overflow = 'hidden';\n    } else {\n      document.body.style.overflow = 'unset';\n    }\n  }, [isMobileMenuOpen, activeDrawer]);\n\n  const handleFeatureClick = (featureName: string) => {\n    setIsMobileMenuOpen(false);\n    toast(`Connecting to ${featureName} Protocol...`, {\n      icon: '⚡',\n      style: { borderRadius: '10px', background: '#111827', color: '#fff', border: '1px solid #1F2937', fontSize: '12px', fontFamily: 'monospace' }\n    });\n  };\n\n  const handleExecuteFunction = () => {\n    toast.success('Done', {\n      icon: '✅',\n      style: { borderRadius: '10px', background: '#10B981', color: '#0A0E14', fontWeight: 'bold', fontSize: '12px', fontFamily: 'monospace' }\n    });\n    setActiveDrawer(null); \n  };\n\n  if (!mounted) return <div className=\"min-h-[100dvh] bg-[#0A0E14]\" />;\n  const activeDrawerData = activeDrawer ? drawerContent[activeDrawer] : null;\n\n  return (\n    <div className=\"flex h-[100dvh] bg-[#0A0E14] text-[#F9FAFB] font-sans overflow-hidden selection:bg-[#AA771C]/30 relative\">\n      <Toaster position=\"top-center\" reverseOrder={false} />\n      \n      <aside className={`fixed inset-y-0 left-0 w-64 bg-[#111827] border-r border-[#1F2937] flex flex-col justify-between z-50 transform ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 transition-transform duration-300 ease-in-out shrink-0`}>\n        <div className=\"flex-1 overflow-y-auto [&::-webkit-scrollbar]:hidden\">\n          <div className=\"p-4 lg:p-6 border-b border-[#1F2937] flex items-center justify-between\">\n            <div className=\"flex items-center gap-3\">\n              <div className=\"w-8 h-8 rounded-full bg-gradient-to-br from-[#FDB813] to-[#F59E0B] flex items-center justify-center shadow-[0_0_15px_rgba(253,184,19,0.4)] shrink-0\"><span className=\"font-black text-[#0A0E14]\">K</span></div>\n              <div className=\"flex flex-col\"><h2 className=\"font-black text-[13px] tracking-widest uppercase leading-none mb-1.5 whitespace-nowrap\">KOBPAY</h2><p className=\"text-[8px] font-mono text-[#FDB813] tracking-[0.3em] uppercase leading-none\">Holds its value</p></div>\n            </div>\n            <button className=\"lg:hidden text-[#94A3B8] hover:text-white\" onClick={() => setIsMobileMenuOpen(false)}>\n              <X size={20} />\n            </button>\n          </div>\n          <nav className=\"p-3 lg:p-4 pb-8 space-y-0.5 lg:space-y-1\">\n            {/* Grouped, because a flat list of fifteen is a list nobody\n                reads. The money features were previously reachable only from\n                /wallet, which orphaned Savings, Invest, Circles, Safe Send,\n                Activity and Take Payments behind a single page. */}\n            <NavItem icon={<LayoutDashboard size={18} />} label={t.dashboard} href=\"/\" active={pathname === '/'} onClick={() => setIsMobileMenuOpen(false)} />\n\n            <NavGroup label=\"Money\" />\n            <NavItem icon={<Wallet size={18} />} label={t.wallet} href=\"/wallet\" active={pathname === '/wallet'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<Send size={18} />} label={t.send} href=\"/send\" active={pathname === '/send'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<PiggyBank size={18} />} label={t.savings} href=\"/savings\" active={pathname === '/savings'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<LineChartIcon size={18} />} label={t.invest} href=\"/invest\" active={pathname === '/invest'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<Users size={18} />} label={t.circles} href=\"/circles\" active={pathname === '/circles'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<ShieldCheck size={18} />} label=\"Limits\" href=\"/limits\" active={pathname === '/limits'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<Gauge size={18} />} label=\"Score\" href=\"/score\" active={pathname === '/score'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<Receipt size={18} />} label={t.activity} href=\"/activity\" active={pathname === '/activity'} onClick={() => setIsMobileMenuOpen(false)} />\n\n            <NavGroup label=\"Paying\" />\n            <NavItem icon={<ShoppingCart size={18} />} label={t.pay} href=\"/pay\" active={pathname === '/pay'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<ShieldCheck size={18} />} label={t.safe} href=\"/safe\" active={pathname === '/safe'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<Store size={18} />} label={t.merchant} href=\"/merchant\" active={pathname === '/merchant'} onClick={() => setIsMobileMenuOpen(false)} />\n\n            <NavGroup label=\"Network\" />\n            <NavItem icon={<TrendingUp size={18} />} label={t.markets} href=\"/markets\" active={pathname === '/markets'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<Activity size={18} />} label=\"Ledger\" href=\"/explorer\" active={pathname === '/explorer'} onClick={() => setIsMobileMenuOpen(false)} />\n\n            {/* Only rendered for staff. am_i_staff() is the same gate the\n                admin readers use, so this cannot show a door that will not\n                open. */}\n            {isStaff && (\n              <>\n                <NavGroup label=\"Staff\" />\n                <NavItem icon={<Scale size={18} />} label={t.operations} href=\"/admin\" active={pathname === '/admin'} onClick={() => setIsMobileMenuOpen(false)} />\n              </>\n            )}\n          </nav>\n        </div>\n      </aside>\n\n      <div className=\"flex-1 flex flex-col relative h-full overflow-y-auto [&::-webkit-scrollbar]:hidden\">\n        <header className=\"h-16 sm:h-20 border-b border-[#1F2937] bg-[#111827]/80 backdrop-blur-xl sticky top-0 z-30 flex items-center justify-between px-4 sm:px-8 shrink-0\">\n          <div className=\"flex items-center gap-3 sm:gap-6 min-w-0\">\n            {/* THE PHONE MENU WAS NEVER OPENABLE.\n                The sidebar sits off-canvas at -translate-x-full until\n                isMobileMenuOpen is true, and nothing in the app ever set it\n                to true — the only toggle was the close button INSIDE the\n                sidebar, so it was off-screen too. Below lg there was no way\n                to reach Wallet, Send, Savings or anything else.\n                AppMenu is the same slide-over the other pages use. */}\n            <div className=\"lg:hidden\">\n              <AppMenu />\n            </div>\n            <div className=\"hidden sm:flex items-center gap-2 text-[11px] font-mono font-bold tracking-widest bg-[#1F2937]/50 px-4 py-2 rounded-full border border-[#1F2937]\"><span className=\"text-[#FDB813]\">1 KPC</span><span className=\"text-[#94A3B8]\">=</span><span className=\"text-white\">$1.00 USD</span></div>\n            <div className=\"flex items-center gap-2 text-[9px] sm:text-[10px] font-mono tracking-widest text-[#94A3B8] uppercase whitespace-nowrap\">\n              <div className={`w-2 h-2 rounded-full shadow-[0_0_8px_#10b981] ${ledgerLive === true ? 'bg-[#10B981] animate-pulse' : ledgerLive === false ? 'bg-[#EF4444]' : 'bg-[#94A3B8]'}`} />\n              <span>{ledgerLive === true ? 'Ledger live' : ledgerLive === false ? 'Ledger unreachable' : 'Checking...'}</span>\n            </div>\n          </div>\n          \n          <div className=\"flex items-center gap-2 sm:gap-4 z-10 shrink-0\">\n           <div className=\"relative\">\n              <button \n                onClick={() => setIsLangMenuOpen(!isLangMenuOpen)}\n                className=\"flex items-center gap-2 px-3 py-2 text-[#94A3B8] hover:text-white bg-[#111827] hover:bg-[#1F2937] border border-[#1F2937] rounded-lg transition-colors font-mono text-[10px] uppercase tracking-widest\"\n              >\n                <Globe size={14} />\n                <span className=\"hidden sm:inline\">\n                  {currentLang === 'en' ? 'EN' : currentLang === 'es' ? 'ES' : currentLang === 'fr' ? 'FR' : currentLang === 'pt' ? 'PT' : currentLang === 'zh' ? '中文' : '日本語'}\n                </span>\n                <ChevronDown size={14} className={`transition-transform duration-200 ${isLangMenuOpen ? 'rotate-180' : ''}`} />\n              </button>\n\n              <AnimatePresence>\n                {isLangMenuOpen && (\n                  <motion.div \n                    initial={{ opacity: 0, y: -10 }}\n                    animate={{ opacity: 1, y: 0 }}\n                    exit={{ opacity: 0, y: -10 }}\n                    className=\"absolute right-0 mt-2 w-32 bg-[#111827] border border-[#1F2937] rounded-xl shadow-[0_0_30px_rgba(0,0,0,0.8)] overflow-hidden z-50 flex flex-col\"\n                  >\n                    <button onClick={() => { setCurrentLang('en'); setIsLangMenuOpen(false); }} className={`px-4 py-3 text-left text-xs font-mono tracking-widest hover:bg-[#1F2937] transition-colors ${currentLang === 'en' ? 'text-[#FDB813]' : 'text-white'}`}>English</button>\n                    <button onClick={() => { setCurrentLang('es'); setIsLangMenuOpen(false); }} className={`px-4 py-3 text-left text-xs font-mono tracking-widest hover:bg-[#1F2937] transition-colors border-t border-[#1F2937] ${currentLang === 'es' ? 'text-[#FDB813]' : 'text-white'}`}>Español</button>\n                    <button onClick={() => { setCurrentLang('fr'); setIsLangMenuOpen(false); }} className={`px-4 py-3 text-left text-xs font-mono tracking-widest hover:bg-[#1F2937] transition-colors border-t border-[#1F2937] ${currentLang === 'fr' ? 'text-[#FDB813]' : 'text-white'}`}>Français</button>\n                    <button onClick={() => { setCurrentLang('pt'); setIsLangMenuOpen(false); }} className={`px-4 py-3 text-left text-xs font-mono tracking-widest hover:bg-[#1F2937] transition-colors border-t border-[#1F2937] ${currentLang === 'pt' ? 'text-[#FDB813]' : 'text-white'}`}>Português</button>\n                    <button onClick={() => { setCurrentLang('zh'); setIsLangMenuOpen(false); }} className={`px-4 py-3 text-left text-xs font-mono tracking-widest hover:bg-[#1F2937] transition-colors border-t border-[#1F2937] ${currentLang === 'zh' ? 'text-[#FDB813]' : 'text-white'}`}>简体中文</button>\n                    <button onClick={() => { setCurrentLang('ja'); setIsLangMenuOpen(false); }} className={`px-4 py-3 text-left text-xs font-mono tracking-widest hover:bg-[#1F2937] transition-colors border-t border-[#1F2937] ${currentLang === 'ja' ? 'text-[#FDB813]' : 'text-white'}`}>日本語</button>\n                  </motion.div>\n                )}\n              </AnimatePresence>\n            </div>\n            \n            <ConnectButton.Custom>\n              {({ account, chain, openAccountModal, openChainModal, openConnectModal, mounted }) => {\n                const ready = mounted;\n                const connected = ready && account && chain;\n                return (\n                  <div {...(!ready && { 'aria-hidden': true, style: { opacity: 0, pointerEvents: 'none', userSelect: 'none' }})}>\n                    {(() => {\n                      if (!connected) {\n                        return (\n                          <button onClick={openConnectModal} className=\"text-[9px] sm:text-[10px] font-mono font-bold tracking-[0.1em] sm:tracking-[0.2em] bg-[#FDB813] text-[#0A0E14] px-3 sm:px-6 py-2 rounded uppercase whitespace-nowrap shadow-[0_0_15px_rgba(253,184,19,0.3)] hover:bg-[#F59E0B] transition-colors\">\n                            Launch Wallet\n                          </button>\n                        );\n                      }\n                      return (\n                        <div className=\"flex gap-3\">\n                          <button onClick={openChainModal} className=\"hidden sm:flex items-center text-[10px] font-mono border border-[#1F2937] px-3 py-2 rounded text-[#94A3B8] hover:bg-[#1F2937] transition-all\">\n                            {chain.hasIcon && (\n                              <div style={{ background: chain.iconBackground, width: 14, height: 14, borderRadius: 999, overflow: 'hidden', display: 'inline-block', marginRight: 6 }}>\n                                {chain.iconUrl && (<img alt={chain.name ?? 'Chain icon'} src={chain.iconUrl} style={{ width: 14, height: 14 }} />)}\n                              </div>\n                            )}\n                            {chain.name}\n                          </button>\n                          <button onClick={openAccountModal} className=\"text-[10px] font-mono font-bold bg-[#1F2937] text-white px-4 py-2 rounded border border-[#FDB813]/30 hover:border-[#FDB813] transition-all\">\n                            {account.displayName}\n                            {account.displayBalance ? ` (${account.displayBalance})` : ''}\n                          </button>\n                        </div>\n                      );\n                    })()}\n                  </div>\n                );\n              }}\n            </ConnectButton.Custom>\n          </div>\n        </header>\n\n        <div className=\"w-full bg-[#FDB813] text-[#0A0E14] py-2 overflow-hidden flex items-center whitespace-nowrap z-20 border-b border-[#F59E0B]\">\n          <motion.div animate={{ x: [\"0%\", \"-50%\"] }} transition={{ repeat: Infinity, ease: \"linear\", duration: 30 }} className=\"flex gap-8 sm:gap-16 text-[10px] sm:text-[11px] font-mono font-black tracking-widest uppercase\">\n            {[...tickerItems, ...tickerItems].map((item, i) => <span key={i}>{item}</span>)}\n          </motion.div>\n        </div>\n\n        <main className=\"p-4 sm:p-6 lg:px-12 lg:py-10 relative z-10 flex-1\">\n          <div className=\"max-w-[1800px] mx-auto space-y-6 lg:space-y-10\">\n            \n            <div className=\"bg-[#0A0E14]/80 backdrop-blur-xl border border-[#1F2937] rounded-2xl sm:rounded-3xl p-5 sm:p-8 relative overflow-hidden group shadow-[0_0_80px_rgba(0,0,0,0.8)] max-w-4xl mt-0 sm:mt-2 flex flex-col items-center justify-center gap-4 sm:gap-5 text-center mx-auto\">\n              <div className=\"absolute top-1/2 left-1/2 w-full lg:w-[80%] h-64 -translate-y-1/2 -translate-x-1/2 bg-gradient-to-r from-[#AA771C]/20 via-[#AA771C]/5 to-transparent blur-[100px]\" />\n              <div className=\"relative z-10 inline-flex items-center gap-2 sm:gap-3 px-3 sm:px-4 py-2 border border-[#FDB813]/30 rounded-full bg-[#0A0E14]/60\"><Shield size={12} className=\"text-[#FDB813] shrink-0\" /><span className=\"text-[9px] sm:text-[10px] font-mono tracking-[0.12em] sm:tracking-[0.2em] text-[#FDB813] uppercase font-bold\">One KPC is one US dollar. Always.</span></div>\n              <div className=\"relative z-10 w-full max-w-xl aspect-video rounded-xl overflow-hidden border border-[#FDB813]/30 bg-black shadow-[0_0_50px_rgba(253,184,19,0.1)]\"><video src=\"/kpc-video.mp4\" autoPlay loop muted playsInline className=\"w-full h-full object-cover scale-105\" /></div>\n              <div className=\"relative z-10 flex gap-3 sm:gap-4 w-full justify-center max-w-md\">\n                <motion.button \n                  onClick={() => {\n                    if (!currentUser) {\n                      window.location.href = '/auth?redirect_uri=' + encodeURIComponent(window.location.href);\n                      return;\n                    }\n                    setIsBuyModalOpen(true);\n                  }}\n                  whileHover={{ scale: 1.03 }} \n                  whileTap={{ scale: 0.95 }} \n                  animate={{ boxShadow: [\"0px 0px 15px rgba(244, 208, 104, 0.4)\", \"0px 0px 45px rgba(255, 240, 168, 0.8)\", \"0px 0px 15px rgba(244, 208, 104, 0.4)\"] }} \n                  transition={{ duration: 2, repeat: Infinity }} \n                  className=\"relative overflow-hidden w-1/2 px-2 sm:px-6 py-3.5 sm:py-4 bg-gradient-to-r from-[#AA771C] via-[#FFF0A8] to-[#AA771C] bg-[length:200%_auto] text-[#0A0E14] rounded-lg cursor-pointer border border-[#FFF0A8]/60 font-mono font-black tracking-[0.06em] sm:tracking-[0.2em] text-[10px] sm:text-[11px] uppercase whitespace-nowrap flex items-center justify-center gap-1.5 sm:gap-2\"\n                >\n                  <motion.div className=\"absolute inset-y-0 w-1/2 bg-gradient-to-r from-transparent via-white/70 to-transparent skew-x-[-20deg]\" initial={{ left: '-100%' }} animate={{ left: '200%' }} transition={{ repeat: Infinity, duration: 2.5, ease: \"linear\", repeatDelay: 1 }} />\n                  Buy KPC <Zap size={14} className=\"animate-pulse\" />\n                </motion.button>\n                <button onClick={() => handleFeatureClick('Explorer')} className=\"w-1/2 px-2 sm:px-6 py-3.5 sm:py-4 bg-[#111827] text-[#F9FAFB] border border-[#1F2937] font-mono font-bold tracking-[0.06em] sm:tracking-[0.2em] text-[10px] sm:text-[11px] uppercase whitespace-nowrap hover:border-[#FDB813]/50 rounded-lg flex items-center justify-center transition-all\">Explore Network</button>\n              </div>\n            </div>\n\n            <div className=\"grid grid-cols-2 md:grid-cols-4 2xl:grid-cols-8 gap-3 lg:gap-4\">\n              <StatCard label=\"Live Price\" value={networkStats.price} prefix=\"$\" suffix=\" USD\" decimals={2} onClick={() => setActiveDrawer(\"live_price\")} />\n              <StatCard label=\"24h Volume\" value={networkStats.volume} prefix=\"$\" isShort onClick={() => setActiveDrawer(\"volume\")} />\n              <StatCard label=\"Market Cap\" value={networkStats.marketCap} prefix=\"$\" isShort onClick={() => setActiveDrawer(\"market_cap\")} />\n              <StatCard label=\"Txns Today\" value={networkStats.txnsToday} onClick={() => setActiveDrawer(\"txns\")} />\n              <StatCard label=\"Holders\" value={networkStats.holders} onClick={() => setActiveDrawer(\"holders\")} />\n              {/* Was \"Network LIVE/OFFLINE\", meaning a public Ethereum RPC\n                  answered. Countries is a fact about KobPay. */}\n              <StatCard label=\"Countries\" value={networkStats.countries} onClick={() => setActiveDrawer(\"global\")} />\n              {/* Was a hardcoded $0.001 of Ethereum gas. transfer_fee_bps is\n                  0, so sending really is free, and a true zero is worth more\n                  than an invented fraction. */}\n              <StatCard label=\"Send Fee\" customValue={<span className=\"text-[#10B981]\">{networkStats.transferFeeBps === 0 ? \"FREE\" : `${(networkStats.transferFeeBps / 100).toFixed(2)}%`}</span>} onClick={() => setActiveDrawer(\"fee\")} />\n              <StatCard label=\"Circulating\" value={networkStats.circulating} suffix=\"M KPC\" decimals={1} onClick={() => setActiveDrawer(\"circulating\")} />\n            </div>\n\n            <div className=\"grid grid-cols-1 lg:grid-cols-12 gap-5 lg:gap-8\">\n              <div className=\"lg:col-span-8 bg-[#111827]/80 backdrop-blur-xl border border-[#1F2937] rounded-2xl sm:rounded-[2rem] p-5 sm:p-8 lg:p-10 flex flex-col shadow-2xl\">\n                <div className=\"flex justify-between items-center mb-5 sm:mb-8\">\n                  <div><h3 className=\"text-base sm:text-xl font-black uppercase tracking-widest mb-2 flex items-center gap-2 sm:gap-3\"><Activity className=\"text-[#FDB813]\" size={20} /> What a dollar is worth</h3><p className=\"text-[10px] font-mono text-[#94A3B8] tracking-widest uppercase\">Local currencies lose value against the dollar. KPC does not.</p></div>\n                </div>\n                <div className=\"h-[240px] sm:h-[300px] lg:h-[350px] w-full font-mono text-[9px] sm:text-[10px]\">\n                  <ResponsiveContainer width=\"100%\" height=\"100%\"><LineChart data={liveChartData}><CartesianGrid strokeDasharray=\"3 3\" stroke=\"#1F2937\" vertical={false} /><XAxis dataKey=\"month\" stroke=\"#94A3B8\" /><YAxis stroke=\"#94A3B8\" tickFormatter={(val: number) => `${(val * 100).toFixed(0)}%`} /><Tooltip contentStyle={{ backgroundColor: '#0A0E14', border: '1px solid #1F2937' }} /><Legend /><Line type=\"monotone\" dataKey=\"KPC\" name=\"🪙 KPC\" stroke=\"#FDB813\" strokeWidth={3} dot={false} /><Line type=\"monotone\" dataKey=\"GHS\" name=\"🇬🇭 GHS\" stroke=\"#EF4444\" strokeWidth={2} strokeOpacity={0.6} dot={false} /><Line type=\"monotone\" dataKey=\"NGN\" name=\"🇳🇬 NGN\" stroke=\"#22D3EE\" strokeWidth={2} strokeOpacity={0.6} dot={false} /></LineChart></ResponsiveContainer>\n                </div>\n              </div>\n\n              <div className=\"lg:col-span-4 bg-[#111827]/80 border border-[#1F2937] rounded-2xl sm:rounded-[2rem] p-5 sm:p-8 flex flex-col shadow-2xl overflow-hidden relative\">\n                <div className=\"absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-[#22D3EE] to-transparent opacity-50\" />\n                <h3 className=\"text-sm font-black uppercase tracking-widest flex items-center gap-3 mb-6 relative z-10\">\n                  <Globe2 className=\"text-[#22D3EE] animate-pulse\" size={16} /> Live Feed\n                  <div className=\"w-1.5 h-1.5 bg-[#22D3EE] rounded-full animate-ping ml-auto\" />\n                </h3>\n                <div className=\"flex-1 overflow-hidden relative h-[280px] sm:h-[380px]\">\n                  <div className=\"absolute inset-0 overflow-y-auto pr-2 [&::-webkit-scrollbar]:hidden\">\n                    <div className=\"space-y-4\">\n                      <AnimatePresence initial={false}>\n                        {liveTxns.map((txn, i) => (\n                          <motion.div \n                            key={txn.id}\n                            layout \n                            initial={{ opacity: 0, y: -20, scale: 0.95 }}\n                            animate={{ opacity: 1, y: 0, scale: 1, backgroundColor: [\"#1F2937\", \"#0A0E14\"] }}\n                            exit={{ opacity: 0, scale: 0.9, transition: { duration: 0.2 } }}\n                            transition={{ duration: 0.4, ease: \"easeOut\" }}\n                            className=\"p-4 bg-[#0A0E14] border border-[#1F2937] rounded-2xl flex flex-col gap-3 group hover:border-[#FDB813]/30 transition-colors\"\n                          >\n                            <div className=\"flex justify-between items-center border-b border-[#1F2937] pb-2\">\n                              <span className=\"text-[9px] font-mono text-[#FDB813] tracking-widest bg-[#FDB813]/10 px-2 py-0.5 rounded\">{txn.type}</span>\n                              <span className=\"text-[9px] font-mono text-[#10B981] animate-pulse\">{txn.time}</span>\n                            </div>\n                            <div className=\"flex justify-between items-end\">\n                              <div>\n                                <span className=\"block text-xs font-mono text-[#94A3B8] uppercase\">From: <span className=\"text-white\">{txn.from}</span></span>\n                                <span className=\"block text-xs font-mono text-[#94A3B8] uppercase\">To: <span className=\"text-white\">{txn.to}</span></span>\n                              </div>\n                              <div className=\"text-right font-black font-mono text-white text-lg\">\n                                {txn.amount.toLocaleString()} <span className=\"text-[#FDB813] text-[10px]\">KPC</span>\n                              </div>\n                            </div>\n                          </motion.div>\n                        ))}\n                      </AnimatePresence>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>\n\n            <div className=\"pb-8 sm:pb-12 pt-2 sm:pt-4\">\n              <div className=\"flex items-center gap-3 sm:gap-4 mb-5 sm:mb-8\"><Layers className=\"text-[#FDB813] shrink-0\" /><h2 className=\"text-xl sm:text-2xl lg:text-3xl font-black uppercase tracking-tighter italic text-white\">{t.infrastructure}</h2></div>\n              <div className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 sm:gap-6\">\n                {/* These four counters are why this section read badly: the\n                    card claiming global reach printed 1, and the card about\n                    paying printed 0.\n\n                    \"Currencies 1\" came from currencies_supported — what you\n                    can FUND in, which is Paystack/GHS only. The card is\n                    about sending, so it now shows countries reached.\n\n                    \"Stability 100%\" was a hardcoded 100 presented as a\n                    measurement. The peg is the honest version of that claim.\n\n                    \"Merchants 0\" was true and will stay 0 until the first\n                    business signs up. A traction counter on a pre-launch\n                    page measures the wrong thing, so this shows what the\n                    product does — merchant fee capped at 1% — which is a\n                    fact from platform_settings, not a number waiting to\n                    grow. Apps stays a real count: 2 is small but true. */}\n                <WhyCard index={0} icon={<Globe2 size={24} className=\"text-[#22D3EE]\" />} title=\"Send Globally\" desc=\"All you need is their phone number. No bank account, no fee.\" statLabel=\"Countries\" statValue={networkStats.countries} onClick={() => setActiveDrawer(\"global\")} />\n                <WhyCard index={1} icon={<Shield size={24} className=\"text-[#FDB813]\" />} title=\"Protect Savings\" desc=\"Hold your money as dollars so it keeps its value.\" statLabel=\"Always worth\" statText=\"$1.00\" onClick={() => setActiveDrawer(\"hedge\")} />\n                <WhyCard index={2} icon={<TrendingUp size={24} className=\"text-[#10B981]\" />} title=\"Earn Daily\" desc=\"Collect KC points as you use KobPay, and swap them for KPC.\" statLabel=\"Live Apps\" statValue={networkStats.activeApps} onClick={() => setActiveDrawer(\"earn\")} />\n                <WhyCard index={3} icon={<ShoppingCart size={24} className=\"text-[#8B5CF6]\" />} title=\"Universal Pay\" desc=\"One balance that works across every shop and app on KobPay.\" statLabel={networkStats.merchants > 0 ? \"Businesses\" : \"Merchant fee\"} statValue={networkStats.merchants > 0 ? networkStats.merchants : undefined} statText={networkStats.merchants > 0 ? undefined : \"1%\"} onClick={() => setActiveDrawer(\"pay\")} />\n              </div>\n            </div>\n          </div>\n        </main>\n      </div>\n\n      <AnimatePresence>\n        {activeDrawer && activeDrawerData && (\n          <><motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className=\"fixed inset-0 bg-[#0A0E14]/70 backdrop-blur-sm z-[90]\" onClick={() => setActiveDrawer(null)} />\n          <motion.div initial={{ x: '100%' }} animate={{ x: 0 }} exit={{ x: '100%' }} transition={{ type: 'spring', damping: 25, stiffness: 200 }} className=\"fixed right-0 top-0 bottom-0 w-full sm:w-[450px] bg-[#111827] border-l border-[#1F2937] z-[100] shadow-2xl flex flex-col\">\n            <div className=\"p-5 sm:p-8 border-b border-[#1F2937] flex items-start justify-between bg-[#111827]/90 backdrop-blur-md\">\n              <div className=\"flex gap-4 items-center\"><div className={`w-12 h-12 rounded-xl flex items-center justify-center border ${activeDrawerData.bg} ${activeDrawerData.border}`}>{activeDrawerData.icon}</div><div><h3 className=\"text-xl font-black uppercase text-white\">{activeDrawerData.title}</h3><p className={`text-[10px] font-mono tracking-[0.2em] uppercase mt-1 ${activeDrawerData.color}`}>{activeDrawerData.subtitle}</p></div></div>\n              <button onClick={() => setActiveDrawer(null)} className=\"text-[#94A3B8] hover:text-white p-2 bg-[#1F2937] rounded-full\"><X size={20} /></button>\n            </div>\n            <div className=\"p-5 sm:p-8 flex-1 overflow-y-auto\"><p className=\"text-xs text-[#94A3B8] font-mono leading-relaxed uppercase tracking-widest bg-[#0A0E14] p-5 rounded-2xl border border-[#1F2937] mb-8\">{activeDrawerData.details}</p><div className=\"space-y-4\">{activeDrawerData.metrics.length > 0 && (<h4 className=\"text-[10px] font-mono text-white tracking-[0.3em] uppercase flex items-center gap-2\"><Server size={12} /> Live Metrics</h4>)}{activeDrawerData.metrics.map((m: any, i: number) => (<div key={i} className=\"bg-[#0A0E14] border border-[#1F2937] p-4 rounded-xl flex justify-between items-center group hover:border-[#FDB813]/30 transition-colors\"><span className=\"text-[9px] font-mono text-[#94A3B8] uppercase\">{m.label}</span><span className=\"text-sm font-black font-mono text-white\">{m.value}</span></div>))}</div></div>\n            <div className=\"p-5 sm:p-8 border-t border-[#1F2937] bg-[#111827]\">\n              <button onClick={handleExecuteFunction} className=\"w-full py-4 bg-[#FDB813] text-[#0A0E14] font-black font-mono text-[10px] uppercase rounded flex items-center justify-center gap-2 shadow-lg hover:bg-[#F59E0B] transition-all\">\n                Execute Function <ChevronRight size={14} />\n              </button>\n            </div>\n          </motion.div></>\n        )}\n      </AnimatePresence>\n\n      <KobBotChat />\n      {isBuyModalOpen && currentUser && (\n  <BuyKpcModal\n    accessToken={currentUser.accessToken}\n    onClose={() => setIsBuyModalOpen(false)}\n  />\n)}\n    </div>\n  );\n}\n\n// --- COMPONENTS ---\nfunction NavGroup({ label }: { label: string }) {\n  return (\n    <p className=\"px-3 lg:px-4 pt-3 lg:pt-4 pb-1 text-[9px] font-mono font-bold uppercase tracking-[0.2em] text-[#4B5563]\">\n      {label}\n    </p>\n  );\n}\n\nfunction NavItem({ icon, label, active = false, onClick, href = \"#\" }: { icon: React.ReactNode, label: string, active?: boolean, onClick?: () => void, href?: string }) {\n  return (\n    <Link \n      href={href} \n      onClick={onClick} \n      className={`w-full flex items-center gap-3 lg:gap-4 px-3 lg:px-4 py-2.5 lg:py-3 rounded-lg transition-all ${active ? 'bg-[#FDB813]/10 text-[#FDB813] border border-[#FDB813]/20' : 'text-[#94A3B8] border border-transparent hover:bg-[#1F2937] hover:text-[#F9FAFB]'}`}\n    >\n      {icon}<span className=\"text-[11px] font-mono font-bold uppercase tracking-[0.15em]\">{label}</span>\n    </Link>\n  );\n}\n\nfunction StatCard({ label, value, prefix = \"\", suffix = \"\", customValue, isShort = false, decimals = 0, onClick }: any) {\n  return (\n    <div onClick={onClick} className=\"bg-[#111827]/90 backdrop-blur-md border border-[#1F2937] p-4 lg:p-5 rounded-2xl flex flex-col justify-between group hover:border-[#FDB813]/30 hover:-translate-y-1 transition-all duration-300 shadow-lg cursor-pointer overflow-hidden\">\n      <span className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] whitespace-nowrap group-hover:text-white transition-colors\">{label}</span>\n      <div className=\"text-sm md:text-base 2xl:text-xl font-black mt-2 lg:mt-3 text-white tracking-tighter group-hover:text-[#FDB813] transition-colors flex items-baseline gap-0.5\">\n        {customValue ? customValue : (<>{prefix}{isShort ? <span className=\"font-mono\">{(value / 1000000).toFixed(2)}M</span> : <RollingNum value={value} decimals={decimals} />}<span className=\"text-[8px] xl:text-[10px] text-[#FDB813] whitespace-nowrap ml-0.5\">{suffix}</span></>)}\n      </div>\n    </div>\n  );\n}\n\n// statText renders a stat that is not a count — a peg, a rate, a fee. Without\n// it every stat had to be a number, which is how \"Stability\" ended up as a\n// hardcoded 100 dressed as a measurement.\nfunction WhyCard({ index = 0, icon, title, desc, statLabel, statValue, statText, statSuffix = \"\", onClick }: any) {\n  return (\n    <div onClick={onClick} className=\"bg-[#111827] border border-[#1F2937] p-6 lg:p-8 rounded-2xl sm:rounded-[2rem] flex flex-col group hover:-translate-y-1 hover:border-[#FDB813]/30 transition-all duration-300 shadow-xl cursor-pointer relative overflow-hidden min-h-[200px] sm:min-h-[280px] h-full\">\n      <motion.div \n        animate={{ opacity: [0.03, 0.20, 0.03], y: [0, -3, 0] }}\n        transition={{ duration: 4, repeat: Infinity, ease: \"easeInOut\", delay: index * 0.6 }}\n        className=\"absolute top-6 right-6 pointer-events-none\"\n      >\n        <div className=\"scale-[1.25] text-[#94A3B8]\">\n          {icon}\n        </div>\n      </motion.div>\n      <div className=\"relative z-10 flex-1\">\n        <div className=\"w-12 h-12 rounded-2xl bg-[#1F2937] flex items-center justify-center mb-6 border border-[#1F2937]\">{icon}</div>\n        <h3 className=\"text-base xl:text-lg font-black uppercase tracking-widest mb-3 text-white\">{title}</h3>\n        <p className=\"text-[10px] font-mono text-[#94A3B8] leading-relaxed uppercase\">{desc}</p>\n      </div>\n      <div className=\"mt-auto pt-5 border-t border-[#1F2937] flex justify-between items-end relative z-10\">\n        <span className=\"text-[9px] font-mono text-[#94A3B8] uppercase\">{statLabel}</span>\n        <span className=\"text-xl xl:text-2xl font-black font-mono tracking-tighter text-white group-hover:text-[#FDB813] transition-colors\">\n          {statText ? statText : <><RollingNum value={statValue ?? 0} decimals={(statValue ?? 0) % 1 !== 0 ? 1 : 0} />{statSuffix}</>}\n        </span>\n      </div>\n    </div>\n  );\n}\n\nconst KobBotAvatar = ({ className = \"w-full h-full\" }: { className?: string }) => (\n  <svg viewBox=\"0 0 100 100\" className={className} xmlns=\"http://www.w3.org/2000/svg\">\n    <defs>\n      <linearGradient id=\"gold-grad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n        <stop offset=\"0%\" stopColor=\"#FFF0A8\" />\n        <stop offset=\"50%\" stopColor=\"#FDB813\" />\n        <stop offset=\"100%\" stopColor=\"#AA771C\" />\n      </linearGradient>\n      <linearGradient id=\"bg-grad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n        <stop offset=\"0%\" stopColor=\"#1F2937\" />\n        <stop offset=\"100%\" stopColor=\"#0A0E14\" />\n      </linearGradient>\n      <filter id=\"glow\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n        <feGaussianBlur stdDeviation=\"2\" result=\"blur\" />\n        <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\" />\n      </filter>\n    </defs>\n    <circle cx=\"50\" cy=\"50\" r=\"48\" fill=\"url(#bg-grad)\" stroke=\"url(#gold-grad)\" strokeWidth=\"2\" />\n    <circle cx=\"50\" cy=\"50\" r=\"42\" fill=\"none\" stroke=\"#FDB813\" strokeWidth=\"0.5\" strokeDasharray=\"4 2\" opacity=\"0.4\"/>\n    <path d=\"M 50 12 L 50 25 L 35 25 L 35 35\" fill=\"none\" stroke=\"url(#gold-grad)\" strokeWidth=\"1\" />\n    <circle cx=\"50\" cy=\"12\" r=\"1.5\" fill=\"#FDB813\" />\n    <circle cx=\"35\" cy=\"35\" r=\"1.5\" fill=\"#FDB813\" />\n    <path d=\"M 50 12 L 50 25 L 65 25 L 65 35\" fill=\"none\" stroke=\"url(#gold-grad)\" strokeWidth=\"1\" />\n    <circle cx=\"65\" cy=\"35\" r=\"1.5\" fill=\"#FDB813\" />\n    <path d=\"M 15 50 L 25 50 L 25 65 L 35 65\" fill=\"none\" stroke=\"url(#gold-grad)\" strokeWidth=\"1\" opacity=\"0.7\"/>\n    <circle cx=\"15\" cy=\"50\" r=\"1.5\" fill=\"#FDB813\" />\n    <path d=\"M 85 50 L 75 50 L 75 65 L 65 65\" fill=\"none\" stroke=\"url(#gold-grad)\" strokeWidth=\"1\" opacity=\"0.7\"/>\n    <circle cx=\"85\" cy=\"50\" r=\"1.5\" fill=\"#FDB813\" />\n    <path d=\"M 38 32 L 38 68 L 44 68 L 44 52 L 55 68 L 64 68 L 49 48 L 64 32 L 55 32 L 44 45 L 44 32 Z\" fill=\"url(#gold-grad)\" filter=\"url(#glow)\"/>\n    <rect x=\"33\" y=\"46\" width=\"4\" height=\"2\" fill=\"#FFF\" filter=\"url(#glow)\" />\n    <rect x=\"63\" y=\"46\" width=\"4\" height=\"2\" fill=\"#FFF\" filter=\"url(#glow)\" />\n    <path d=\"M 40 76 L 60 76 L 56 82 L 44 82 Z\" fill=\"url(#gold-grad)\" />\n  </svg>\n);\n\nfunction KobBotChat() {\n  const [isOpen, setIsOpen] = useState(false);\n  const [messages, setMessages] = useState<{role: string, content: string}[]>([{ role: 'model', content: \"Hi, I am KobBot. Ask me anything about sending money, saving, or your balance.\" }]);\n  const [input, setInput] = useState(\"\");\n  const [isLoading, setIsLoading] = useState(false);\n  const messagesEndRef = useRef<HTMLDivElement>(null);\n\n  const scrollToBottom = () => {\n    messagesEndRef.current?.scrollIntoView({ behavior: \"smooth\" });\n  };\n\n  useEffect(() => {\n    scrollToBottom();\n  }, [messages]);\n\n  const handleSend = async () => {\n    if (!input.trim()) return;\n    const userText = input;\n    setInput(\"\");\n    \n    const newMessages = [...messages, { role: 'user', content: userText }];\n    setMessages(newMessages);\n    setIsLoading(true);\n\n    try {\n      const response = await fetch('/api/chat', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          prompt: userText,\n          history: messages.map(m => ({ role: m.role, parts: [{ text: m.content }] }))\n        }),\n      });\n\n      const data = await response.json();\n      if (data.error) throw new Error(data.error);\n\n      setMessages(prev => [...prev, { role: 'model', content: data.text }]);\n    } catch (error) {\n      console.error(error);\n      toast.error(\"KobBot connection lost.\");\n      setMessages(prev => [...prev, { role: 'model', content: \"[SYSTEM ERROR] Connection to AI Core failed.\" }]);\n    } finally {\n      setIsLoading(false);\n    }\n  };\n\n  return (\n    <>\n      <motion.button \n        onClick={() => setIsOpen(!isOpen)}\n        whileHover={{ scale: 1.05 }}\n        whileTap={{ scale: 0.95 }}\n        className=\"fixed bottom-8 right-8 w-14 h-14 bg-gradient-to-br from-[#111827] to-[#0A0E14] rounded-full shadow-[0_0_20px_rgba(253,184,19,0.3)] flex items-center justify-center z-[100] overflow-hidden border border-[#FDB813]/30\"\n      >\n        {isOpen ? <X size={24} className=\"text-[#FDB813]\" /> : <KobBotAvatar className=\"w-12 h-12 drop-shadow-[0_0_10px_rgba(253,184,19,0.5)]\" />}\n      </motion.button>\n\n      <AnimatePresence>\n        {isOpen && (\n          <motion.div \n            initial={{ opacity: 0, y: 20, scale: 0.95 }}\n            animate={{ opacity: 1, y: 0, scale: 1 }}\n            exit={{ opacity: 0, y: 20, scale: 0.95 }}\n            transition={{ duration: 0.2 }}\n          className=\"fixed bottom-28 right-8 w-[350px] h-[500px] max-h-[calc(100vh-140px)] bg-[#111827]/95 backdrop-blur-xl border border-[#1F2937] rounded-2xl shadow-[0_0_40px_rgba(0,0,0,0.8)] z-[100] flex flex-col overflow-hidden\"\n          >\n            <div className=\"p-4 border-b border-[#1F2937] bg-[#0A0E14]/50 flex items-center justify-between\">\n              <div className=\"flex items-center gap-3\">\n                <div className=\"w-8 h-8 rounded-full bg-[#0A0E14] border border-[#374151] flex items-center justify-center overflow-hidden shrink-0 shadow-[0_0_10px_rgba(253,184,19,0.2)]\">\n                  <KobBotAvatar className=\"w-full h-full scale-110\" />\n                </div>\n                <div>\n                  <div className=\"font-mono font-bold text-white tracking-widest text-xs uppercase flex items-center gap-2\">\n                    KobBot 2.0 <div className=\"w-1.5 h-1.5 bg-[#10B981] rounded-full animate-pulse shadow-[0_0_8px_#10b981]\" />\n                  </div>\n                  <div className=\"text-[9px] font-mono text-[#94A3B8] tracking-widest uppercase mt-0.5\">Your money assistant</div>\n                </div>\n              </div>\n            </div>\n\n            <div className=\"flex-1 overflow-y-auto p-4 space-y-4 [&::-webkit-scrollbar]:hidden\">\n              {messages.map((msg, i) => (\n                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>\n                  <div className={`max-w-[80%] p-3 rounded-xl text-xs font-mono leading-relaxed ${\n                    msg.role === 'user' \n                      ? 'bg-[#FDB813]/20 text-[#FDB813] border border-[#FDB813]/30 rounded-br-none' \n                      : 'bg-[#1F2937] text-white border border-[#374151] rounded-bl-none'\n                  }`}>\n                    {msg.content}\n                  </div>\n                </div>\n              ))}\n              {isLoading && (\n                <div className=\"flex justify-start\">\n                  <div className=\"bg-[#1F2937] text-[#94A3B8] p-3 rounded-xl rounded-bl-none border border-[#374151] flex items-center gap-2\">\n                    <Loader2 size={14} className=\"animate-spin\" /> <span className=\"text-[10px] font-mono tracking-widest uppercase\">Processing...</span>\n                  </div>\n                </div>\n              )}\n              <div ref={messagesEndRef} />\n            </div>\n\n            <div className=\"p-4 border-t border-[#1F2937] bg-[#0A0E14]/50 flex gap-2\">\n              <input \n                type=\"text\" \n                value={input}\n                onChange={(e) => setInput(e.target.value)}\n                onKeyDown={(e) => e.key === 'Enter' && handleSend()}\n                placeholder=\"Query network data...\"\n                className=\"flex-1 bg-[#111827] border border-[#374151] rounded-lg px-4 py-2 text-xs font-mono text-white outline-none focus:border-[#FDB813]/50 transition-colors\"\n              />\n              <button \n                onClick={handleSend}\n                disabled={isLoading || !input.trim()}\n                className=\"bg-[#FDB813] text-[#0A0E14] p-2 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-[#F59E0B] transition-colors flex items-center justify-center w-10\"\n              >\n                <Send size={16} />\n              </button>\n            </div>\n          </motion.div>\n        )}\n      </AnimatePresence>\n    </>\n  );\n}");

write("app/components/AppMenu.tsx", "\"use client\";\n\nimport React, { useCallback, useEffect, useState } from \"react\";\nimport { createPortal } from \"react-dom\";\nimport Link from \"next/link\";\nimport { usePathname } from \"next/navigation\";\nimport {\n  Menu, X, Wallet, Send, PiggyBank, LineChart, Users, ShieldCheck, Gauge,\n  Receipt, ShoppingCart, Store, TrendingUp, Activity, Scale, LayoutDashboard,\n} from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\n\n// THE MENU ONLY EXISTED ON THE DASHBOARD.\n//\n// Every other page — sixteen of them — had a back arrow and nothing else. So\n// a customer who tapped \"Score\" in the sidebar landed on /score with no way\n// to reach Savings except going back first. The nav was a one-way door.\n//\n// Rather than lift the sidebar out of ClientDashboard (760 lines, and its\n// state is tangled with the landing page), this is a small slide-over that\n// carries the same grouped links and drops into any page header with one\n// line. ClientDashboard keeps its own sidebar on wide screens; this is what\n// every other page gets.\n\ntype Item = { label: string; href: string; icon: React.ReactNode };\n\nconst GROUPS: { group: string; items: Item[] }[] = [\n  {\n    group: \"Money\",\n    items: [\n      { label: \"Wallet\", href: \"/wallet\", icon: <Wallet size={16} /> },\n      { label: \"Send\", href: \"/send\", icon: <Send size={16} /> },\n      { label: \"Savings\", href: \"/savings\", icon: <PiggyBank size={16} /> },\n      { label: \"Invest\", href: \"/invest\", icon: <LineChart size={16} /> },\n      { label: \"Circles\", href: \"/circles\", icon: <Users size={16} /> },\n      { label: \"Limits\", href: \"/limits\", icon: <ShieldCheck size={16} /> },\n      { label: \"Score\", href: \"/score\", icon: <Gauge size={16} /> },\n      { label: \"Activity\", href: \"/activity\", icon: <Receipt size={16} /> },\n    ],\n  },\n  {\n    group: \"Paying\",\n    items: [\n      { label: \"Pay with KPC\", href: \"/pay\", icon: <ShoppingCart size={16} /> },\n      { label: \"Safe Send\", href: \"/safe\", icon: <ShieldCheck size={16} /> },\n      { label: \"Take Payments\", href: \"/merchant\", icon: <Store size={16} /> },\n    ],\n  },\n  {\n    group: \"Network\",\n    items: [\n      { label: \"Markets\", href: \"/markets\", icon: <TrendingUp size={16} /> },\n      { label: \"Ledger\", href: \"/explorer\", icon: <Activity size={16} /> },\n    ],\n  },\n];\n\nexport default function AppMenu() {\n  const [open, setOpen] = useState(false);\n  const [mounted, setMounted] = useState(false);\n  const [isStaff, setIsStaff] = useState(false);\n  const pathname = usePathname();\n\n  // The panel has to be portalled to <body>.\n  //\n  // Every page header here uses backdrop-blur, and a backdrop-filter makes\n  // that element the containing block for position:fixed descendants. So an\n  // overlay rendered inside the header resolved `inset-0` against the 64px\n  // header instead of the viewport: it measured 400x63, clipped its own\n  // contents, and only the sticky panel header painted. transform and filter\n  // ancestors do the same thing, so this cannot be fixed by styling the\n  // overlay — it has to escape the subtree.\n  useEffect(() => setMounted(true), []);\n\n  // Same lesson as /score: wait for the session before calling an RPC that\n  // anon is not allowed to run, or it goes out as anon and fails.\n  useEffect(() => {\n    supabase.auth.getSession().then(({ data }) => {\n      if (!data.session) return;\n      supabase.rpc(\"am_i_staff\").then(({ data: staff }) => setIsStaff(Boolean(staff)));\n    });\n  }, []);\n\n  const close = useCallback(() => setOpen(false), []);\n\n  useEffect(() => {\n    if (!open) return;\n    const onKey = (e: KeyboardEvent) => {\n      if (e.key === \"Escape\") close();\n    };\n    window.addEventListener(\"keydown\", onKey);\n    return () => window.removeEventListener(\"keydown\", onKey);\n  }, [open, close]);\n\n  return (\n    <>\n      <button\n        onClick={() => setOpen(true)}\n        aria-label=\"Open menu\"\n        className=\"text-[#94A3B8] hover:text-[#FDB813] transition-colors p-2.5 lg:p-3 bg-[#111827] rounded-xl border border-[#1F2937] shrink-0\"\n      >\n        <Menu size={18} />\n      </button>\n\n      {open && mounted && createPortal(\n        <div className=\"fixed inset-0 z-[200] flex\">\n          <button\n            aria-label=\"Close menu\"\n            onClick={close}\n            className=\"absolute inset-0 bg-[#0A0E14]/80 backdrop-blur-sm\"\n          />\n          <nav className=\"relative w-[82vw] max-w-[280px] h-full bg-[#111827] border-r border-[#1F2937] overflow-y-auto [&::-webkit-scrollbar]:hidden\">\n            <div className=\"p-4 border-b border-[#1F2937] flex items-center justify-between sticky top-0 bg-[#111827] z-10\">\n              <div className=\"flex items-center gap-2.5 min-w-0\">\n                <div className=\"w-8 h-8 rounded-full bg-gradient-to-br from-[#FDB813] to-[#F59E0B] flex items-center justify-center shrink-0\">\n                  <span className=\"font-black text-[#0A0E14]\">K</span>\n                </div>\n                <div className=\"flex flex-col min-w-0\">\n                  <span className=\"font-black text-[12px] tracking-widest uppercase leading-none whitespace-nowrap\">\n                    KobPay\n                  </span>\n                  <span className=\"text-[8px] font-mono text-[#FDB813] tracking-[0.3em] uppercase leading-none mt-1\">\n                    Money that holds its value\n                  </span>\n                </div>\n              </div>\n              <button\n                onClick={close}\n                aria-label=\"Close menu\"\n                className=\"text-[#94A3B8] hover:text-white p-1.5 bg-[#1F2937] rounded-lg shrink-0\"\n              >\n                <X size={16} />\n              </button>\n            </div>\n\n            <div className=\"p-3 pb-8 space-y-0.5\">\n              <Row\n                item={{ label: \"Dashboard\", href: \"/\", icon: <LayoutDashboard size={16} /> }}\n                active={pathname === \"/\"}\n                onClick={close}\n              />\n              {GROUPS.map((g) => (\n                <div key={g.group}>\n                  <p className=\"text-[8px] font-mono text-[#4B5563] uppercase tracking-[0.25em] px-3 pt-4 pb-1.5\">\n                    {g.group}\n                  </p>\n                  {g.items.map((it) => (\n                    <Row\n                      key={it.href}\n                      item={it}\n                      active={pathname === it.href}\n                      onClick={close}\n                    />\n                  ))}\n                </div>\n              ))}\n              {/* Only for staff, gated on the same am_i_staff() the admin\n                  readers use, so this never shows a door that will not open. */}\n              {isStaff && (\n                <div>\n                  <p className=\"text-[8px] font-mono text-[#4B5563] uppercase tracking-[0.25em] px-3 pt-4 pb-1.5\">\n                    Staff\n                  </p>\n                  <Row\n                    item={{ label: \"Operations\", href: \"/admin\", icon: <Scale size={16} /> }}\n                    active={pathname === \"/admin\"}\n                    onClick={close}\n                  />\n                </div>\n              )}\n            </div>\n          </nav>\n        </div>,\n        document.body,\n      )}\n    </>\n  );\n}\n\nfunction Row({ item, active, onClick }: { item: Item; active: boolean; onClick: () => void }) {\n  return (\n    <Link\n      href={item.href}\n      onClick={onClick}\n      className={`flex items-center gap-3 px-3 py-2.5 rounded-lg text-[11px] font-mono uppercase tracking-[0.12em] transition-colors ${\n        active\n          ? \"bg-[#FDB813]/10 text-[#FDB813] border border-[#FDB813]/30\"\n          : \"text-[#94A3B8] hover:text-white hover:bg-[#1F2937] border border-transparent\"\n      }`}\n    >\n      <span className=\"shrink-0\">{item.icon}</span>\n      <span className=\"truncate\">{item.label}</span>\n    </Link>\n  );\n}\n");

write("app/translations.ts", "export const translations = {\n  en: {\n    dashboard: \"Dashboard\",\n    explorer: \"Explorer\",\n    wallet: \"Wallet\",\n    markets: \"Markets\",\n    send: \"Send\",\n    pay: \"Pay with KPC\",\n    trade: \"Trade\",\n    ecosystem: \"Ecosystem\",\n    savings: \"Savings\",\n    invest: \"Invest\",\n    circles: \"Circles\",\n    activity: \"Activity\",\n    safe: \"Safe Send\",\n    merchant: \"Take Payments\",\n    operations: \"Operations\",\n    infrastructure: \"What you can do\",\n    connect: \"Connect\"\n  },\n  es: {\n    dashboard: \"Panel\",\n    explorer: \"Explorador\",\n    wallet: \"Billetera\",\n    markets: \"Mercados\",\n    send: \"Enviar\",\n    pay: \"Pagar con KPC\",\n    trade: \"Comerciar\",\n    ecosystem: \"Ecosistema\",\n    savings: \"Ahorros\",\n    invest: \"Invertir\",\n    circles: \"Círculos\",\n    activity: \"Actividad\",\n    safe: \"Pago Seguro\",\n    merchant: \"Cobrar\",\n    operations: \"Operaciones\",\n    infrastructure: \"Lo que puedes hacer\",\n    connect: \"Conectar\"\n  },\n  fr: {\n    dashboard: \"Tableau de Bord\",\n    explorer: \"Explorateur\",\n    wallet: \"Portefeuille\",\n    markets: \"Marchés\",\n    send: \"Envoyer\",\n    pay: \"Payer avec KPC\",\n    trade: \"Échanger\",\n    ecosystem: \"Écosystème\",\n    savings: \"Épargne\",\n    invest: \"Investir\",\n    circles: \"Cercles\",\n    activity: \"Activité\",\n    safe: \"Paiement Sûr\",\n    merchant: \"Encaisser\",\n    operations: \"Opérations\",\n    infrastructure: \"Ce que vous pouvez faire\",\n    connect: \"Connecter\"\n  },\n  pt: {\n    dashboard: \"Painel\",\n    explorer: \"Explorador\",\n    wallet: \"Carteira\",\n    markets: \"Mercados\",\n    send: \"Enviar\",\n    pay: \"Pagar com KPC\",\n    trade: \"Negociar\",\n    ecosystem: \"Ecossistema\",\n    savings: \"Poupança\",\n    invest: \"Investir\",\n    circles: \"Círculos\",\n    activity: \"Atividade\",\n    safe: \"Pagamento Seguro\",\n    merchant: \"Receber\",\n    operations: \"Operações\",\n    infrastructure: \"O que você pode fazer\",\n    connect: \"Conectar\"\n  },\n  zh: {\n    dashboard: \"仪表板\",\n    explorer: \"区块链浏览器\",\n    wallet: \"钱包\",\n    markets: \"市场\",\n    send: \"发送\",\n    pay: \"使用 KPC 支付\",\n    trade: \"交易\",\n    ecosystem: \"生态系统\",\n    savings: \"储蓄\",\n    invest: \"投资\",\n    circles: \"互助会\",\n    activity: \"活动\",\n    safe: \"安全支付\",\n    merchant: \"收款\",\n    operations: \"运营\",\n    infrastructure: \"你可以做什么\",\n    connect: \"连接\"\n  },\n  ja: {\n    dashboard: \"ダッシュボード\",\n    explorer: \"エクスプローラー\",\n    wallet: \"ウォレット\",\n    markets: \"市場\",\n    send: \"送信\",\n    pay: \"KPCで支払う\",\n    trade: \"トレード\",\n    ecosystem: \"エコシステム\",\n    savings: \"貯蓄\",\n    invest: \"投資\",\n    circles: \"共同貯蓄\",\n    activity: \"履歴\",\n    safe: \"安全送金\",\n    merchant: \"決済受付\",\n    operations: \"運営\",\n    infrastructure: \"できること\",\n    connect: \"接続する\"\n  }\n} as const;\n\nexport type LanguageCode = keyof typeof translations;");

write("app/layout.tsx", "import type { Metadata } from \"next\";\n\nimport \"./globals.css\";\nimport { Providers } from \"./providers\";\n\nconst inter = { className: \"\" };\n\nexport const metadata: Metadata = {\n  title: \"KobPay\",\n  description: \"Elite Web3 Financial Rail\",\n};\n\nexport default function RootLayout({\n  children,\n}: Readonly<{\n  children: React.ReactNode;\n}>) {\n  return (\n    <html lang=\"en\">\n      <body className={inter.className}>\n        <Providers>\n          {children}\n        </Providers>\n      </body>\n    </html>\n  );\n}");

write("app/circles/page.tsx", "\"use client\";\n\nimport React, { useCallback, useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport {\n  ArrowLeft, Users, Plus, LogIn, Play, Copy, Check,\n  Clock, Trophy, AlertTriangle, Wallet,\n} from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\nimport AppMenu from \"../components/AppMenu\";\nimport { useKpcBalance } from \"../lib/useKpcBalance\";\nimport { formatKpcAsUsd } from \"../lib/kpcPeg\";\nimport toast, { Toaster } from \"react-hot-toast\";\n\n// Every function here is granted to `authenticated` by 012 and checks\n// membership and auth.uid() in SQL, so calling them straight from the browser\n// is safe. run_circle_payouts is service-role only and runs nightly on cron —\n// there is deliberately no way to trigger a payout from this page.\ntype Circle = {\n  id: string;\n  reference: string;\n  name: string;\n  amount_per_round: number;\n  currency: string;\n  cadence: string;\n  size: number;\n  status: string;\n  current_round: number;\n  started_at: string | null;\n  i_created_it: boolean;\n  my_position: number | null;\n  i_received_in_round: number | null;\n  times_i_was_passed_over: number;\n  members: number;\n  rounds_i_owe: number;\n  next_due: string | null;\n  pot_when_full: number;\n  in_the_pot: number;\n};\n\nconst num = (v: unknown) => (typeof v === \"number\" ? v : Number(v ?? 0));\n\nconst CADENCE_WORD: Record<string, string> = {\n  daily: \"every day\",\n  weekly: \"every week\",\n  monthly: \"every month\",\n};\n\nexport default function CirclesPage() {\n  const [userId, setUserId] = useState<string | null>(null);\n  const [checkingSession, setCheckingSession] = useState(true);\n  const [circles, setCircles] = useState<Circle[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [showCreate, setShowCreate] = useState(false);\n  const [showJoin, setShowJoin] = useState(false);\n  const [busy, setBusy] = useState<string | null>(null);\n\n  const { balance } = useKpcBalance(userId);\n\n  const load = useCallback(async () => {\n    const { data, error } = await supabase\n      .from(\"my_circles\")\n      .select(\"*\")\n      .order(\"started_at\", { ascending: false, nullsFirst: true });\n    if (error) toast.error(error.message);\n    setCircles((data as Circle[]) ?? []);\n    setLoading(false);\n  }, []);\n\n  useEffect(() => {\n    supabase.auth.getSession().then(({ data }) => {\n      setUserId(data.session?.user.id ?? null);\n      setCheckingSession(false);\n      if (data.session?.user.id) load();\n      else setLoading(false);\n    });\n  }, [load]);\n\n  // One place for every RPC, so the busy state, the error surface and the\n  // reload after a change all behave the same way everywhere.\n  const call = async (\n    fn: string,\n    args: Record<string, unknown>,\n    ok: string,\n    key: string,\n  ) => {\n    setBusy(key);\n    const { error } = await supabase.rpc(fn, args);\n    setBusy(null);\n    if (error) {\n      // These come from RAISE EXCEPTION in SQL and are written for people:\n      // \"you are already in this circle\", \"that circle is full\".\n      toast.error(error.message.replace(/^.*?:\\s*/, \"\"));\n      return false;\n    }\n    toast.success(ok);\n    await load();\n    return true;\n  };\n\n  const active = circles.filter((c) => c.status === \"active\");\n  const owed = active.reduce((s, c) => s + num(c.rounds_i_owe) * num(c.amount_per_round), 0);\n  const inPots = active.reduce((s, c) => s + num(c.in_the_pot), 0);\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white font-sans selection:bg-[#AA771C]/30 relative overflow-hidden\">\n      <Toaster position=\"top-center\" reverseOrder={false} />\n      <div className=\"absolute top-0 left-1/2 -translate-x-1/2 w-[900px] h-[900px] bg-gradient-to-br from-[#FDB813]/5 to-transparent rounded-full blur-[120px] pointer-events-none\" />\n\n      <div className=\"relative z-10 max-w-3xl mx-auto px-5 py-8 sm:px-8\">\n        <div className=\"flex justify-between items-start mb-8\">\n          <Link\n            href=\"/wallet\"\n            className=\"text-[#94A3B8] hover:text-[#FDB813] transition-colors p-2 bg-[#1F2937] rounded-lg border border-[#374151]\"\n          >\n            <ArrowLeft size={20} />\n          </Link>\n          <AppMenu />\n          <div className=\"flex items-center gap-2 text-[10px] font-mono tracking-widest uppercase bg-[#0A0E14] px-3 py-1.5 rounded-full border border-[#1F2937]\">\n            <Users size={12} className=\"text-[#FDB813]\" />\n            <span className=\"text-[#FDB813]\">Circles</span>\n          </div>\n        </div>\n\n        <h1 className=\"text-3xl font-black uppercase tracking-widest mb-1\">Circles</h1>\n        <p className=\"text-[10px] font-mono text-[#94A3B8] tracking-widest uppercase mb-8\">\n          A savings group where nobody has to hold the cash\n        </p>\n\n        {checkingSession ? (\n          <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-10 text-center\">\n            Loading...\n          </p>\n        ) : !userId ? (\n          <div className=\"bg-[#111827] border border-[#1F2937] p-6 rounded-xl\">\n            <p className=\"text-xs font-mono text-[#94A3B8] leading-relaxed uppercase\">\n              Please{\" \"}\n              <Link href=\"/auth\" className=\"underline\">\n                sign in\n              </Link>{\" \"}\n              to join a circle.\n            </p>\n          </div>\n        ) : (\n          <>\n            <div className=\"grid grid-cols-3 gap-3 mb-6\">\n              <Stat label=\"Spendable\" value={num(balance)} />\n              <Stat label=\"In the pots\" value={inPots} />\n              <Stat label=\"You owe\" value={owed} warn={owed > 0} />\n            </div>\n\n            <div className=\"grid grid-cols-2 gap-3 mb-6\">\n              <button\n                onClick={() => {\n                  setShowCreate((v) => !v);\n                  setShowJoin(false);\n                }}\n                className=\"flex items-center justify-center gap-2 bg-[#FDB813] hover:bg-[#E0A411] text-[#0A0E14] font-black uppercase tracking-widest text-xs py-4 rounded-xl transition-colors\"\n              >\n                <Plus size={14} /> Start one\n              </button>\n              <button\n                onClick={() => {\n                  setShowJoin((v) => !v);\n                  setShowCreate(false);\n                }}\n                className=\"flex items-center justify-center gap-2 bg-[#1F2937] hover:bg-[#374151] border border-[#374151] text-white font-black uppercase tracking-widest text-xs py-4 rounded-xl transition-colors\"\n              >\n                <LogIn size={14} /> Join with a code\n              </button>\n            </div>\n\n            {showCreate && (\n              <CreateForm\n                busy={busy === \"create\"}\n                onCancel={() => setShowCreate(false)}\n                onCreate={async (name, amount, cadence, size) => {\n                  const okay = await call(\n                    \"create_circle\",\n                    { p_name: name, p_amount: amount, p_cadence: cadence, p_size: size },\n                    \"Circle created — share the code\",\n                    \"create\",\n                  );\n                  if (okay) setShowCreate(false);\n                }}\n              />\n            )}\n\n            {showJoin && (\n              <JoinForm\n                busy={busy === \"join\"}\n                onCancel={() => setShowJoin(false)}\n                onJoin={async (ref) => {\n                  const okay = await call(\n                    \"join_circle\",\n                    { p_reference: ref },\n                    \"You're in\",\n                    \"join\",\n                  );\n                  if (okay) setShowJoin(false);\n                }}\n              />\n            )}\n\n            {loading ? (\n              <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-10 text-center\">\n                Loading...\n              </p>\n            ) : circles.length === 0 ? (\n              <div className=\"bg-[#111827]/80 border border-[#1F2937] rounded-2xl p-8 text-center\">\n                <Users size={28} className=\"text-[#374151] mx-auto mb-3\" />\n                <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest mb-2\">\n                  No circles yet\n                </p>\n                <p className=\"text-[10px] font-mono text-[#4B5563] leading-relaxed\">\n                  Everyone pays in each round. Each round, one person takes the\n                  whole pot. The order is drawn at random when it starts.\n                </p>\n              </div>\n            ) : (\n              <div className=\"space-y-4\">\n                {circles.map((c) => (\n                  <CircleCard\n                    key={c.id}\n                    c={c}\n                    busy={busy}\n                    onStart={() =>\n                      call(\"start_circle\", { p_circle: c.id }, \"Started — order drawn\", c.id + \":start\")\n                    }\n                    onContribute={() =>\n                      call(\"contribute_to_circle\", { p_circle: c.id }, \"Paid in\", c.id + \":pay\")\n                    }\n                    onLeave={() =>\n                      call(\"leave_circle\", { p_circle: c.id }, \"You left\", c.id + \":leave\")\n                    }\n                  />\n                ))}\n              </div>\n            )}\n\n            <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.2em] text-center mt-10 leading-relaxed\">\n              1 KPC = $1.00 · nobody holds the pot but the circle\n              <br />\n              {formatKpcAsUsd(inPots)} across your circles\n            </p>\n          </>\n        )}\n      </div>\n    </div>\n  );\n}\n\nfunction Stat({ label, value, warn }: { label: string; value: number; warn?: boolean }) {\n  return (\n    <div className=\"bg-[#0A0E14] border border-[#1F2937] p-4 rounded-xl\">\n      <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n        {label}\n      </span>\n      <span className={`text-lg font-black ${warn ? \"text-[#EF4444]\" : \"text-[#FDB813]\"}`}>\n        {value.toLocaleString(undefined, { maximumFractionDigits: 2 })}\n        <span className=\"text-[9px] text-[#94A3B8] ml-1\">KPC</span>\n      </span>\n    </div>\n  );\n}\n\nfunction CreateForm({\n  busy,\n  onCreate,\n  onCancel,\n}: {\n  busy: boolean;\n  onCreate: (name: string, amount: number, cadence: string, size: number) => void;\n  onCancel: () => void;\n}) {\n  const [name, setName] = useState(\"\");\n  const [amount, setAmount] = useState(\"\");\n  const [cadence, setCadence] = useState(\"monthly\");\n  const [size, setSize] = useState(\"5\");\n\n  const n = Number(amount) || 0;\n  const s = Number(size) || 0;\n\n  return (\n    <div className=\"bg-[#111827]/80 backdrop-blur-xl border border-[#1F2937] rounded-2xl p-5 mb-6 space-y-4\">\n      <Field label=\"What is it for\">\n        <input\n          value={name}\n          onChange={(e) => setName(e.target.value)}\n          placeholder=\"Market women\"\n          className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#FDB813] outline-none\"\n        />\n      </Field>\n\n      <div className=\"grid grid-cols-2 gap-3\">\n        <Field label=\"Each person pays\">\n          <input\n            value={amount}\n            onChange={(e) => setAmount(e.target.value)}\n            inputMode=\"decimal\"\n            placeholder=\"50\"\n            className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#FDB813] outline-none\"\n          />\n        </Field>\n        <Field label=\"How often\">\n          <select\n            value={cadence}\n            onChange={(e) => setCadence(e.target.value)}\n            className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white focus:border-[#FDB813] outline-none\"\n          >\n            <option value=\"daily\">Daily</option>\n            <option value=\"weekly\">Weekly</option>\n            <option value=\"monthly\">Monthly</option>\n          </select>\n        </Field>\n      </div>\n\n      <Field label=\"How many people\">\n        <input\n          value={size}\n          onChange={(e) => setSize(e.target.value)}\n          inputMode=\"numeric\"\n          placeholder=\"5\"\n          className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#FDB813] outline-none\"\n        />\n      </Field>\n\n      {n > 0 && s > 1 && (\n        <div className=\"bg-[#FDB813]/10 border border-[#FDB813]/30 rounded-lg p-3\">\n          <p className=\"text-[10px] font-mono text-[#FDB813] leading-relaxed uppercase\">\n            {s} people × {n.toLocaleString()} KPC = {(n * s).toLocaleString()} KPC\n            in each pot.\n            <br />\n            You pay {n.toLocaleString()} {CADENCE_WORD[cadence]} for {s} rounds,\n            and take the whole pot once.\n          </p>\n        </div>\n      )}\n\n      <div className=\"flex gap-2\">\n        <button\n          onClick={onCancel}\n          className=\"flex-1 bg-[#1F2937] hover:bg-[#374151] text-[#94A3B8] font-black uppercase tracking-widest text-xs py-3.5 rounded-xl transition-colors\"\n        >\n          Cancel\n        </button>\n        <button\n          disabled={busy || !name || n <= 0 || s < 3}\n          onClick={() => onCreate(name.trim(), n, cadence, s)}\n          className=\"flex-[2] bg-[#FDB813] hover:bg-[#E0A411] disabled:opacity-40 text-[#0A0E14] font-black uppercase tracking-widest text-xs py-3.5 rounded-xl transition-colors\"\n        >\n          {busy ? \"Creating...\" : \"Create\"}\n        </button>\n      </div>\n    </div>\n  );\n}\n\nfunction JoinForm({\n  busy,\n  onJoin,\n  onCancel,\n}: {\n  busy: boolean;\n  onJoin: (ref: string) => void;\n  onCancel: () => void;\n}) {\n  const [ref, setRef] = useState(\"\");\n  return (\n    <div className=\"bg-[#111827]/80 backdrop-blur-xl border border-[#1F2937] rounded-2xl p-5 mb-6 space-y-4\">\n      <Field label=\"Circle code\">\n        <input\n          value={ref}\n          onChange={(e) => setRef(e.target.value.toUpperCase())}\n          placeholder=\"CIR-XXXXXXXXXX\"\n          className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm font-mono text-white placeholder-[#4B5563] focus:border-[#FDB813] outline-none\"\n        />\n      </Field>\n      <div className=\"flex gap-2\">\n        <button\n          onClick={onCancel}\n          className=\"flex-1 bg-[#1F2937] hover:bg-[#374151] text-[#94A3B8] font-black uppercase tracking-widest text-xs py-3.5 rounded-xl transition-colors\"\n        >\n          Cancel\n        </button>\n        <button\n          disabled={busy || ref.trim().length < 4}\n          onClick={() => onJoin(ref.trim())}\n          className=\"flex-[2] bg-[#FDB813] hover:bg-[#E0A411] disabled:opacity-40 text-[#0A0E14] font-black uppercase tracking-widest text-xs py-3.5 rounded-xl transition-colors\"\n        >\n          {busy ? \"Joining...\" : \"Join\"}\n        </button>\n      </div>\n    </div>\n  );\n}\n\nfunction Field({ label, children }: { label: string; children: React.ReactNode }) {\n  return (\n    <div>\n      <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1.5\">\n        {label}\n      </span>\n      {children}\n    </div>\n  );\n}\n\nfunction CircleCard({\n  c,\n  busy,\n  onStart,\n  onContribute,\n  onLeave,\n}: {\n  c: Circle;\n  busy: string | null;\n  onStart: () => void;\n  onContribute: () => void;\n  onLeave: () => void;\n}) {\n  const [copied, setCopied] = useState(false);\n  const forming = c.status === \"forming\";\n  const done = c.status === \"completed\";\n  const owes = num(c.rounds_i_owe);\n  const received = c.i_received_in_round !== null;\n\n  const copy = async () => {\n    try {\n      await navigator.clipboard.writeText(c.reference);\n      setCopied(true);\n      setTimeout(() => setCopied(false), 1600);\n    } catch {\n      toast.error(\"Could not copy — the code is \" + c.reference);\n    }\n  };\n\n  return (\n    <div\n      className={`bg-[#111827]/80 backdrop-blur-xl border rounded-2xl p-5 ${\n        owes > 0 ? \"border-[#EF4444]/40\" : \"border-[#1F2937]\"\n      }`}\n    >\n      <div className=\"flex justify-between items-start mb-4\">\n        <div>\n          <h3 className=\"font-black uppercase tracking-wide text-sm\">{c.name}</h3>\n          <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mt-1\">\n            {num(c.amount_per_round).toLocaleString()} KPC {CADENCE_WORD[c.cadence]} ·{\" \"}\n            {c.members} of {c.size}\n          </p>\n        </div>\n        <span\n          className={`text-[9px] font-mono uppercase tracking-[0.15em] px-2 py-1 rounded-full border ${\n            done\n              ? \"text-[#94A3B8] border-[#374151]\"\n              : forming\n                ? \"text-[#FDB813] border-[#FDB813]/40\"\n                : \"text-[#10B981] border-[#10B981]/40\"\n          }`}\n        >\n          {done ? \"Finished\" : forming ? \"Forming\" : `Round ${c.current_round}`}\n        </span>\n      </div>\n\n      {/* While forming, the code is the whole point of the card — it is how\n          people are invited. */}\n      {forming && (\n        <button\n          onClick={copy}\n          className=\"w-full flex items-center justify-between bg-[#0A0E14] border border-[#1F2937] hover:border-[#FDB813]/50 rounded-lg px-3 py-3 mb-4 transition-colors group\"\n        >\n          <span className=\"font-mono text-sm tracking-[0.2em] text-[#FDB813]\">\n            {c.reference}\n          </span>\n          <span className=\"flex items-center gap-1.5 text-[9px] font-mono uppercase tracking-[0.15em] text-[#94A3B8] group-hover:text-[#FDB813]\">\n            {copied ? <Check size={12} /> : <Copy size={12} />}\n            {copied ? \"Copied\" : \"Share\"}\n          </span>\n        </button>\n      )}\n\n      {!forming && (\n        <div className=\"grid grid-cols-3 gap-2 mb-4\">\n          <Mini label=\"Your turn\" value={c.my_position ? `#${c.my_position}` : \"—\"} />\n          <Mini\n            label=\"In the pot\"\n            value={num(c.in_the_pot).toLocaleString(undefined, { maximumFractionDigits: 0 })}\n          />\n          <Mini\n            label={received ? \"You got it\" : \"Still waiting\"}\n            value={received ? `Round ${c.i_received_in_round}` : \"—\"}\n            good={received}\n          />\n        </div>\n      )}\n\n      {num(c.times_i_was_passed_over) > 0 && !received && (\n        <div className=\"flex gap-2 bg-[#EF4444]/10 border border-[#EF4444]/30 rounded-lg p-3 mb-4\">\n          <AlertTriangle size={14} className=\"text-[#EF4444] shrink-0 mt-0.5\" />\n          <p className=\"text-[10px] font-mono text-[#EF4444] leading-relaxed uppercase\">\n            You were passed over {c.times_i_was_passed_over}{\" \"}\n            {num(c.times_i_was_passed_over) === 1 ? \"time\" : \"times\"} for being\n            behind. Catch up and you get the next pot you are due.\n          </p>\n        </div>\n      )}\n\n      {owes > 0 && (\n        <div className=\"flex gap-2 bg-[#FDB813]/10 border border-[#FDB813]/30 rounded-lg p-3 mb-4\">\n          <Clock size={14} className=\"text-[#FDB813] shrink-0 mt-0.5\" />\n          <p className=\"text-[10px] font-mono text-[#FDB813] leading-relaxed uppercase\">\n            You owe {owes} {owes === 1 ? \"round\" : \"rounds\"} —{\" \"}\n            {(owes * num(c.amount_per_round)).toLocaleString()} KPC.\n            {c.next_due ? ` Due ${new Date(c.next_due).toLocaleDateString()}.` : \"\"}\n            <br />\n            Falling behind means being passed over when your turn comes.\n          </p>\n        </div>\n      )}\n\n      {done && (\n        <div className=\"flex gap-2 bg-[#10B981]/10 border border-[#10B981]/30 rounded-lg p-3 mb-4\">\n          <Trophy size={14} className=\"text-[#10B981] shrink-0 mt-0.5\" />\n          <p className=\"text-[10px] font-mono text-[#10B981] leading-relaxed uppercase\">\n            Finished — everybody had their turn.\n          </p>\n        </div>\n      )}\n\n      <div className=\"flex gap-2\">\n        {forming && c.i_created_it && (\n          <button\n            disabled={busy === c.id + \":start\" || c.members < 3}\n            onClick={onStart}\n            className=\"flex-[2] flex items-center justify-center gap-2 bg-[#FDB813] hover:bg-[#E0A411] disabled:opacity-40 text-[#0A0E14] font-black uppercase tracking-widest text-[10px] py-3 rounded-xl transition-colors\"\n          >\n            <Play size={12} />\n            {c.members < 3 ? `Need ${3 - c.members} more` : \"Start it\"}\n          </button>\n        )}\n        {forming && (\n          <button\n            disabled={busy === c.id + \":leave\"}\n            onClick={onLeave}\n            className=\"flex-1 bg-[#1F2937] hover:bg-[#EF4444]/20 text-[#94A3B8] hover:text-[#EF4444] font-black uppercase tracking-widest text-[10px] py-3 rounded-xl transition-colors\"\n          >\n            Leave\n          </button>\n        )}\n        {!forming && !done && (\n          <button\n            disabled={busy === c.id + \":pay\" || owes === 0}\n            onClick={onContribute}\n            className=\"flex-1 flex items-center justify-center gap-2 bg-[#10B981] hover:bg-[#0E9F6E] disabled:opacity-40 text-[#0A0E14] font-black uppercase tracking-widest text-[10px] py-3 rounded-xl transition-colors\"\n          >\n            <Wallet size={12} />\n            {owes === 0\n              ? \"Paid up\"\n              : `Pay ${num(c.amount_per_round).toLocaleString()} KPC`}\n          </button>\n        )}\n      </div>\n    </div>\n  );\n}\n\nfunction Mini({ label, value, good }: { label: string; value: string; good?: boolean }) {\n  return (\n    <div className=\"bg-[#0A0E14] border border-[#1F2937] rounded-lg p-2.5\">\n      <span className=\"block text-[8px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mb-0.5\">\n        {label}\n      </span>\n      <span className={`text-xs font-black ${good ? \"text-[#10B981]\" : \"text-white\"}`}>\n        {value}\n      </span>\n    </div>\n  );\n}\n");

write("app/activity/page.tsx", "\"use client\";\n\nimport React, { useCallback, useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport {\n  ArrowLeft, Receipt, ArrowUpRight, ArrowDownLeft, ShieldAlert,\n  ChevronDown, Clock, Check, X,\n} from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\nimport AppMenu from \"../components/AppMenu\";\nimport { formatKpcAsUsd } from \"../lib/kpcPeg\";\nimport toast, { Toaster } from \"react-hot-toast\";\n\ntype Txn = {\n  id: number;\n  transaction_group_id: string;\n  direction: \"debit\" | \"credit\";\n  amount: number;\n  signed_amount: number;\n  balance_after: number;\n  currency: string;\n  entry_type: string;\n  what: string;\n  memo: string | null;\n  created_at: string;\n  counterparty: string | null;\n  has_counterparty: boolean;\n  can_dispute: boolean;\n  dispute_reference: string | null;\n  dispute_status: string | null;\n};\n\nconst num = (v: unknown) => (typeof v === \"number\" ? v : Number(v ?? 0));\n\n// The reasons 011 accepts, in the words a person would use. The value is what\n// goes into the CHECK constraint; the label is what they read.\nconst REASONS: { value: string; label: string }[] = [\n  { value: \"not_received\", label: \"I never got it\" },\n  { value: \"not_as_described\", label: \"Not what was agreed\" },\n  { value: \"wrong_amount\", label: \"Wrong amount\" },\n  { value: \"duplicate\", label: \"Charged twice\" },\n  { value: \"unauthorised\", label: \"I didn't authorise this\" },\n  { value: \"wrong_recipient\", label: \"Went to the wrong person\" },\n  { value: \"other\", label: \"Something else\" },\n];\n\nconst DISPUTE_LABEL: Record<string, string> = {\n  open: \"Waiting for a response\",\n  answered: \"Under review\",\n  resolved_refund: \"Refunded\",\n  resolved_partial: \"Partly refunded\",\n  resolved_rejected: \"Not upheld\",\n  expired_refund: \"Refunded — no response\",\n  withdrawn: \"Withdrawn\",\n};\n\nexport default function ActivityPage() {\n  const [userId, setUserId] = useState<string | null>(null);\n  const [checkingSession, setCheckingSession] = useState(true);\n  const [txns, setTxns] = useState<Txn[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [openRow, setOpenRow] = useState<number | null>(null);\n  const [disputing, setDisputing] = useState<Txn | null>(null);\n\n  const load = useCallback(async () => {\n    const { data, error } = await supabase\n      .from(\"my_transactions\")\n      .select(\"*\")\n      .limit(200);\n    if (error) toast.error(error.message);\n    setTxns((data as Txn[]) ?? []);\n    setLoading(false);\n  }, []);\n\n  useEffect(() => {\n    supabase.auth.getSession().then(({ data }) => {\n      setUserId(data.session?.user.id ?? null);\n      setCheckingSession(false);\n      if (data.session?.user.id) load();\n      else setLoading(false);\n    });\n  }, [load]);\n\n  // Group by day, because a flat list of timestamps is unreadable once there\n  // is more than a handful of anything.\n  const days: { label: string; items: Txn[] }[] = [];\n  for (const t of txns) {\n    const d = new Date(t.created_at);\n    const label = d.toLocaleDateString(undefined, {\n      weekday: \"short\",\n      day: \"numeric\",\n      month: \"short\",\n    });\n    const last = days[days.length - 1];\n    if (last && last.label === label) last.items.push(t);\n    else days.push({ label, items: [t] });\n  }\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white font-sans selection:bg-[#AA771C]/30 relative overflow-hidden\">\n      <Toaster position=\"top-center\" reverseOrder={false} />\n      <div className=\"absolute top-0 left-1/2 -translate-x-1/2 w-[900px] h-[900px] bg-gradient-to-br from-[#FDB813]/5 to-transparent rounded-full blur-[120px] pointer-events-none\" />\n\n      <div className=\"relative z-10 max-w-3xl mx-auto px-5 py-8 sm:px-8\">\n        <div className=\"flex justify-between items-start mb-8\">\n          <Link\n            href=\"/wallet\"\n            className=\"text-[#94A3B8] hover:text-[#FDB813] transition-colors p-2 bg-[#1F2937] rounded-lg border border-[#374151]\"\n          >\n            <ArrowLeft size={20} />\n          </Link>\n          <AppMenu />\n          <div className=\"flex items-center gap-2 text-[10px] font-mono tracking-widest uppercase bg-[#0A0E14] px-3 py-1.5 rounded-full border border-[#1F2937]\">\n            <Receipt size={12} className=\"text-[#FDB813]\" />\n            <span className=\"text-[#FDB813]\">Activity</span>\n          </div>\n        </div>\n\n        <h1 className=\"text-3xl font-black uppercase tracking-widest mb-1\">Activity</h1>\n        <p className=\"text-[10px] font-mono text-[#94A3B8] tracking-widest uppercase mb-8\">\n          Every movement, and a way to challenge any of them\n        </p>\n\n        {checkingSession ? (\n          <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-10 text-center\">\n            Loading...\n          </p>\n        ) : !userId ? (\n          <div className=\"bg-[#111827] border border-[#1F2937] p-6 rounded-xl\">\n            <p className=\"text-xs font-mono text-[#94A3B8] leading-relaxed uppercase\">\n              Please{\" \"}\n              <Link href=\"/auth\" className=\"underline\">\n                sign in\n              </Link>{\" \"}\n              to see your activity.\n            </p>\n          </div>\n        ) : loading ? (\n          <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-10 text-center\">\n            Loading...\n          </p>\n        ) : txns.length === 0 ? (\n          <div className=\"bg-[#111827]/80 border border-[#1F2937] rounded-2xl p-8 text-center\">\n            <Receipt size={28} className=\"text-[#374151] mx-auto mb-3\" />\n            <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest\">\n              Nothing yet\n            </p>\n          </div>\n        ) : (\n          <div className=\"space-y-6\">\n            {days.map((day) => (\n              <div key={day.label}>\n                <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.2em] mb-2 px-1\">\n                  {day.label}\n                </p>\n                <div className=\"bg-[#111827]/80 backdrop-blur-xl border border-[#1F2937] rounded-2xl overflow-hidden\">\n                  {day.items.map((t, i) => (\n                    <Row\n                      key={t.id}\n                      t={t}\n                      first={i === 0}\n                      open={openRow === t.id}\n                      onToggle={() => setOpenRow(openRow === t.id ? null : t.id)}\n                      onDispute={() => setDisputing(t)}\n                    />\n                  ))}\n                </div>\n              </div>\n            ))}\n          </div>\n        )}\n\n        {txns.length > 0 && (\n          <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.2em] text-center mt-10 leading-relaxed\">\n            1 KPC = $1.00 · showing the last {txns.length}\n          </p>\n        )}\n      </div>\n\n      {disputing && (\n        <DisputeSheet\n          t={disputing}\n          onClose={() => setDisputing(null)}\n          onDone={async () => {\n            setDisputing(null);\n            await load();\n          }}\n        />\n      )}\n    </div>\n  );\n}\n\nfunction Row({\n  t,\n  first,\n  open,\n  onToggle,\n  onDispute,\n}: {\n  t: Txn;\n  first: boolean;\n  open: boolean;\n  onToggle: () => void;\n  onDispute: () => void;\n}) {\n  const inbound = t.direction === \"credit\";\n  const amount = num(t.signed_amount);\n  const disputed = !!t.dispute_status;\n  const live = t.dispute_status === \"open\" || t.dispute_status === \"answered\";\n\n  return (\n    <div className={first ? \"\" : \"border-t border-[#1F2937]\"}>\n      <button\n        onClick={onToggle}\n        className=\"w-full flex items-center gap-3 px-4 py-3.5 hover:bg-[#0A0E14]/50 transition-colors text-left\"\n      >\n        <span\n          className={`shrink-0 p-2 rounded-lg ${\n            inbound ? \"bg-[#10B981]/10 text-[#10B981]\" : \"bg-[#1F2937] text-[#94A3B8]\"\n          }`}\n        >\n          {inbound ? <ArrowDownLeft size={14} /> : <ArrowUpRight size={14} />}\n        </span>\n\n        <span className=\"flex-1 min-w-0\">\n          <span className=\"block text-sm font-bold truncate\">\n            {t.counterparty ?? t.what}\n          </span>\n          <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] truncate\">\n            {t.what}\n            {t.memo ? ` · ${t.memo}` : \"\"}\n          </span>\n        </span>\n\n        <span className=\"shrink-0 text-right\">\n          <span\n            className={`block text-sm font-black ${\n              inbound ? \"text-[#10B981]\" : \"text-white\"\n            }`}\n          >\n            {inbound ? \"+\" : \"\"}\n            {amount.toLocaleString(undefined, { maximumFractionDigits: 2 })}\n          </span>\n          <span className=\"block text-[8px] font-mono text-[#4B5563] uppercase tracking-[0.15em]\">\n            {new Date(t.created_at).toLocaleTimeString(undefined, {\n              hour: \"2-digit\",\n              minute: \"2-digit\",\n            })}\n          </span>\n        </span>\n\n        <ChevronDown\n          size={14}\n          className={`shrink-0 text-[#4B5563] transition-transform ${open ? \"rotate-180\" : \"\"}`}\n        />\n      </button>\n\n      {open && (\n        <div className=\"px-4 pb-4 space-y-3\">\n          <div className=\"grid grid-cols-2 gap-2\">\n            <Detail label=\"Balance after\" value={num(t.balance_after).toLocaleString(undefined, { maximumFractionDigits: 2 }) + \" KPC\"} />\n            <Detail label=\"In dollars\" value={formatKpcAsUsd(Math.abs(amount))} />\n          </div>\n\n          {disputed && (\n            <div\n              className={`flex gap-2 rounded-lg p-3 border ${\n                live\n                  ? \"bg-[#FDB813]/10 border-[#FDB813]/30\"\n                  : \"bg-[#1F2937] border-[#374151]\"\n              }`}\n            >\n              {live ? (\n                <Clock size={14} className=\"text-[#FDB813] shrink-0 mt-0.5\" />\n              ) : (\n                <Check size={14} className=\"text-[#94A3B8] shrink-0 mt-0.5\" />\n              )}\n              <p\n                className={`text-[10px] font-mono leading-relaxed uppercase ${\n                  live ? \"text-[#FDB813]\" : \"text-[#94A3B8]\"\n                }`}\n              >\n                {t.dispute_reference} —{\" \"}\n                {DISPUTE_LABEL[t.dispute_status ?? \"\"] ?? t.dispute_status}\n                {live && (\n                  <>\n                    <br />\n                    If nobody responds in time, it is decided in your favour.\n                  </>\n                )}\n              </p>\n            </div>\n          )}\n\n          {t.can_dispute && (\n            <button\n              onClick={onDispute}\n              className=\"w-full flex items-center justify-center gap-2 bg-[#1F2937] hover:bg-[#EF4444]/20 text-[#94A3B8] hover:text-[#EF4444] border border-[#374151] hover:border-[#EF4444]/50 font-black uppercase tracking-widest text-[10px] py-3 rounded-xl transition-colors\"\n            >\n              <ShieldAlert size={12} /> Something wrong with this?\n            </button>\n          )}\n        </div>\n      )}\n    </div>\n  );\n}\n\nfunction Detail({ label, value }: { label: string; value: string }) {\n  return (\n    <div className=\"bg-[#0A0E14] border border-[#1F2937] rounded-lg p-2.5\">\n      <span className=\"block text-[8px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mb-0.5\">\n        {label}\n      </span>\n      <span className=\"text-xs font-black text-white\">{value}</span>\n    </div>\n  );\n}\n\nfunction DisputeSheet({\n  t,\n  onClose,\n  onDone,\n}: {\n  t: Txn;\n  onClose: () => void;\n  onDone: () => void;\n}) {\n  const [reason, setReason] = useState(\"\");\n  const [detail, setDetail] = useState(\"\");\n  const [busy, setBusy] = useState(false);\n\n  const submit = async () => {\n    setBusy(true);\n    const { error } = await supabase.rpc(\"open_dispute\", {\n      p_group: t.transaction_group_id,\n      p_reason: reason,\n      p_detail: detail.trim() || null,\n    });\n    setBusy(false);\n    if (error) {\n      toast.error(error.message.replace(/^.*?:\\s*/, \"\"));\n      return;\n    }\n    toast.success(\"Opened — the money is held while it's looked at\");\n    onDone();\n  };\n\n  return (\n    <div className=\"fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/70 backdrop-blur-sm p-0 sm:p-5\">\n      <div className=\"w-full sm:max-w-md bg-[#111827] border border-[#1F2937] rounded-t-2xl sm:rounded-2xl p-5 space-y-4 max-h-[90vh] overflow-y-auto\">\n        <div className=\"flex justify-between items-start\">\n          <div>\n            <h3 className=\"font-black uppercase tracking-wide text-sm\">\n              Challenge this\n            </h3>\n            <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mt-1\">\n              {t.what} · {num(t.amount).toLocaleString()} KPC\n              {t.counterparty ? ` · ${t.counterparty}` : \"\"}\n            </p>\n          </div>\n          <button\n            onClick={onClose}\n            className=\"text-[#94A3B8] hover:text-white p-1\"\n            aria-label=\"Close\"\n          >\n            <X size={18} />\n          </button>\n        </div>\n\n        {/* Said before they commit, because it is the reason to use this rather\n            than complaining somewhere public. */}\n        <div className=\"bg-[#10B981]/10 border border-[#10B981]/30 rounded-lg p-3\">\n          <p className=\"text-[10px] font-mono text-[#10B981] leading-relaxed uppercase\">\n            The {num(t.amount).toLocaleString()} KPC is held as soon as you\n            open this — neither side can spend it.\n            <br />\n            If they don't respond in 3 days, it is decided in your favour.\n          </p>\n        </div>\n\n        <div>\n          <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1.5\">\n            What went wrong\n          </span>\n          <div className=\"space-y-1.5\">\n            {REASONS.map((r) => (\n              <button\n                key={r.value}\n                onClick={() => setReason(r.value)}\n                className={`w-full text-left px-3 py-2.5 rounded-lg border text-xs transition-colors ${\n                  reason === r.value\n                    ? \"border-[#EF4444] bg-[#EF4444]/10 text-white\"\n                    : \"border-[#1F2937] bg-[#0A0E14] text-[#94A3B8] hover:border-[#374151]\"\n                }`}\n              >\n                {r.label}\n              </button>\n            ))}\n          </div>\n        </div>\n\n        <div>\n          <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1.5\">\n            Anything else (optional)\n          </span>\n          <textarea\n            value={detail}\n            onChange={(e) => setDetail(e.target.value)}\n            rows={3}\n            placeholder=\"What happened?\"\n            className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#EF4444] outline-none resize-none\"\n          />\n        </div>\n\n        <div className=\"flex gap-2\">\n          <button\n            onClick={onClose}\n            className=\"flex-1 bg-[#1F2937] hover:bg-[#374151] text-[#94A3B8] font-black uppercase tracking-widest text-xs py-3.5 rounded-xl transition-colors\"\n          >\n            Cancel\n          </button>\n          <button\n            disabled={busy || !reason}\n            onClick={submit}\n            className=\"flex-[2] bg-[#EF4444] hover:bg-[#DC2626] disabled:opacity-40 text-white font-black uppercase tracking-widest text-xs py-3.5 rounded-xl transition-colors\"\n          >\n            {busy ? \"Opening...\" : \"Open dispute\"}\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n}\n");

write("app/safe/page.tsx", "\"use client\";\n\nimport React, { useCallback, useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport {\n  ArrowLeft, ShieldCheck, Plus, Check, X, AlertTriangle,\n  Clock, Scale, Handshake,\n} from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\nimport AppMenu from \"../components/AppMenu\";\nimport { useKpcBalance } from \"../lib/useKpcBalance\";\nimport { formatKpcAsUsd } from \"../lib/kpcPeg\";\nimport toast, { Toaster } from \"react-hot-toast\";\n\ntype SafePayment = {\n  id: string;\n  reference: string;\n  amount: number;\n  currency: string;\n  description: string;\n  status: string;\n  created_at: string;\n  auto_release_at: string | null;\n  settled_at: string | null;\n  issue_reason: string | null;\n  resolution_note: string | null;\n  amount_to_buyer: number | null;\n  i_am_the_buyer: boolean;\n  other_party: string | null;\n  other_tag: string | null;\n  hours_left: number | null;\n};\n\nconst num = (v: unknown) => (typeof v === \"number\" ? v : Number(v ?? 0));\n\nconst STATUS: Record<string, { label: string; tone: \"live\" | \"good\" | \"bad\" | \"mute\" }> = {\n  held: { label: \"Held\", tone: \"live\" },\n  disputed: { label: \"Issue raised\", tone: \"bad\" },\n  released: { label: \"Released\", tone: \"good\" },\n  refunded: { label: \"Refunded\", tone: \"mute\" },\n  split: { label: \"Split\", tone: \"mute\" },\n};\n\nconst ISSUES = [\n  { value: \"not_received\", label: \"Nothing arrived\" },\n  { value: \"not_as_described\", label: \"Not what was agreed\" },\n  { value: \"wrong_amount\", label: \"Wrong amount\" },\n  { value: \"other\", label: \"Something else\" },\n];\n\nexport default function SafePage() {\n  const [userId, setUserId] = useState<string | null>(null);\n  const [checkingSession, setCheckingSession] = useState(true);\n  const [items, setItems] = useState<SafePayment[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [showNew, setShowNew] = useState(false);\n  const [busy, setBusy] = useState<string | null>(null);\n  const [issueFor, setIssueFor] = useState<SafePayment | null>(null);\n\n  const { balance } = useKpcBalance(userId);\n\n  const load = useCallback(async () => {\n    const { data, error } = await supabase\n      .from(\"my_safe_payments\")\n      .select(\"*\")\n      .order(\"created_at\", { ascending: false });\n    if (error) toast.error(error.message);\n    setItems((data as SafePayment[]) ?? []);\n    setLoading(false);\n  }, []);\n\n  useEffect(() => {\n    supabase.auth.getSession().then(({ data }) => {\n      setUserId(data.session?.user.id ?? null);\n      setCheckingSession(false);\n      if (data.session?.user.id) load();\n      else setLoading(false);\n    });\n  }, [load]);\n\n  const call = async (fn: string, args: Record<string, unknown>, ok: string, key: string) => {\n    setBusy(key);\n    const { error } = await supabase.rpc(fn, args);\n    setBusy(null);\n    if (error) {\n      toast.error(error.message.replace(/^.*?:\\s*/, \"\"));\n      return false;\n    }\n    toast.success(ok);\n    await load();\n    return true;\n  };\n\n  const held = items.filter((i) => i.status === \"held\" || i.status === \"disputed\");\n  const holding = held.reduce((s, i) => s + num(i.amount), 0);\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white font-sans selection:bg-[#AA771C]/30 relative overflow-hidden\">\n      <Toaster position=\"top-center\" reverseOrder={false} />\n      <div className=\"absolute top-0 left-1/2 -translate-x-1/2 w-[900px] h-[900px] bg-gradient-to-br from-[#10B981]/5 to-transparent rounded-full blur-[120px] pointer-events-none\" />\n\n      <div className=\"relative z-10 max-w-3xl mx-auto px-5 py-8 sm:px-8\">\n        <div className=\"flex justify-between items-start mb-8\">\n          <Link\n            href=\"/wallet\"\n            className=\"text-[#94A3B8] hover:text-[#FDB813] transition-colors p-2 bg-[#1F2937] rounded-lg border border-[#374151]\"\n          >\n            <ArrowLeft size={20} />\n          </Link>\n          <AppMenu />\n          <div className=\"flex items-center gap-2 text-[10px] font-mono tracking-widest uppercase bg-[#0A0E14] px-3 py-1.5 rounded-full border border-[#1F2937]\">\n            <ShieldCheck size={12} className=\"text-[#10B981]\" />\n            <span className=\"text-[#10B981]\">Safe send</span>\n          </div>\n        </div>\n\n        <h1 className=\"text-3xl font-black uppercase tracking-widest mb-1\">Safe send</h1>\n        <p className=\"text-[10px] font-mono text-[#94A3B8] tracking-widest uppercase mb-8\">\n          They see the money is real. You keep it until it arrives.\n        </p>\n\n        {checkingSession ? (\n          <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-10 text-center\">\n            Loading...\n          </p>\n        ) : !userId ? (\n          <div className=\"bg-[#111827] border border-[#1F2937] p-6 rounded-xl\">\n            <p className=\"text-xs font-mono text-[#94A3B8] leading-relaxed uppercase\">\n              Please{\" \"}\n              <Link href=\"/auth\" className=\"underline\">\n                sign in\n              </Link>{\" \"}\n              to pay safely.\n            </p>\n          </div>\n        ) : (\n          <>\n            <div className=\"grid grid-cols-2 gap-3 mb-6\">\n              <Stat label=\"Spendable\" value={num(balance)} />\n              <Stat label=\"Being held\" value={holding} accent />\n            </div>\n\n            <button\n              onClick={() => setShowNew((v) => !v)}\n              className=\"w-full mb-6 flex items-center justify-center gap-2 bg-[#10B981] hover:bg-[#0E9F6E] text-[#0A0E14] font-black uppercase tracking-widest text-xs py-4 rounded-xl transition-colors\"\n            >\n              <Plus size={14} /> Pay someone safely\n            </button>\n\n            {showNew && (\n              <NewForm\n                busy={busy === \"new\"}\n                onCancel={() => setShowNew(false)}\n                onCreate={async (to, amount, what, days) => {\n                  const okay = await call(\n                    \"create_safe_payment\",\n                    { p_recipient: to, p_amount: amount, p_description: what, p_days: days },\n                    \"Held — they can see it is real\",\n                    \"new\",\n                  );\n                  if (okay) setShowNew(false);\n                }}\n              />\n            )}\n\n            {loading ? (\n              <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-10 text-center\">\n                Loading...\n              </p>\n            ) : items.length === 0 ? (\n              <div className=\"bg-[#111827]/80 border border-[#1F2937] rounded-2xl p-8 text-center\">\n                <Handshake size={28} className=\"text-[#374151] mx-auto mb-3\" />\n                <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest mb-2\">\n                  Nothing held\n                </p>\n                <p className=\"text-[10px] font-mono text-[#4B5563] leading-relaxed\">\n                  Buying from someone you don&apos;t know? Pay this way and the\n                  money waits where neither of you can spend it.\n                </p>\n              </div>\n            ) : (\n              <div className=\"space-y-4\">\n                {items.map((s) => (\n                  <Card\n                    key={s.id}\n                    s={s}\n                    busy={busy}\n                    onConfirm={() =>\n                      call(\"confirm_safe_payment\", { p_payment: s.id }, \"Released to them\", s.id + \":ok\")\n                    }\n                    onCancel={() =>\n                      call(\"cancel_safe_payment\", { p_payment: s.id, p_why: null }, \"Returned to them\", s.id + \":no\")\n                    }\n                    onIssue={() => setIssueFor(s)}\n                  />\n                ))}\n              </div>\n            )}\n\n            <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.2em] text-center mt-10 leading-relaxed\">\n              1 KPC = $1.00 · held by the escrow, not by KobPay\n              <br />\n              {formatKpcAsUsd(holding)} currently held\n            </p>\n          </>\n        )}\n      </div>\n\n      {issueFor && (\n        <IssueSheet\n          s={issueFor}\n          onClose={() => setIssueFor(null)}\n          onDone={async () => {\n            setIssueFor(null);\n            await load();\n          }}\n        />\n      )}\n    </div>\n  );\n}\n\nfunction Stat({ label, value, accent }: { label: string; value: number; accent?: boolean }) {\n  return (\n    <div className=\"bg-[#0A0E14] border border-[#1F2937] p-4 rounded-xl\">\n      <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n        {label}\n      </span>\n      <span className={`text-lg font-black ${accent ? \"text-[#10B981]\" : \"text-[#FDB813]\"}`}>\n        {value.toLocaleString(undefined, { maximumFractionDigits: 2 })}\n        <span className=\"text-[9px] text-[#94A3B8] ml-1\">KPC</span>\n      </span>\n    </div>\n  );\n}\n\nfunction NewForm({\n  busy,\n  onCreate,\n  onCancel,\n}: {\n  busy: boolean;\n  onCreate: (to: string, amount: number, what: string, days: number) => void;\n  onCancel: () => void;\n}) {\n  const [to, setTo] = useState(\"\");\n  const [amount, setAmount] = useState(\"\");\n  const [what, setWhat] = useState(\"\");\n  const [days, setDays] = useState(\"7\");\n\n  const n = Number(amount) || 0;\n  const d = Number(days) || 7;\n\n  return (\n    <div className=\"bg-[#111827]/80 backdrop-blur-xl border border-[#1F2937] rounded-2xl p-5 mb-6 space-y-4\">\n      <Field label=\"Who you're paying\">\n        <input\n          value={to}\n          onChange={(e) => setTo(e.target.value)}\n          placeholder=\"@their-tag or 233...\"\n          className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#10B981] outline-none\"\n        />\n      </Field>\n\n      <Field label=\"What you're paying for\">\n        <input\n          value={what}\n          onChange={(e) => setWhat(e.target.value)}\n          placeholder=\"Samsung A15, blue, 128GB\"\n          className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#10B981] outline-none\"\n        />\n      </Field>\n      {/* Not decoration: this is the sentence both sides argue over later, and\n          the one a staff decision gets made against. */}\n      <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.15em] -mt-2 leading-relaxed\">\n        Be specific. If something goes wrong, this is what gets compared.\n      </p>\n\n      <div className=\"grid grid-cols-2 gap-3\">\n        <Field label=\"Amount\">\n          <input\n            value={amount}\n            onChange={(e) => setAmount(e.target.value)}\n            inputMode=\"decimal\"\n            placeholder=\"200\"\n            className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#10B981] outline-none\"\n          />\n        </Field>\n        <Field label=\"Days to confirm\">\n          <input\n            value={days}\n            onChange={(e) => setDays(e.target.value)}\n            inputMode=\"numeric\"\n            placeholder=\"7\"\n            className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#10B981] outline-none\"\n          />\n        </Field>\n      </div>\n\n      {n > 0 && (\n        <div className=\"bg-[#10B981]/10 border border-[#10B981]/30 rounded-lg p-3\">\n          <p className=\"text-[10px] font-mono text-[#10B981] leading-relaxed uppercase\">\n            {n.toLocaleString()} KPC leaves your wallet now and waits where\n            neither of you can spend it.\n            <br />\n            Confirm when it arrives and they&apos;re paid. Raise an issue and it\n            stays put. Do nothing for {d} {d === 1 ? \"day\" : \"days\"} and it goes\n            to them.\n          </p>\n        </div>\n      )}\n\n      <div className=\"flex gap-2\">\n        <button\n          onClick={onCancel}\n          className=\"flex-1 bg-[#1F2937] hover:bg-[#374151] text-[#94A3B8] font-black uppercase tracking-widest text-xs py-3.5 rounded-xl transition-colors\"\n        >\n          Cancel\n        </button>\n        <button\n          disabled={busy || !to || !what || n <= 0}\n          onClick={() => onCreate(to.trim(), n, what.trim(), d)}\n          className=\"flex-[2] bg-[#10B981] hover:bg-[#0E9F6E] disabled:opacity-40 text-[#0A0E14] font-black uppercase tracking-widest text-xs py-3.5 rounded-xl transition-colors\"\n        >\n          {busy ? \"Holding...\" : `Hold ${n > 0 ? n.toLocaleString() : \"\"} KPC`}\n        </button>\n      </div>\n    </div>\n  );\n}\n\nfunction Field({ label, children }: { label: string; children: React.ReactNode }) {\n  return (\n    <div>\n      <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1.5\">\n        {label}\n      </span>\n      {children}\n    </div>\n  );\n}\n\nfunction Card({\n  s,\n  busy,\n  onConfirm,\n  onCancel,\n  onIssue,\n}: {\n  s: SafePayment;\n  busy: string | null;\n  onConfirm: () => void;\n  onCancel: () => void;\n  onIssue: () => void;\n}) {\n  const st = STATUS[s.status] ?? { label: s.status, tone: \"mute\" as const };\n  const live = s.status === \"held\";\n  const hours = s.hours_left ?? 0;\n  const days = Math.floor(hours / 24);\n\n  const who = s.other_party ?? (s.other_tag ? \"@\" + s.other_tag : \"Someone\");\n\n  return (\n    <div\n      className={`bg-[#111827]/80 backdrop-blur-xl border rounded-2xl p-5 ${\n        s.status === \"disputed\" ? \"border-[#EF4444]/40\" : \"border-[#1F2937]\"\n      }`}\n    >\n      <div className=\"flex justify-between items-start mb-3\">\n        <div className=\"min-w-0\">\n          <h3 className=\"font-black uppercase tracking-wide text-sm truncate\">\n            {s.description}\n          </h3>\n          <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mt-1\">\n            {s.i_am_the_buyer ? \"You pay\" : \"You receive\"} · {who} ·{\" \"}\n            {num(s.amount).toLocaleString()} KPC\n          </p>\n        </div>\n        <span\n          className={`shrink-0 ml-2 text-[9px] font-mono uppercase tracking-[0.15em] px-2 py-1 rounded-full border ${\n            st.tone === \"live\"\n              ? \"text-[#10B981] border-[#10B981]/40\"\n              : st.tone === \"bad\"\n                ? \"text-[#EF4444] border-[#EF4444]/40\"\n                : st.tone === \"good\"\n                  ? \"text-[#10B981] border-[#10B981]/40\"\n                  : \"text-[#94A3B8] border-[#374151]\"\n          }`}\n        >\n          {st.label}\n        </span>\n      </div>\n\n      {live && (\n        <div className=\"flex gap-2 bg-[#0A0E14] border border-[#1F2937] rounded-lg p-3 mb-4\">\n          <Clock size={14} className=\"text-[#FDB813] shrink-0 mt-0.5\" />\n          <p className=\"text-[10px] font-mono text-[#94A3B8] leading-relaxed uppercase\">\n            {s.i_am_the_buyer ? (\n              <>\n                Releases to {who} in{\" \"}\n                <span className=\"text-[#FDB813]\">\n                  {days > 0 ? `${days} ${days === 1 ? \"day\" : \"days\"}` : `${hours} hours`}\n                </span>{\" \"}\n                unless you confirm or raise an issue.\n              </>\n            ) : (\n              <>\n                Yours in{\" \"}\n                <span className=\"text-[#FDB813]\">\n                  {days > 0 ? `${days} ${days === 1 ? \"day\" : \"days\"}` : `${hours} hours`}\n                </span>{\" \"}\n                even if they say nothing.\n              </>\n            )}\n          </p>\n        </div>\n      )}\n\n      {s.status === \"disputed\" && (\n        <div className=\"flex gap-2 bg-[#EF4444]/10 border border-[#EF4444]/30 rounded-lg p-3 mb-4\">\n          <Scale size={14} className=\"text-[#EF4444] shrink-0 mt-0.5\" />\n          <p className=\"text-[10px] font-mono text-[#EF4444] leading-relaxed uppercase\">\n            An issue was raised{s.issue_reason ? `: ${s.issue_reason.replace(/_/g, \" \")}` : \"\"}.\n            <br />\n            The clock has stopped. Someone will look at it.\n          </p>\n        </div>\n      )}\n\n      {s.resolution_note && s.status !== \"disputed\" && (\n        <div className=\"flex gap-2 bg-[#1F2937] border border-[#374151] rounded-lg p-3 mb-4\">\n          <Check size={14} className=\"text-[#94A3B8] shrink-0 mt-0.5\" />\n          <p className=\"text-[10px] font-mono text-[#94A3B8] leading-relaxed uppercase\">\n            {s.resolution_note}\n            {s.amount_to_buyer !== null && num(s.amount_to_buyer) > 0 && (\n              <>\n                <br />\n                {num(s.amount_to_buyer).toLocaleString()} KPC went back to the buyer.\n              </>\n            )}\n          </p>\n        </div>\n      )}\n\n      {live && s.i_am_the_buyer && (\n        <div className=\"flex gap-2\">\n          <button\n            disabled={busy === s.id + \":ok\"}\n            onClick={onConfirm}\n            className=\"flex-[2] flex items-center justify-center gap-2 bg-[#10B981] hover:bg-[#0E9F6E] disabled:opacity-40 text-[#0A0E14] font-black uppercase tracking-widest text-[10px] py-3 rounded-xl transition-colors\"\n          >\n            <Check size={12} /> It arrived — pay them\n          </button>\n          <button\n            onClick={onIssue}\n            className=\"flex-1 flex items-center justify-center gap-1.5 bg-[#1F2937] hover:bg-[#EF4444]/20 text-[#94A3B8] hover:text-[#EF4444] font-black uppercase tracking-widest text-[10px] py-3 rounded-xl transition-colors\"\n          >\n            <AlertTriangle size={12} /> Problem\n          </button>\n        </div>\n      )}\n\n      {(live || s.status === \"disputed\") && !s.i_am_the_buyer && (\n        <button\n          disabled={busy === s.id + \":no\"}\n          onClick={onCancel}\n          className=\"w-full flex items-center justify-center gap-2 bg-[#1F2937] hover:bg-[#374151] disabled:opacity-40 text-[#94A3B8] font-black uppercase tracking-widest text-[10px] py-3 rounded-xl transition-colors\"\n        >\n          <X size={12} /> I can&apos;t deliver — return it\n        </button>\n      )}\n    </div>\n  );\n}\n\nfunction IssueSheet({\n  s,\n  onClose,\n  onDone,\n}: {\n  s: SafePayment;\n  onClose: () => void;\n  onDone: () => void;\n}) {\n  const [reason, setReason] = useState(\"\");\n  const [detail, setDetail] = useState(\"\");\n  const [busy, setBusy] = useState(false);\n\n  const submit = async () => {\n    setBusy(true);\n    const { error } = await supabase.rpc(\"raise_safe_issue\", {\n      p_payment: s.id,\n      p_reason: reason,\n      p_detail: detail.trim() || null,\n    });\n    setBusy(false);\n    if (error) {\n      toast.error(error.message.replace(/^.*?:\\s*/, \"\"));\n      return;\n    }\n    toast.success(\"Raised — the clock has stopped\");\n    onDone();\n  };\n\n  return (\n    <div className=\"fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/70 backdrop-blur-sm p-0 sm:p-5\">\n      <div className=\"w-full sm:max-w-md bg-[#111827] border border-[#1F2937] rounded-t-2xl sm:rounded-2xl p-5 space-y-4 max-h-[90vh] overflow-y-auto\">\n        <div className=\"flex justify-between items-start\">\n          <div className=\"min-w-0\">\n            <h3 className=\"font-black uppercase tracking-wide text-sm\">\n              What went wrong?\n            </h3>\n            <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mt-1 truncate\">\n              {s.description} · {num(s.amount).toLocaleString()} KPC\n            </p>\n          </div>\n          <button onClick={onClose} className=\"text-[#94A3B8] hover:text-white p-1\" aria-label=\"Close\">\n            <X size={18} />\n          </button>\n        </div>\n\n        <div className=\"bg-[#10B981]/10 border border-[#10B981]/30 rounded-lg p-3\">\n          <p className=\"text-[10px] font-mono text-[#10B981] leading-relaxed uppercase\">\n            Raising this stops the countdown. Your {num(s.amount).toLocaleString()}{\" \"}\n            KPC stays held until it is sorted out.\n          </p>\n        </div>\n\n        <div className=\"space-y-1.5\">\n          {ISSUES.map((r) => (\n            <button\n              key={r.value}\n              onClick={() => setReason(r.value)}\n              className={`w-full text-left px-3 py-2.5 rounded-lg border text-xs transition-colors ${\n                reason === r.value\n                  ? \"border-[#EF4444] bg-[#EF4444]/10 text-white\"\n                  : \"border-[#1F2937] bg-[#0A0E14] text-[#94A3B8] hover:border-[#374151]\"\n              }`}\n            >\n              {r.label}\n            </button>\n          ))}\n        </div>\n\n        <textarea\n          value={detail}\n          onChange={(e) => setDetail(e.target.value)}\n          rows={3}\n          placeholder=\"What happened?\"\n          className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#EF4444] outline-none resize-none\"\n        />\n\n        <div className=\"flex gap-2\">\n          <button\n            onClick={onClose}\n            className=\"flex-1 bg-[#1F2937] hover:bg-[#374151] text-[#94A3B8] font-black uppercase tracking-widest text-xs py-3.5 rounded-xl transition-colors\"\n          >\n            Cancel\n          </button>\n          <button\n            disabled={busy || !reason}\n            onClick={submit}\n            className=\"flex-[2] bg-[#EF4444] hover:bg-[#DC2626] disabled:opacity-40 text-white font-black uppercase tracking-widest text-xs py-3.5 rounded-xl transition-colors\"\n          >\n            {busy ? \"Raising...\" : \"Raise it\"}\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n}\n");

write("app/wallet/page.tsx", "\"use client\";\n\nimport React, { useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport {\n  ArrowLeft,\n  ShieldCheck,\n  LogOut,\n  Send,\n  ArrowDownToLine,\n  PlusCircle,\n  PiggyBank,\n  Users,\n  Receipt,\n  Store,\n  Scale,\n  Lock,\n  LineChart,\n  Phone,\n  AlertCircle,\n} from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\nimport AppMenu from \"../components/AppMenu\";\nimport { useKpcBalance } from \"../lib/useKpcBalance\";\nimport { formatKpcAsUsd } from \"../lib/kpcPeg\";\nimport PinSetup from \"../components/PinSetup\";\n\nexport default function WalletPage() {\n  const [currentUser, setCurrentUser] = useState<{ id: string; phone: string } | null>(null);\n  const [checkingSession, setCheckingSession] = useState(true);\n  // Staff get one extra link. am_i_staff is the same gate the admin readers\n  // use, so this cannot show a door that will not open.\n  const [isStaff, setIsStaff] = useState(false);\n  // A PIN is what stands between an unlocked phone and an empty wallet, so\n  // the prompt to set one is not buried in a settings page.\n  const [hasPin, setHasPin] = useState<boolean | null>(null);\n  const [pinSetup, setPinSetup] = useState(false);\n\n  const { balance, loading: balanceLoading } = useKpcBalance(currentUser?.id ?? null);\n\n  useEffect(() => {\n    supabase.auth.getSession().then(({ data }) => {\n      if (data.session) {\n        setCurrentUser({\n          id: data.session.user.id,\n          phone: data.session.user.phone ?? \"Unknown\",\n        });\n        supabase.rpc(\"am_i_staff\").then(({ data: s }) => setIsStaff(Boolean(s)));\n        supabase.rpc(\"my_pin_status\").then(({ data: p }) => {\n          setHasPin(Boolean((p as { has_pin?: boolean } | null)?.has_pin));\n        });\n      }\n      setCheckingSession(false);\n    });\n  }, []);\n\n  const handleSignOut = async () => {\n    await supabase.auth.signOut();\n    window.location.href = \"/auth\";\n  };\n\n  const formatPhone = (phone?: string) => {\n    if (!phone || phone === \"Unknown\") return \"Unknown\";\n    return phone.startsWith(\"+\") ? phone : `+${phone}`;\n  };\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white flex flex-col items-center justify-center p-5 lg:p-8 font-sans selection:bg-[#AA771C]/30 relative overflow-hidden\">\n      {/* Background ambient glow */}\n      <div className=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] bg-gradient-to-br from-[#FDB813]/5 to-transparent rounded-full blur-[100px] pointer-events-none\" />\n\n      <div className=\"bg-[#111827]/80 backdrop-blur-xl border border-[#1F2937] p-10 rounded-[2rem] shadow-[0_0_80px_rgba(0,0,0,0.8)] max-w-lg w-full text-center relative z-10\">\n        <div className=\"flex justify-between items-start w-full mb-8\">\n          <Link\n            href=\"/\"\n            className=\"text-[#94A3B8] hover:text-[#FDB813] transition-colors p-2 bg-[#1F2937] rounded-lg border border-[#374151]\"\n          >\n            <ArrowLeft size={20} />\n          </Link>\n          <AppMenu />\n          <div className=\"flex items-center gap-2 text-[10px] font-mono tracking-widest uppercase bg-[#0A0E14] px-3 py-1.5 rounded-full border border-[#1F2937]\">\n            {currentUser ? (\n              <>\n                <div className=\"w-2 h-2 bg-[#10B981] rounded-full animate-pulse shadow-[0_0_8px_#10b981]\" />\n                <span className=\"text-[#10B981]\">Connected</span>\n              </>\n            ) : (\n              <>\n                <div className=\"w-2 h-2 bg-[#EF4444] rounded-full\" />\n                <span className=\"text-[#EF4444]\">Disconnected</span>\n              </>\n            )}\n          </div>\n        </div>\n\n        <h1 className=\"text-3xl font-black uppercase tracking-widest mb-1 text-white\">\n          Your wallet\n        </h1>\n        <p className=\"text-[10px] font-mono text-[#94A3B8] tracking-widest uppercase mb-8\">\n          Your real KPC balance, $1-pegged, always\n        </p>\n\n        {checkingSession ? (\n          <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-6\">\n            Loading...\n          </p>\n        ) : !currentUser ? (\n          <div className=\"flex flex-col items-center justify-center py-6 gap-6\">\n            <div className=\"bg-[#111827] border border-[#1F2937] p-6 rounded-xl flex items-start gap-4 w-full text-left\">\n              <AlertCircle className=\"text-[#94A3B8] shrink-0\" size={24} />\n              <p className=\"text-xs font-mono text-[#94A3B8] leading-relaxed uppercase\">\n                Please{\" \"}\n                <Link href=\"/auth\" className=\"font-bold underline\">\n                  sign in\n                </Link>{\" \"}\n                to see your wallet.\n              </p>\n            </div>\n          </div>\n        ) : (\n          <div className=\"space-y-4 mb-2\">\n            {/* Identity */}\n            <div className=\"bg-[#0A0E14] border border-[#1F2937] p-5 rounded-xl flex justify-between items-center text-left\">\n              <div>\n                <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n                  Authenticated Identity\n                </span>\n                <span className=\"flex items-center gap-2 text-lg font-mono font-black text-white\">\n                  <Phone size={16} className=\"text-[#94A3B8]\" />\n                  {formatPhone(currentUser.phone)}\n                </span>\n              </div>\n              <ShieldCheck className=\"text-[#10B981]\" size={24} />\n            </div>\n\n            {/* Balance */}\n            <div className=\"bg-[#0A0E14] border border-[#1F2937] p-5 rounded-xl text-left\">\n              <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n                KPC Balance\n              </span>\n              {balanceLoading ? (\n                <span className=\"text-sm font-mono text-[#94A3B8] uppercase\">Loading...</span>\n              ) : (\n                <div className=\"flex items-baseline gap-3\">\n                  <span className=\"text-3xl font-black text-[#FDB813]\">\n                    {(balance ?? 0).toLocaleString()} <span className=\"text-sm text-white\">KPC</span>\n                  </span>\n                  <span className=\"text-xs font-mono text-[#94A3B8]\">\n                    ≈ {formatKpcAsUsd(balance ?? 0)}\n                  </span>\n                </div>\n              )}\n            </div>\n\n            {/* Quick actions */}\n            <div className=\"grid grid-cols-3 gap-2 pt-2\">\n              <Link\n                href=\"/send\"\n                className=\"flex flex-col items-center justify-center gap-2 py-4 bg-[#1F2937] hover:bg-[#FDB813]/10 border border-[#374151] hover:border-[#FDB813]/50 transition-all rounded-xl\"\n              >\n                <Send size={18} className=\"text-[#FDB813]\" />\n                <span className=\"text-[9px] font-mono uppercase tracking-widest text-[#94A3B8]\">\n                  Send\n                </span>\n              </Link>\n              <Link\n                href=\"/withdraw\"\n                className=\"flex flex-col items-center justify-center gap-2 py-4 bg-[#1F2937] hover:bg-[#FDB813]/10 border border-[#374151] hover:border-[#FDB813]/50 transition-all rounded-xl\"\n              >\n                <ArrowDownToLine size={18} className=\"text-[#FDB813]\" />\n                <span className=\"text-[9px] font-mono uppercase tracking-widest text-[#94A3B8]\">\n                  Withdraw\n                </span>\n              </Link>\n              <Link\n                href=\"/\"\n                className=\"flex flex-col items-center justify-center gap-2 py-4 bg-[#1F2937] hover:bg-[#FDB813]/10 border border-[#374151] hover:border-[#FDB813]/50 transition-all rounded-xl\"\n              >\n                <PlusCircle size={18} className=\"text-[#FDB813]\" />\n                <span className=\"text-[9px] font-mono uppercase tracking-widest text-[#94A3B8]\">\n                  Buy KPC\n                </span>\n              </Link>\n              {/* Savings earns money sitting still, so it gets the green of the\n                  savings page rather than the gold of the spending actions. */}\n              <Link\n                href=\"/savings\"\n                className=\"flex flex-col items-center justify-center gap-2 py-4 bg-[#1F2937] hover:bg-[#10B981]/10 border border-[#374151] hover:border-[#10B981]/50 transition-all rounded-xl\"\n              >\n                <PiggyBank size={18} className=\"text-[#10B981]\" />\n                <span className=\"text-[9px] font-mono uppercase tracking-widest text-[#94A3B8]\">\n                  Save\n                </span>\n              </Link>\n              {/* Circles are social rather than solitary, so they take the\n                  brand gold rather than the savings green. */}\n              <Link\n                href=\"/circles\"\n                className=\"flex flex-col items-center justify-center gap-2 py-4 bg-[#1F2937] hover:bg-[#FDB813]/10 border border-[#374151] hover:border-[#FDB813]/50 transition-all rounded-xl\"\n              >\n                <Users size={18} className=\"text-[#FDB813]\" />\n                <span className=\"text-[9px] font-mono uppercase tracking-widest text-[#94A3B8]\">\n                  Circles\n                </span>\n              </Link>\n              {/* Every movement of their money, and the only route to raising\n                  a dispute. */}\n              <Link\n                href=\"/activity\"\n                className=\"flex flex-col items-center justify-center gap-2 py-4 bg-[#1F2937] hover:bg-[#FDB813]/10 border border-[#374151] hover:border-[#FDB813]/50 transition-all rounded-xl\"\n              >\n                <Receipt size={18} className=\"text-[#FDB813]\" />\n                <span className=\"text-[9px] font-mono uppercase tracking-widest text-[#94A3B8]\">\n                  Activity\n                </span>\n              </Link>\n            </div>\n\n            {/* Limits live where people look when something is refused. */}\n            <Link\n              href=\"/limits\"\n              className=\"mt-3 flex items-center justify-center gap-2 py-3 bg-[#1F2937] hover:bg-[#FDB813]/10 border border-[#374151] hover:border-[#FDB813]/50 transition-all rounded-lg\"\n            >\n              <ShieldCheck size={14} className=\"text-[#FDB813]\" />\n              <span className=\"text-[9px] font-mono uppercase tracking-widest text-[#94A3B8]\">\n                Limits &amp; verification\n              </span>\n            </Link>\n\n            {hasPin === false && (\n              <button\n                onClick={() => setPinSetup(true)}\n                className=\"mt-3 w-full flex items-center justify-center gap-2 py-3 bg-[#FDB813]/10 border border-[#FDB813]/40 rounded-lg\"\n              >\n                <Lock size={14} className=\"text-[#FDB813]\" />\n                <span className=\"text-[9px] font-mono uppercase tracking-widest text-[#FDB813]\">\n                  Set a payment PIN\n                </span>\n              </button>\n            )}\n            {hasPin === true && (\n              <button\n                onClick={() => setPinSetup(true)}\n                className=\"mt-3 w-full flex items-center justify-center gap-2 py-3 bg-[#1F2937] hover:bg-[#374151] border border-[#374151] rounded-lg\"\n              >\n                <Lock size={14} className=\"text-[#94A3B8]\" />\n                <span className=\"text-[9px] font-mono uppercase tracking-widest text-[#94A3B8]\">\n                  Change PIN\n                </span>\n              </button>\n            )}\n\n            {/* Deliberately not in the grid with Save. Savings is a promise\n                at a fixed rate; this is money that can fall in value, and\n                putting them side by side as equivalent choices would be the\n                most misleading thing on the page. */}\n            <Link\n              href=\"/invest\"\n              className=\"mt-3 flex items-center justify-center gap-2 py-3 bg-[#1F2937] hover:bg-[#10B981]/10 border border-[#374151] hover:border-[#10B981]/50 transition-all rounded-lg\"\n            >\n              <LineChart size={14} className=\"text-[#10B981]\" />\n              <span className=\"text-[9px] font-mono uppercase tracking-widest text-[#94A3B8]\">\n                Invest\n              </span>\n            </Link>\n\n            {/* Not a seventh tile. Taking payments is a different mode from\n                spending, and a merchant visits this once then lives on that\n                page — it should not compete with Send for attention. */}\n            <Link\n              href=\"/merchant\"\n              className=\"mt-2 flex items-center justify-center gap-2 py-3 bg-[#1F2937] hover:bg-[#FDB813]/10 border border-[#374151] hover:border-[#FDB813]/50 transition-all rounded-lg\"\n            >\n              <Store size={14} className=\"text-[#FDB813]\" />\n              <span className=\"text-[9px] font-mono uppercase tracking-widest text-[#94A3B8]\">\n                Take payments\n              </span>\n            </Link>\n\n            {isStaff && (\n              <Link\n                href=\"/admin\"\n                className=\"mt-2 flex items-center justify-center gap-2 py-3 bg-[#1F2937] hover:bg-[#FDB813]/10 border border-[#374151] hover:border-[#FDB813]/50 transition-all rounded-lg\"\n              >\n                <Scale size={14} className=\"text-[#FDB813]\" />\n                <span className=\"text-[9px] font-mono uppercase tracking-widest text-[#94A3B8]\">\n                  Operations\n                </span>\n              </Link>\n            )}\n\n            <button\n              onClick={handleSignOut}\n              className=\"w-full mt-4 flex items-center justify-center gap-2 py-3 bg-[#1F2937] hover:bg-[#EF4444]/20 text-[#94A3B8] hover:text-[#EF4444] border border-[#374151] hover:border-[#EF4444]/50 transition-all rounded-lg font-mono text-[10px] uppercase font-bold tracking-widest\"\n            >\n              <LogOut size={14} /> Sign Out\n            </button>\n          </div>\n        )}\n      </div>\n\n      {pinSetup && (\n        <PinSetup\n          hasPin={Boolean(hasPin)}\n          onClose={() => setPinSetup(false)}\n          onDone={() => setHasPin(true)}\n        />\n      )}\n    </div>\n  );\n}");

write("app/savings/page.tsx", "\"use client\";\n\nimport React, { useCallback, useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport {\n  ArrowLeft, PiggyBank, Lock, Target, Zap, Plus, Minus,\n  Pause, Play, AlertTriangle, TrendingUp, Clock,\n} from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\nimport AppMenu from \"../components/AppMenu\";\nimport { useKpcBalance } from \"../lib/useKpcBalance\";\nimport { formatKpcAsUsd } from \"../lib/kpcPeg\";\nimport toast, { Toaster } from \"react-hot-toast\";\n\n// The five functions 005 grants to `authenticated`. Each one checks auth.uid()\n// and plan ownership in SQL, so calling them straight from the browser is safe\n// and saves an API hop. Everything else in 005 is service-role only.\ntype Product = {\n  id: string;\n  name: string;\n  blurb: string | null;\n  apy_bps: number;\n  locked: boolean;\n  min_days: number;\n  max_days: number | null;\n  min_amount: number;\n  break_fee_bps: number;\n  withdrawals_per_month: number | null;\n};\n\ntype Plan = {\n  id: string;\n  reference: string;\n  name: string;\n  product_id: string;\n  product_name: string;\n  product_blurb: string | null;\n  principal: number;\n  target_amount: number | null;\n  percent_of_target: number | null;\n  rate_percent: number;\n  locked_until: string | null;\n  locked_now: boolean;\n  interest_waiting: number;\n  interest_paid: number;\n  interest_owed: number;\n  break_would_cost: number;\n  autosave_amount: number | null;\n  autosave_cadence: string | null;\n  autosave_next: string | null;\n  status: string;\n  withdrawals_per_month: number | null;\n  withdrawals_this_month: number;\n};\n\nconst ICON: Record<string, React.ReactNode> = {\n  flex: <Zap size={13} />,\n  lock: <Lock size={13} />,\n  target: <Target size={13} />,\n};\n\nconst num = (v: unknown) => Number(v ?? 0);\n\nexport default function SavingsPage() {\n  const [userId, setUserId] = useState<string | null>(null);\n  const [checkingSession, setCheckingSession] = useState(true);\n\n  const [products, setProducts] = useState<Product[]>([]);\n  const [plans, setPlans] = useState<Plan[]>([]);\n  const [loadingPlans, setLoadingPlans] = useState(true);\n\n  const [showOpen, setShowOpen] = useState(false);\n  const [busy, setBusy] = useState<string | null>(null);\n\n  const { balance: wallet, loading: walletLoading } = useKpcBalance(userId, \"user\");\n\n  useEffect(() => {\n    supabase.auth.getSession().then(({ data }) => {\n      setUserId(data.session?.user.id ?? null);\n      setCheckingSession(false);\n    });\n  }, []);\n\n  const load = useCallback(async () => {\n    if (!userId) return;\n    setLoadingPlans(true);\n    const [{ data: prod }, { data: mine, error }] = await Promise.all([\n      supabase.from(\"savings_products\").select(\"*\").order(\"apy_bps\"),\n      supabase.from(\"my_savings\").select(\"*\").order(\"created_at\", { ascending: false }),\n    ]);\n    if (error) toast.error(\"Could not load your savings\");\n    setProducts((prod ?? []) as Product[]);\n    setPlans((mine ?? []) as Plan[]);\n    setLoadingPlans(false);\n  }, [userId]);\n\n  useEffect(() => {\n    void load();\n  }, [load]);\n\n  // Every action is one RPC. The database does the validating, so the only job\n  // here is to report what it said and reload.\n  const call = async (fn: string, args: Record<string, unknown>, success: string, key: string) => {\n    setBusy(key);\n    try {\n      const { error } = await supabase.rpc(fn, args);\n      if (error) {\n        // These messages are written for the customer in 005 — limits, locks,\n        // insufficient balance — so they are shown rather than flattened.\n        toast.error(error.message, { duration: 6000 });\n        return false;\n      }\n      toast.success(success);\n      await load();\n      return true;\n    } catch {\n      toast.error(\"Network error — please try again\");\n      return false;\n    } finally {\n      setBusy(null);\n    }\n  };\n\n  const totalSaved = plans\n    .filter((p) => [\"active\", \"paused\", \"matured\"].includes(p.status))\n    .reduce((s, p) => s + num(p.principal), 0);\n  const totalInterest = plans.reduce((s, p) => s + num(p.interest_waiting), 0);\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white font-sans selection:bg-[#AA771C]/30 relative overflow-hidden\">\n      <Toaster position=\"top-center\" reverseOrder={false} />\n      <div className=\"absolute top-0 left-1/2 -translate-x-1/2 w-[900px] h-[900px] bg-gradient-to-br from-[#10B981]/5 to-transparent rounded-full blur-[120px] pointer-events-none\" />\n\n      <div className=\"relative z-10 max-w-3xl mx-auto px-5 py-8 sm:px-8\">\n        {/* header */}\n        <div className=\"flex justify-between items-start mb-8\">\n          <Link\n            href=\"/wallet\"\n            className=\"text-[#94A3B8] hover:text-[#FDB813] transition-colors p-2 bg-[#1F2937] rounded-lg border border-[#374151]\"\n          >\n            <ArrowLeft size={20} />\n          </Link>\n          <AppMenu />\n          <div className=\"flex items-center gap-2 text-[10px] font-mono tracking-widest uppercase bg-[#0A0E14] px-3 py-1.5 rounded-full border border-[#1F2937]\">\n            <PiggyBank size={12} className=\"text-[#10B981]\" />\n            <span className=\"text-[#10B981]\">Savings</span>\n          </div>\n        </div>\n\n        <h1 className=\"text-3xl font-black uppercase tracking-widest mb-1\">Savings</h1>\n        <p className=\"text-[10px] font-mono text-[#94A3B8] tracking-widest uppercase mb-8\">\n          Break a plan early and you forfeit interest — never your money\n        </p>\n\n        {checkingSession ? (\n          <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-10 text-center\">\n            Loading...\n          </p>\n        ) : !userId ? (\n          <div className=\"bg-[#EF4444]/10 border border-[#EF4444]/30 p-6 rounded-xl\">\n            <p className=\"text-xs font-mono text-[#EF4444] leading-relaxed uppercase\">\n              Please{\" \"}\n              <Link href=\"/auth\" className=\"font-bold underline\">\n                sign in\n              </Link>{\" \"}\n              to save.\n            </p>\n          </div>\n        ) : (\n          <>\n            {/* the three numbers that matter */}\n            <div className=\"grid grid-cols-3 gap-3 mb-6\">\n              <Stat label=\"Spendable\" value={walletLoading ? null : num(wallet)} />\n              <Stat label=\"Saved\" value={totalSaved} accent=\"#10B981\" />\n              <Stat label=\"Interest waiting\" value={totalInterest} accent=\"#FDB813\" decimals={4} />\n            </div>\n\n            <button\n              onClick={() => setShowOpen((s) => !s)}\n              className=\"w-full mb-6 flex items-center justify-center gap-2 bg-[#10B981] hover:bg-[#0E9F6E] text-[#0A0E14] font-black uppercase tracking-widest text-xs py-4 rounded-xl transition-colors\"\n            >\n              <Plus size={16} /> {showOpen ? \"Close\" : \"Start a new plan\"}\n            </button>\n\n            {showOpen && (\n              <OpenPlan\n                products={products}\n                wallet={num(wallet)}\n                busy={busy === \"open\"}\n                onOpen={async (args) => {\n                  const ok = await call(\"open_savings_plan\", args, \"Plan opened\", \"open\");\n                  if (ok) setShowOpen(false);\n                }}\n              />\n            )}\n\n            {loadingPlans ? (\n              <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-10 text-center\">\n                Loading your plans...\n              </p>\n            ) : plans.length === 0 ? (\n              <div className=\"bg-[#111827]/80 border border-[#1F2937] rounded-2xl p-8 text-center\">\n                <PiggyBank size={28} className=\"mx-auto text-[#374151] mb-3\" />\n                <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest leading-relaxed\">\n                  No plans yet.\n                  <br />\n                  Lock earns {((products.find((p) => p.id === \"lock\")?.apy_bps ?? 1300) / 100).toFixed(0)}% a year.\n                </p>\n              </div>\n            ) : (\n              <div className=\"space-y-3\">\n                {plans.map((p) => (\n                  <PlanCard\n                    key={p.id}\n                    plan={p}\n                    wallet={num(wallet)}\n                    busy={busy}\n                    onFund={(amount) =>\n                      call(\"fund_savings_plan\", { p_plan: p.id, p_amount: amount }, \"Added to \" + p.name, p.id + \":fund\")\n                    }\n                    onWithdraw={(amount) =>\n                      call(\n                        \"withdraw_savings\",\n                        { p_plan: p.id, p_amount: amount },\n                        amount === null ? \"Closed and returned\" : \"Withdrawn\",\n                        p.id + \":out\",\n                      )\n                    }\n                    onPause={() =>\n                      call(\"pause_savings_plan\", { p_plan: p.id }, \"Paused — your rate is unchanged\", p.id + \":pause\")\n                    }\n                    onResume={() => call(\"resume_savings_plan\", { p_plan: p.id }, \"Resumed\", p.id + \":pause\")}\n                  />\n                ))}\n              </div>\n            )}\n\n            <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.2em] text-center mt-10 leading-relaxed\">\n              1 KPC = $1.00 · interest accrues daily\n              <br />\n              {formatKpcAsUsd(totalSaved)} saved\n            </p>\n          </>\n        )}\n      </div>\n    </div>\n  );\n}\n\n/* ------------------------------------------------------------------ */\n\nfunction Stat({\n  label,\n  value,\n  accent = \"#FFFFFF\",\n  decimals = 2,\n}: {\n  label: string;\n  value: number | null;\n  accent?: string;\n  decimals?: number;\n}) {\n  return (\n    <div className=\"bg-[#0A0E14] border border-[#1F2937] p-4 rounded-xl\">\n      <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n        {label}\n      </span>\n      {value === null ? (\n        <span className=\"text-xs font-mono text-[#94A3B8]\">...</span>\n      ) : (\n        <span className=\"text-base font-black leading-none\" style={{ color: accent }}>\n          {value.toLocaleString(undefined, { maximumFractionDigits: decimals })}\n          <span className=\"text-[9px] text-[#94A3B8] ml-1\">KPC</span>\n        </span>\n      )}\n    </div>\n  );\n}\n\nfunction OpenPlan({\n  products,\n  wallet,\n  busy,\n  onOpen,\n}: {\n  products: Product[];\n  wallet: number;\n  busy: boolean;\n  onOpen: (args: Record<string, unknown>) => void;\n}) {\n  const [productId, setProductId] = useState(\"lock\");\n  const [name, setName] = useState(\"\");\n  const [amount, setAmount] = useState(\"\");\n  const [lockDays, setLockDays] = useState(\"90\");\n  const [target, setTarget] = useState(\"\");\n  const [autosave, setAutosave] = useState(\"\");\n  const [cadence, setCadence] = useState(\"monthly\");\n\n  const product = products.find((p) => p.id === productId);\n\n  const submit = () => {\n    if (!name.trim()) return toast.error(\"Give the plan a name\");\n    const amt = parseFloat(amount || \"0\");\n    if (amt > 0 && amt > wallet) return toast.error(\"That is more than your wallet holds\");\n\n    onOpen({\n      p_product: productId,\n      p_name: name.trim(),\n      p_initial: amt || 0,\n      p_target: productId === \"target\" && target ? parseFloat(target) : null,\n      p_lock_days: product?.locked ? parseInt(lockDays, 10) : null,\n      p_autosave: autosave ? parseFloat(autosave) : null,\n      p_cadence: autosave ? cadence : null,\n    });\n  };\n\n  return (\n    <div className=\"bg-[#111827]/80 backdrop-blur-xl border border-[#1F2937] rounded-2xl p-5 mb-6 space-y-4\">\n      <div className=\"grid grid-cols-3 gap-2\">\n        {products.map((p) => (\n          <button\n            key={p.id}\n            onClick={() => setProductId(p.id)}\n            className={`p-3 rounded-xl border text-left transition-colors ${\n              productId === p.id\n                ? \"border-[#10B981] bg-[#10B981]/10\"\n                : \"border-[#1F2937] bg-[#0A0E14] hover:border-[#374151]\"\n            }`}\n          >\n            <span className=\"flex items-center gap-1.5 text-[9px] font-mono uppercase tracking-[0.15em] text-[#94A3B8] mb-1\">\n              {ICON[p.id]} {p.name}\n            </span>\n            <span className=\"block text-sm font-black text-white\">\n              {(p.apy_bps / 100).toFixed(0)}%\n            </span>\n          </button>\n        ))}\n      </div>\n\n      {product?.blurb && (\n        <p className=\"text-[10px] font-mono text-[#94A3B8] leading-relaxed\">{product.blurb}</p>\n      )}\n\n      <Field label=\"What is it for\">\n        <input\n          value={name}\n          onChange={(e) => setName(e.target.value)}\n          placeholder=\"School fees\"\n          maxLength={60}\n          className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#10B981] outline-none\"\n        />\n      </Field>\n\n      <div className=\"grid grid-cols-2 gap-3\">\n        <Field label={`Start with (you have ${wallet.toLocaleString()})`}>\n          <input\n            value={amount}\n            onChange={(e) => setAmount(e.target.value)}\n            inputMode=\"decimal\"\n            placeholder=\"0\"\n            className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#10B981] outline-none\"\n          />\n        </Field>\n\n        {product?.locked ? (\n          <Field label={`Lock for (${product.min_days}–${product.max_days ?? 730} days)`}>\n            <input\n              value={lockDays}\n              onChange={(e) => setLockDays(e.target.value)}\n              inputMode=\"numeric\"\n              className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white focus:border-[#10B981] outline-none\"\n            />\n          </Field>\n        ) : productId === \"target\" ? (\n          <Field label=\"Goal amount\">\n            <input\n              value={target}\n              onChange={(e) => setTarget(e.target.value)}\n              inputMode=\"decimal\"\n              placeholder=\"500\"\n              className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#10B981] outline-none\"\n            />\n          </Field>\n        ) : (\n          <Field label=\"Withdrawals a month\">\n            <div className=\"px-3 py-2.5 text-sm font-mono text-[#94A3B8]\">\n              {product?.withdrawals_per_month ?? \"Unlimited\"}\n            </div>\n          </Field>\n        )}\n      </div>\n\n      <div className=\"grid grid-cols-2 gap-3\">\n        <Field label=\"Add automatically (optional)\">\n          <input\n            value={autosave}\n            onChange={(e) => setAutosave(e.target.value)}\n            inputMode=\"decimal\"\n            placeholder=\"0\"\n            className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#10B981] outline-none\"\n          />\n        </Field>\n        <Field label=\"How often\">\n          <select\n            value={cadence}\n            onChange={(e) => setCadence(e.target.value)}\n            disabled={!autosave}\n            className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white focus:border-[#10B981] outline-none disabled:opacity-40\"\n          >\n            <option value=\"daily\">Every day</option>\n            <option value=\"weekly\">Every week</option>\n            <option value=\"monthly\">Every month</option>\n          </select>\n        </Field>\n      </div>\n\n      {product?.locked && (\n        <div className=\"flex gap-2 bg-[#FDB813]/10 border border-[#FDB813]/30 rounded-lg p-3\">\n          <AlertTriangle size={14} className=\"text-[#FDB813] shrink-0 mt-0.5\" />\n          <p className=\"text-[10px] font-mono text-[#FDB813] leading-relaxed\">\n            Breaking this early forfeits {(product.break_fee_bps / 100).toFixed(0)}% of the interest\n            you have earned. Your deposit always comes back in full.\n          </p>\n        </div>\n      )}\n\n      <button\n        onClick={submit}\n        disabled={busy}\n        className=\"w-full bg-[#10B981] hover:bg-[#0E9F6E] disabled:opacity-40 text-[#0A0E14] font-black uppercase tracking-widest text-xs py-3.5 rounded-xl transition-colors\"\n      >\n        {busy ? \"Opening...\" : \"Open plan\"}\n      </button>\n    </div>\n  );\n}\n\nfunction Field({ label, children }: { label: string; children: React.ReactNode }) {\n  return (\n    <label className=\"block\">\n      <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1.5\">\n        {label}\n      </span>\n      {children}\n    </label>\n  );\n}\n\nfunction PlanCard({\n  plan,\n  wallet,\n  busy,\n  onFund,\n  onWithdraw,\n  onPause,\n  onResume,\n}: {\n  plan: Plan;\n  wallet: number;\n  busy: string | null;\n  onFund: (amount: number) => void;\n  onWithdraw: (amount: number | null) => void;\n  onPause: () => void;\n  onResume: () => void;\n}) {\n  const [open, setOpen] = useState<\"none\" | \"fund\" | \"out\">(\"none\");\n  const [amount, setAmount] = useState(\"\");\n  const [confirmBreak, setConfirmBreak] = useState(false);\n\n  const closed = [\"closed\", \"broken\"].includes(plan.status);\n  const principal = num(plan.principal);\n  const waiting = num(plan.interest_waiting);\n  const breakCost = num(plan.break_would_cost);\n\n  const act = (kind: \"fund\" | \"out\") => {\n    const amt = parseFloat(amount || \"0\");\n    if (!amt || amt <= 0) return toast.error(\"Enter an amount\");\n    if (kind === \"fund\" && amt > wallet) return toast.error(\"More than your wallet holds\");\n    if (kind === \"out\" && amt > principal) return toast.error(\"More than this plan holds\");\n    kind === \"fund\" ? onFund(amt) : onWithdraw(amt);\n    setAmount(\"\");\n    setOpen(\"none\");\n  };\n\n  return (\n    <div\n      className={`bg-[#111827]/80 backdrop-blur-xl border rounded-2xl p-5 ${\n        closed ? \"border-[#1F2937] opacity-60\" : \"border-[#1F2937]\"\n      }`}\n    >\n      <div className=\"flex justify-between items-start gap-3 mb-3\">\n        <div className=\"min-w-0\">\n          <span className=\"flex items-center gap-1.5 text-[9px] font-mono uppercase tracking-[0.15em] text-[#94A3B8] mb-1\">\n            {ICON[plan.product_id]} {plan.product_name} · {plan.rate_percent}%\n            {plan.locked_now && plan.locked_until && (\n              <span className=\"text-[#FDB813] normal-case tracking-normal\">\n                · locked to {new Date(plan.locked_until).toLocaleDateString()}\n              </span>\n            )}\n            {plan.status === \"paused\" && <span className=\"text-[#FDB813]\">· paused</span>}\n            {plan.status === \"matured\" && <span className=\"text-[#10B981]\">· matured</span>}\n            {closed && <span>· {plan.status}</span>}\n          </span>\n          <h3 className=\"text-base font-bold text-white truncate\">{plan.name}</h3>\n        </div>\n        <div className=\"text-right shrink-0\">\n          <span className=\"block text-lg font-black text-white leading-none\">\n            {principal.toLocaleString(undefined, { maximumFractionDigits: 2 })}\n          </span>\n          <span className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em]\">KPC</span>\n        </div>\n      </div>\n\n      {plan.target_amount && plan.percent_of_target !== null && (\n        <div className=\"mb-3\">\n          <div className=\"h-1.5 bg-[#0A0E14] rounded-full overflow-hidden border border-[#1F2937]\">\n            <div\n              className=\"h-full bg-[#10B981] transition-all\"\n              style={{ width: `${Math.min(num(plan.percent_of_target), 100)}%` }}\n            />\n          </div>\n          <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mt-1.5\">\n            {num(plan.percent_of_target)}% of {num(plan.target_amount).toLocaleString()} KPC\n          </span>\n        </div>\n      )}\n\n      <div className=\"flex flex-wrap gap-x-5 gap-y-1 text-[9px] font-mono uppercase tracking-[0.15em] mb-4\">\n        <span className=\"text-[#FDB813]\">\n          <TrendingUp size={10} className=\"inline mb-0.5 mr-1\" />\n          {waiting.toLocaleString(undefined, { maximumFractionDigits: 4 })} interest waiting\n        </span>\n        {plan.autosave_amount && plan.autosave_next && (\n          <span className=\"text-[#94A3B8]\">\n            <Clock size={10} className=\"inline mb-0.5 mr-1\" />\n            {num(plan.autosave_amount)} {plan.autosave_cadence} · next{\" \"}\n            {new Date(plan.autosave_next).toLocaleDateString()}\n          </span>\n        )}\n        {plan.withdrawals_per_month !== null && !plan.locked_now && (\n          <span className=\"text-[#94A3B8]\">\n            {plan.withdrawals_per_month - plan.withdrawals_this_month} of{\" \"}\n            {plan.withdrawals_per_month} withdrawals left\n          </span>\n        )}\n        {num(plan.interest_owed) > 0 && (\n          <span className=\"text-[#EF4444]\">\n            {num(plan.interest_owed).toFixed(4)} interest owed to you — being paid\n          </span>\n        )}\n      </div>\n\n      {!closed && (\n        <>\n          <div className=\"flex gap-2\">\n            <button\n              onClick={() => setOpen(open === \"fund\" ? \"none\" : \"fund\")}\n              className=\"flex-1 flex items-center justify-center gap-1.5 bg-[#1F2937] hover:bg-[#374151] border border-[#374151] text-white font-mono uppercase tracking-widest text-[10px] py-2.5 rounded-lg transition-colors\"\n            >\n              <Plus size={12} /> Add\n            </button>\n\n            {plan.locked_now ? (\n              <button\n                onClick={() => setConfirmBreak(true)}\n                className=\"flex-1 flex items-center justify-center gap-1.5 bg-[#1F2937] hover:bg-[#EF4444]/20 border border-[#374151] hover:border-[#EF4444]/40 text-[#94A3B8] hover:text-[#EF4444] font-mono uppercase tracking-widest text-[10px] py-2.5 rounded-lg transition-colors\"\n              >\n                <Lock size={12} /> Break\n              </button>\n            ) : (\n              <button\n                onClick={() => setOpen(open === \"out\" ? \"none\" : \"out\")}\n                className=\"flex-1 flex items-center justify-center gap-1.5 bg-[#1F2937] hover:bg-[#374151] border border-[#374151] text-white font-mono uppercase tracking-widest text-[10px] py-2.5 rounded-lg transition-colors\"\n              >\n                <Minus size={12} /> Take out\n              </button>\n            )}\n\n            {plan.autosave_amount !== null && (\n              <button\n                onClick={plan.status === \"paused\" ? onResume : onPause}\n                disabled={busy === plan.id + \":pause\"}\n                title={plan.status === \"paused\" ? \"Resume automatic deposits\" : \"Pause automatic deposits\"}\n                className=\"px-3 bg-[#1F2937] hover:bg-[#374151] border border-[#374151] text-[#94A3B8] rounded-lg transition-colors disabled:opacity-40\"\n              >\n                {plan.status === \"paused\" ? <Play size={12} /> : <Pause size={12} />}\n              </button>\n            )}\n          </div>\n\n          {open !== \"none\" && (\n            <div className=\"flex gap-2 mt-3\">\n              <input\n                value={amount}\n                onChange={(e) => setAmount(e.target.value)}\n                inputMode=\"decimal\"\n                autoFocus\n                placeholder={open === \"fund\" ? `Up to ${wallet.toLocaleString()}` : `Up to ${principal.toLocaleString()}`}\n                className=\"flex-1 bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#10B981] outline-none\"\n              />\n              <button\n                onClick={() => act(open === \"fund\" ? \"fund\" : \"out\")}\n                disabled={busy === plan.id + \":fund\" || busy === plan.id + \":out\"}\n                className=\"px-5 bg-[#10B981] hover:bg-[#0E9F6E] disabled:opacity-40 text-[#0A0E14] font-black uppercase tracking-widest text-[10px] rounded-lg transition-colors\"\n              >\n                Go\n              </button>\n            </div>\n          )}\n\n          {open === \"out\" && plan.status !== \"paused\" && (\n            <button\n              onClick={() => onWithdraw(null)}\n              className=\"w-full mt-2 text-[9px] font-mono text-[#94A3B8] hover:text-white uppercase tracking-[0.2em] py-2 transition-colors\"\n            >\n              Take everything and close this plan\n            </button>\n          )}\n        </>\n      )}\n\n      {/* Breaking a lock. The cost is stated in money before anything happens —\n          this is the moment the product either earns trust or loses it. */}\n      {confirmBreak && (\n        <div className=\"mt-4 bg-[#0A0E14] border border-[#EF4444]/40 rounded-xl p-4\">\n          <p className=\"text-[11px] font-mono text-white uppercase tracking-widest mb-3\">\n            Break this lock?\n          </p>\n          <div className=\"space-y-1.5 text-[10px] font-mono mb-4\">\n            <Row label=\"Your deposit, returned in full\" value={`${principal.toLocaleString()} KPC`} tone=\"#10B981\" />\n            <Row\n              label=\"Interest you keep\"\n              value={`${Math.max(waiting - breakCost, 0).toLocaleString(undefined, { maximumFractionDigits: 4 })} KPC`}\n              tone=\"#10B981\"\n            />\n            <Row\n              label=\"Interest forfeited\"\n              value={`${breakCost.toLocaleString(undefined, { maximumFractionDigits: 4 })} KPC`}\n              tone=\"#EF4444\"\n            />\n            <div className=\"pt-2 border-t border-[#1F2937]\">\n              <Row\n                label=\"You receive\"\n                value={`${(principal + Math.max(waiting - breakCost, 0)).toLocaleString(undefined, {\n                  maximumFractionDigits: 4,\n                })} KPC`}\n                tone=\"#FFFFFF\"\n              />\n            </div>\n          </div>\n          <div className=\"flex gap-2\">\n            <button\n              onClick={() => setConfirmBreak(false)}\n              className=\"flex-1 bg-[#1F2937] hover:bg-[#374151] border border-[#374151] text-white font-mono uppercase tracking-widest text-[10px] py-2.5 rounded-lg transition-colors\"\n            >\n              Keep saving\n            </button>\n            <button\n              onClick={() => {\n                setConfirmBreak(false);\n                onWithdraw(null);\n              }}\n              disabled={busy === plan.id + \":out\"}\n              className=\"flex-1 bg-[#EF4444] hover:bg-[#DC2626] disabled:opacity-40 text-white font-black uppercase tracking-widest text-[10px] py-2.5 rounded-lg transition-colors\"\n            >\n              Break it\n            </button>\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n\nfunction Row({ label, value, tone }: { label: string; value: string; tone: string }) {\n  return (\n    <div className=\"flex justify-between gap-3\">\n      <span className=\"text-[#94A3B8] uppercase tracking-[0.15em]\">{label}</span>\n      <span className=\"font-bold shrink-0\" style={{ color: tone }}>\n        {value}\n      </span>\n    </div>\n  );\n}\n");

write("app/invest/page.tsx", "\"use client\";\n\nimport React, { useCallback, useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport {\n  ArrowLeft,\n  TrendingUp,\n  TrendingDown,\n  AlertTriangle,\n  Clock,\n  Loader2,\n  ChevronDown,\n} from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\nimport AppMenu from \"../components/AppMenu\";\nimport { useKpcBalance } from \"../lib/useKpcBalance\";\nimport { formatKpcAsUsd } from \"../lib/kpcPeg\";\nimport toast, { Toaster } from \"react-hot-toast\";\n\ntype Instrument = {\n  id: string;\n  name: string;\n  kind: string;\n  issuer: string;\n  blurb: string | null;\n  risk_note: string;\n  unit_price: number;\n  price_at: string;\n  min_investment: number;\n  exit_fee_bps: number;\n  min_hold_days: number;\n  settles_in_days: number;\n  expected_yield_bps: number | null;\n};\n\ntype Holding = {\n  instrument_id: string;\n  name: string;\n  issuer: string;\n  risk_note: string;\n  units: number;\n  unit_price: number;\n  value: number;\n  invested: number;\n  gain: number;\n  gain_percent: number;\n  price_stale: boolean;\n  settles_in_days: number;\n  exit_fee_bps: number;\n};\n\ntype Redemption = {\n  reference: string;\n  name: string;\n  units: number;\n  net: number;\n  status: string;\n  failure: string | null;\n  settles_on: string;\n};\n\nconst n = (v: unknown) => (typeof v === \"number\" ? v : Number(v ?? 0));\nconst money = (v: unknown) =>\n  n(v).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n\nconst KIND: Record<string, string> = {\n  tbill: \"Treasury bill\",\n  bond: \"Bond\",\n  fund: \"Fund\",\n  note: \"Note\",\n};\n\nexport default function InvestPage() {\n  const [userId, setUserId] = useState<string | null>(null);\n  const [checking, setChecking] = useState(true);\n  const [instruments, setInstruments] = useState<Instrument[]>([]);\n  const [holdings, setHoldings] = useState<Holding[]>([]);\n  const [redemptions, setRedemptions] = useState<Redemption[]>([]);\n  const [open, setOpen] = useState<string | null>(null);\n  const [amount, setAmount] = useState(\"\");\n  const [busy, setBusy] = useState(false);\n\n  const { balance } = useKpcBalance(userId);\n\n  const load = useCallback(async () => {\n    const [i, h, r] = await Promise.all([\n      supabase.from(\"instruments\").select(\"*\").order(\"name\"),\n      supabase.from(\"my_investments\").select(\"*\"),\n      supabase.from(\"my_redemptions\").select(\"*\"),\n    ]);\n    if (i.data) setInstruments(i.data as Instrument[]);\n    if (h.data) setHoldings(h.data as Holding[]);\n    if (r.data) setRedemptions(r.data as Redemption[]);\n  }, []);\n\n  useEffect(() => {\n    supabase.auth.getSession().then(({ data }) => {\n      setUserId(data.session?.user.id ?? null);\n      setChecking(false);\n      if (data.session) load();\n    });\n  }, [load]);\n\n  const buy = async (inst: Instrument) => {\n    const amt = Number(amount);\n    if (!Number.isFinite(amt) || amt <= 0) return;\n    setBusy(true);\n    const { error } = await supabase.rpc(\"invest\", {\n      p_instrument: inst.id,\n      p_amount: amt,\n    });\n    setBusy(false);\n    if (error) {\n      toast.error(error.message.replace(/^.*?:\\s*/, \"\"));\n      return;\n    }\n    toast.success(`${money(amt)} KPC into ${inst.name}`);\n    setOpen(null);\n    setAmount(\"\");\n    load();\n  };\n\n  const sell = async (h: Holding) => {\n    const raw = window.prompt(\n      `How many units of ${h.name} to sell? You hold ${n(h.units).toFixed(4)}.`,\n      String(h.units),\n    );\n    if (!raw) return;\n    const units = Number(raw);\n    if (!Number.isFinite(units) || units <= 0) return;\n\n    setBusy(true);\n    const { error } = await supabase.rpc(\"redeem\", {\n      p_instrument: h.instrument_id,\n      p_units: units,\n    });\n    setBusy(false);\n    if (error) {\n      toast.error(error.message.replace(/^.*?:\\s*/, \"\"));\n      return;\n    }\n    toast.success(\"Redemption requested\");\n    load();\n  };\n\n  const totalValue = holdings.reduce((s, h) => s + n(h.value), 0);\n  const totalGain = holdings.reduce((s, h) => s + n(h.gain), 0);\n  const pending = redemptions.filter((r) => r.status === \"pending\");\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white font-sans p-5 selection:bg-[#AA771C]/30\">\n      <Toaster position=\"top-center\" />\n      <div className=\"max-w-xl mx-auto\">\n        <div className=\"flex items-center gap-3 mb-6\">\n          <Link\n            href=\"/wallet\"\n            className=\"text-[#94A3B8] hover:text-[#FDB813] p-2 bg-[#1F2937] rounded-lg border border-[#374151]\"\n          >\n            <ArrowLeft size={18} />\n          </Link>\n          <AppMenu />\n          <h1 className=\"text-lg font-black uppercase tracking-widest\">Invest</h1>\n        </div>\n\n        {checking ? (\n          <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-20 text-center\">\n            Loading...\n          </p>\n        ) : !userId ? (\n          <Panel>\n            <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-[0.15em] text-center leading-relaxed\">\n              Please{\" \"}\n              <Link href=\"/auth\" className=\"text-[#FDB813] underline\">\n                sign in\n              </Link>{\" \"}\n              to invest.\n            </p>\n          </Panel>\n        ) : (\n          <>\n            {/* Consumer copy, not internal reasoning. An earlier version of\n                this explained custody, unit pricing and what happens if\n                KobPay fails — all true, none of it what somebody opening an\n                app wants read at them. No bank puts its failure scenario on\n                the product page.\n                \n                What stays: one short risk line, because this is an\n                investment and that is not optional. What moved: the\n                mechanics, into \"How this works\" below, for the people who\n                want them. */}\n            {holdings.length === 0 && (\n              <div className=\"mb-5\">\n                <h2 className=\"text-xl font-black leading-tight mb-2\">\n                  Put your KPC to work\n                </h2>\n                <p className=\"text-[11px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] leading-relaxed\">\n                  Treasury bills and funds, in dollars, from small amounts.\n                </p>\n              </div>\n            )}\n\n            {holdings.length > 0 && (\n              <div className=\"mb-5 bg-[#111827] border border-[#1F2937] rounded-xl p-5\">\n                <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n                  What you hold\n                </p>\n                <div className=\"flex items-baseline gap-3\">\n                  <span className=\"text-3xl font-black text-[#FDB813]\">\n                    {money(totalValue)} <span className=\"text-sm text-white\">KPC</span>\n                  </span>\n                  <span\n                    className={`text-xs font-mono font-bold flex items-center gap-1 ${\n                      totalGain >= 0 ? \"text-[#10B981]\" : \"text-[#EF4444]\"\n                    }`}\n                  >\n                    {totalGain >= 0 ? <TrendingUp size={12} /> : <TrendingDown size={12} />}\n                    {totalGain >= 0 ? \"+\" : \"\"}\n                    {money(totalGain)}\n                  </span>\n                </div>\n                <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-widest mt-1\">\n                  {formatKpcAsUsd(totalValue)}\n                </p>\n              </div>\n            )}\n\n            {holdings.map((h) => (\n              <div\n                key={h.instrument_id}\n                className=\"mb-3 bg-[#111827] border border-[#1F2937] rounded-xl p-4\"\n              >\n                <div className=\"flex justify-between items-start mb-2\">\n                  <div>\n                    <p className=\"text-sm font-bold\">{h.name}</p>\n                    <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mt-0.5\">\n                      {n(h.units).toFixed(4)} units · {h.issuer}\n                    </p>\n                  </div>\n                  <div className=\"text-right\">\n                    <p className=\"text-sm font-black\">{money(h.value)} KPC</p>\n                    <p\n                      className={`text-[10px] font-mono font-bold ${\n                        n(h.gain) >= 0 ? \"text-[#10B981]\" : \"text-[#EF4444]\"\n                      }`}\n                    >\n                      {n(h.gain) >= 0 ? \"+\" : \"\"}\n                      {money(h.gain)} ({n(h.gain_percent).toFixed(2)}%)\n                    </p>\n                  </div>\n                </div>\n\n                {h.price_stale && (\n                  <p className=\"text-[9px] font-mono text-[#EF4444] uppercase tracking-[0.12em] flex items-center gap-1.5 mb-2\">\n                    <AlertTriangle size={11} /> Price out of date — selling is paused\n                  </p>\n                )}\n\n                <button\n                  disabled={busy || h.price_stale}\n                  onClick={() => sell(h)}\n                  className=\"w-full py-2.5 bg-[#1F2937] hover:bg-[#EF4444]/15 border border-[#374151] hover:border-[#EF4444]/50 text-[#94A3B8] hover:text-[#EF4444] rounded-lg text-[9px] font-mono uppercase tracking-[0.15em] transition-colors disabled:opacity-40\"\n                >\n                  Sell · pays out in {h.settles_in_days} days\n                  {h.exit_fee_bps > 0 && ` · ${(h.exit_fee_bps / 100).toFixed(2)}% exit fee`}\n                </button>\n              </div>\n            ))}\n\n            {pending.length > 0 && (\n              <Panel title=\"Money on the way\">\n                {pending.map((r) => (\n                  <div key={r.reference} className=\"flex justify-between items-baseline gap-3 py-1\">\n                    <span className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] flex items-center gap-1.5\">\n                      <Clock size={11} /> {r.name}\n                    </span>\n                    <span className=\"text-xs font-mono font-bold\">\n                      {money(r.net)} KPC ·{\" \"}\n                      {new Date(r.settles_on).toLocaleDateString(undefined, {\n                        day: \"numeric\",\n                        month: \"short\",\n                      })}\n                    </span>\n                  </div>\n                ))}\n              </Panel>\n            )}\n\n            <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mt-6 mb-3\">\n              Open to invest in\n            </p>\n\n            {instruments.length === 0 ? (\n              <Panel>\n                {/* \"Nothing is open right now\" full stop reads like an abandoned\n                    product. Saying WHY nothing is listed is the honest version\n                    and the reassuring one at the same time: we do not list\n                    something until there is a real issuer behind it. */}\n                <p className=\"text-[11px] font-bold text-center mb-2\">\n                  New products coming soon\n                </p>\n                <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.15em] text-center leading-relaxed\">\n                  Meanwhile your KPC can earn in{\" \"}\n                  <Link href=\"/savings\" className=\"text-[#10B981] underline\">\n                    savings\n                  </Link>\n                </p>\n              </Panel>\n            ) : (\n              instruments.map((inst) => {\n                const stale =\n                  Date.now() - new Date(inst.price_at).getTime() > 48 * 3600 * 1000;\n                return (\n                  <div\n                    key={inst.id}\n                    className=\"mb-3 bg-[#111827] border border-[#1F2937] rounded-xl p-4\"\n                  >\n                    <div className=\"flex justify-between items-start\">\n                      <div>\n                        <p className=\"text-sm font-bold\">{inst.name}</p>\n                        <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mt-0.5\">\n                          {KIND[inst.kind] ?? inst.kind} · {inst.issuer}\n                        </p>\n                      </div>\n                      {inst.expected_yield_bps != null && (\n                        <span className=\"text-sm font-black text-[#10B981]\">\n                          {(inst.expected_yield_bps / 100).toFixed(1)}%\n                          <span className=\"text-[8px] font-mono text-[#4B5563] block text-right tracking-widest\">\n                            EXPECTED\n                          </span>\n                        </span>\n                      )}\n                    </div>\n\n                    {inst.blurb && (\n                      <p className=\"text-[10px] font-mono text-[#94A3B8] mt-2 leading-relaxed\">\n                        {inst.blurb}\n                      </p>\n                    )}\n\n                    <p className=\"text-[9px] font-mono text-[#FDB813]/80 uppercase tracking-[0.12em] mt-2 leading-relaxed\">\n                      {inst.risk_note}\n                    </p>\n\n                    {open === inst.id ? (\n                      <div className=\"mt-3\">\n                        <input\n                          value={amount}\n                          onChange={(e) => setAmount(e.target.value)}\n                          inputMode=\"decimal\"\n                          autoFocus\n                          placeholder={`Minimum ${money(inst.min_investment)} KPC`}\n                          className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-3 text-lg font-black text-white placeholder-[#4B5563] focus:border-[#FDB813] outline-none text-center\"\n                        />\n                        <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] text-center mt-2\">\n                          You have {money(balance ?? 0)} KPC ·{\" \"}\n                          {Number(amount) > 0\n                            ? `${(Number(amount) / n(inst.unit_price)).toFixed(4)} units`\n                            : `1 unit = ${money(inst.unit_price)} KPC`}\n                        </p>\n                        <div className=\"grid grid-cols-2 gap-2 mt-3\">\n                          <button\n                            onClick={() => {\n                              setOpen(null);\n                              setAmount(\"\");\n                            }}\n                            className=\"py-3 bg-[#1F2937] border border-[#374151] text-[#94A3B8] rounded-lg text-[9px] font-mono uppercase tracking-[0.15em]\"\n                          >\n                            Cancel\n                          </button>\n                          <button\n                            disabled={busy || Number(amount) <= 0}\n                            onClick={() => buy(inst)}\n                            className=\"py-3 bg-[#FDB813] hover:bg-[#E0A411] disabled:opacity-40 text-[#0A0E14] rounded-lg text-[9px] font-mono font-black uppercase tracking-[0.15em] flex items-center justify-center gap-1.5\"\n                          >\n                            {busy && <Loader2 size={11} className=\"animate-spin\" />}\n                            Confirm\n                          </button>\n                        </div>\n                      </div>\n                    ) : (\n                      <button\n                        disabled={stale}\n                        onClick={() => setOpen(inst.id)}\n                        className=\"w-full mt-3 py-2.5 bg-[#1F2937] hover:bg-[#FDB813]/10 border border-[#374151] hover:border-[#FDB813]/50 text-[#94A3B8] hover:text-[#FDB813] rounded-lg text-[9px] font-mono uppercase tracking-[0.15em] transition-colors disabled:opacity-40\"\n                      >\n                        {stale\n                          ? \"Price out of date — closed\"\n                          : `Invest · from ${money(inst.min_investment)} KPC`}\n                      </button>\n                    )}\n                  </div>\n                );\n              })\n            )}\n            {/* Where the detail belongs: available, not shouted. Anyone who\n                wants to know how it works can open it; nobody is made to read\n                it before they can see a product. */}\n            <details className=\"mt-6 group\">\n              <summary className=\"cursor-pointer list-none flex items-center justify-between py-3 px-4 bg-[#111827] border border-[#1F2937] rounded-xl text-[10px] font-mono uppercase tracking-[0.15em] text-[#94A3B8]\">\n                How this works\n                <ChevronDown\n                  size={14}\n                  className=\"transition-transform group-open:rotate-180\"\n                />\n              </summary>\n              <div className=\"px-4 pt-4 pb-1 space-y-3\">\n                <Point t=\"Held by the issuer\">\n                  Your investment sits with the institution that issued it, in your\n                  name. KobPay records it and gives you a way in and out.\n                </Point>\n                <Point t=\"Priced daily\">\n                  You hold units. Their price is updated each business day, and every\n                  price is kept on record.\n                </Point>\n                <Point t=\"Selling takes a few days\">\n                  When you sell, the price is set that day and the money reaches your\n                  wallet after the settlement period shown on the product.\n                </Point>\n              </div>\n            </details>\n\n            <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] leading-relaxed text-center mt-6 mb-2\">\n              Investments can fall as well as rise. Capital is at risk.\n            </p>\n          </>\n        )}\n      </div>\n    </div>\n  );\n}\n\nfunction Point({ t, children }: { t: string; children: React.ReactNode }) {\n  return (\n    <div>\n      <p className=\"text-[10px] font-bold mb-0.5\">{t}</p>\n      <p className=\"text-[10px] font-mono text-[#94A3B8] leading-relaxed\">{children}</p>\n    </div>\n  );\n}\n\nfunction Panel({ title, children }: { title?: string; children: React.ReactNode }) {\n  return (\n    <div className=\"bg-[#111827] border border-[#1F2937] rounded-xl p-4\">\n      {title && (\n        <p className=\"text-[9px] font-mono text-[#FDB813] uppercase tracking-[0.2em] mb-3\">\n          {title}\n        </p>\n      )}\n      {children}\n    </div>\n  );\n}\n");

write("app/limits/page.tsx", "\"use client\";\n\nimport React, { useCallback, useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport { ArrowLeft, ShieldCheck, Clock, Loader2, Check } from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\nimport AppMenu from \"../components/AppMenu\";\nimport toast, { Toaster } from \"react-hot-toast\";\n\ntype NextTier = {\n  id: string;\n  name: string;\n  requirements: string;\n  needs_id: boolean;\n  needs_address: boolean;\n  needs_business: boolean;\n  daily: number;\n  max_balance: number;\n};\n\ntype Limits = {\n  tier: string;\n  tier_name: string;\n  rank: number;\n  jurisdiction: string;\n  requirements: string;\n  single_txn: number;\n  daily: number;\n  monthly: number;\n  max_balance: number;\n  spent_today: number;\n  spent_month: number;\n  balance: number;\n  daily_left: number;\n  monthly_left: number;\n  balance_room: number;\n  next_tier: NextTier | null;\n  pending_review: boolean;\n};\n\nconst n = (v: unknown) => (typeof v === \"number\" ? v : Number(v ?? 0));\nconst kpc = (v: unknown) =>\n  `${n(v).toLocaleString(undefined, { maximumFractionDigits: 2 })} KPC`;\n\nconst ID_TYPES = [\n  [\"ghana_card\", \"Ghana Card\"],\n  [\"passport\", \"Passport\"],\n  [\"drivers_licence\", \"Driver's licence\"],\n  [\"voter_id\", \"Voter ID\"],\n  [\"other\", \"Something else\"],\n] as const;\n\nexport default function LimitsPage() {\n  const [limits, setLimits] = useState<Limits | null>(null);\n  const [checking, setChecking] = useState(true);\n  const [signedIn, setSignedIn] = useState(false);\n  const [form, setForm] = useState(false);\n  const [busy, setBusy] = useState(false);\n\n  const [fullName, setFullName] = useState(\"\");\n  const [idType, setIdType] = useState<string>(\"ghana_card\");\n  const [idRef, setIdRef] = useState(\"\");\n  const [address, setAddress] = useState(\"\");\n  const [source, setSource] = useState(\"\");\n\n  const load = useCallback(async () => {\n    const { data } = await supabase.rpc(\"my_limits\");\n    setLimits((data as Limits) ?? null);\n  }, []);\n\n  useEffect(() => {\n    supabase.auth.getSession().then(({ data }) => {\n      setSignedIn(Boolean(data.session));\n      setChecking(false);\n      if (data.session) load();\n    });\n  }, [load]);\n\n  const submit = async () => {\n    if (!limits?.next_tier) return;\n    setBusy(true);\n    const { error } = await supabase.rpc(\"submit_kyc\", {\n      p_tier: limits.next_tier.id,\n      p_full_name: fullName,\n      p_id_type: idType,\n      p_id_reference: idRef,\n      p_id_expires: null,\n      p_address: address.trim() || null,\n      p_source: source.trim() || null,\n    });\n    setBusy(false);\n    if (error) {\n      toast.error(error.message.replace(/^.*?:\\s*/, \"\"));\n      return;\n    }\n    toast.success(\"Sent for review\");\n    setForm(false);\n    load();\n  };\n\n  const next = limits?.next_tier ?? null;\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white font-sans p-5 selection:bg-[#AA771C]/30\">\n      <Toaster position=\"top-center\" />\n      <div className=\"max-w-xl mx-auto\">\n        <div className=\"flex items-center gap-3 mb-6\">\n          <Link\n            href=\"/wallet\"\n            className=\"text-[#94A3B8] hover:text-[#FDB813] p-2 bg-[#1F2937] rounded-lg border border-[#374151]\"\n          >\n            <ArrowLeft size={18} />\n          </Link>\n          <AppMenu />\n          <h1 className=\"text-lg font-black uppercase tracking-widest\">Your limits</h1>\n        </div>\n\n        {checking ? (\n          <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-20 text-center\">\n            Loading...\n          </p>\n        ) : !signedIn ? (\n          <Panel>\n            <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] text-center\">\n              Please{\" \"}\n              <Link href=\"/auth\" className=\"text-[#FDB813] underline\">\n                sign in\n              </Link>\n              .\n            </p>\n          </Panel>\n        ) : !limits ? (\n          <Panel>\n            <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] text-center\">\n              Could not load your limits.\n            </p>\n          </Panel>\n        ) : (\n          <>\n            <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-5 mb-5\">\n              <div className=\"flex items-center justify-between mb-1\">\n                <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em]\">\n                  Your account\n                </p>\n                <span className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.15em]\">\n                  {limits.jurisdiction === \"GH\" ? \"Ghana\" : \"International\"}\n                </span>\n              </div>\n              <p className=\"text-2xl font-black text-[#FDB813]\">{limits.tier_name}</p>\n              <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] mt-1 leading-relaxed\">\n                {limits.requirements}\n              </p>\n            </div>\n\n            {/* Usage first. Somebody opening this page is usually here because\n                something was refused, and the answer is in these three bars. */}\n            <Panel title=\"Right now\">\n              <Bar\n                label=\"Today\"\n                used={n(limits.spent_today)}\n                total={n(limits.daily)}\n                left={n(limits.daily_left)}\n              />\n              <Bar\n                label=\"This month\"\n                used={n(limits.spent_month)}\n                total={n(limits.monthly)}\n                left={n(limits.monthly_left)}\n              />\n              <Bar\n                label=\"Wallet\"\n                used={n(limits.balance)}\n                total={n(limits.max_balance)}\n                left={n(limits.balance_room)}\n              />\n              <div className=\"pt-2 mt-1 border-t border-[#1F2937]\">\n                <KV k=\"Most in one payment\" v={kpc(limits.single_txn)} />\n              </div>\n            </Panel>\n\n            {limits.pending_review ? (\n              <div className=\"mt-5 bg-[#FDB813]/5 border border-[#FDB813]/30 rounded-2xl p-5 flex gap-3\">\n                <Clock size={16} className=\"text-[#FDB813] shrink-0 mt-0.5\" />\n                <div>\n                  <p className=\"text-[11px] font-bold mb-1\">We are checking your details</p>\n                  <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] leading-relaxed\">\n                    You will get a message when it is done. Your current limits still apply\n                    until then.\n                  </p>\n                </div>\n              </div>\n            ) : next ? (\n              <div className=\"mt-5 bg-[#111827] border border-[#1F2937] rounded-2xl p-5\">\n                <div className=\"flex items-center gap-2 mb-2\">\n                  <ShieldCheck size={15} className=\"text-[#10B981]\" />\n                  <p className=\"text-[11px] font-bold\">Move up to {next.name}</p>\n                </div>\n                <div className=\"grid grid-cols-2 gap-3 my-4\">\n                  <Step from={kpc(limits.daily)} to={kpc(next.daily)} label=\"a day\" />\n                  <Step\n                    from={kpc(limits.max_balance)}\n                    to={kpc(next.max_balance)}\n                    label=\"in your wallet\"\n                  />\n                </div>\n                <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] leading-relaxed\">\n                  {next.requirements}\n                </p>\n\n                {!form ? (\n                  <button\n                    onClick={() => setForm(true)}\n                    className=\"w-full mt-4 py-3.5 bg-[#FDB813] hover:bg-[#E0A411] text-[#0A0E14] font-black font-mono text-[10px] uppercase tracking-[0.2em] rounded-xl\"\n                  >\n                    {next.needs_business ? \"Apply as a business\" : \"Verify my account\"}\n                  </button>\n                ) : (\n                  <div className=\"mt-4 space-y-3\">\n                    <Field\n                      label=\"Full name, exactly as on your ID\"\n                      value={fullName}\n                      onChange={setFullName}\n                      autoFocus\n                    />\n\n                    {next.needs_id && (\n                      <>\n                        <div>\n                          <label className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-2\">\n                            Type of ID\n                          </label>\n                          <select\n                            value={idType}\n                            onChange={(e) => setIdType(e.target.value)}\n                            className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-3 text-sm font-mono text-white focus:border-[#FDB813] outline-none appearance-none\"\n                          >\n                            {ID_TYPES.map(([v, l]) => (\n                              <option key={v} value={v}>\n                                {l}\n                              </option>\n                            ))}\n                          </select>\n                        </div>\n                        <Field label=\"ID number\" value={idRef} onChange={setIdRef} />\n                      </>\n                    )}\n\n                    {next.needs_address && (\n                      <Field label=\"Your address\" value={address} onChange={setAddress} />\n                    )}\n\n                    {/* Optional on purpose. Asked properly by a reviewer when\n                        the amounts warrant it, rather than as a wall here. */}\n                    <Field\n                      label=\"Where your money comes from (optional)\"\n                      value={source}\n                      onChange={setSource}\n                      placeholder=\"Salary, business, savings…\"\n                    />\n\n                    <div className=\"grid grid-cols-2 gap-2 pt-1\">\n                      <button\n                        onClick={() => setForm(false)}\n                        className=\"py-3 bg-[#1F2937] border border-[#374151] text-[#94A3B8] rounded-lg text-[9px] font-mono uppercase tracking-[0.15em]\"\n                      >\n                        Cancel\n                      </button>\n                      <button\n                        disabled={busy || !fullName.trim()}\n                        onClick={submit}\n                        className=\"py-3 bg-[#FDB813] hover:bg-[#E0A411] disabled:opacity-40 text-[#0A0E14] rounded-lg text-[9px] font-mono font-black uppercase tracking-[0.15em] flex items-center justify-center gap-1.5\"\n                      >\n                        {busy && <Loader2 size={11} className=\"animate-spin\" />}\n                        Send\n                      </button>\n                    </div>\n\n                    <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] leading-relaxed pt-1\">\n                      We record your ID number, not a copy of the document.\n                    </p>\n                  </div>\n                )}\n              </div>\n            ) : (\n              <div className=\"mt-5 flex items-center justify-center gap-2 py-6 text-[10px] font-mono uppercase tracking-[0.15em] text-[#10B981]\">\n                <Check size={14} /> You are on the highest tier\n              </div>\n            )}\n          </>\n        )}\n      </div>\n    </div>\n  );\n}\n\nfunction Bar({\n  label,\n  used,\n  total,\n  left,\n}: {\n  label: string;\n  used: number;\n  total: number;\n  left: number;\n}) {\n  const pct = total > 0 ? Math.min((used / total) * 100, 100) : 0;\n  const tight = pct >= 85;\n  return (\n    <div className=\"mb-3 last:mb-1\">\n      <div className=\"flex justify-between items-baseline mb-1.5\">\n        <span className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em]\">\n          {label}\n        </span>\n        <span\n          className={`text-[10px] font-mono font-bold ${tight ? \"text-[#EF4444]\" : \"text-white\"}`}\n        >\n          {kpc(left)} left\n        </span>\n      </div>\n      <div className=\"h-1.5 bg-[#0A0E14] rounded-full overflow-hidden\">\n        <div\n          className={`h-full rounded-full transition-all ${tight ? \"bg-[#EF4444]\" : \"bg-[#FDB813]\"}`}\n          style={{ width: `${pct}%` }}\n        />\n      </div>\n      <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.1em] mt-1\">\n        {kpc(used)} of {kpc(total)}\n      </p>\n    </div>\n  );\n}\n\nfunction Step({ from, to, label }: { from: string; to: string; label: string }) {\n  return (\n    <div className=\"bg-[#0A0E14] border border-[#1F2937] rounded-xl p-3\">\n      <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.15em] line-through\">\n        {from}\n      </p>\n      <p className=\"text-sm font-black text-[#10B981]\">{to}</p>\n      <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.12em]\">{label}</p>\n    </div>\n  );\n}\n\nfunction Field({\n  label,\n  value,\n  onChange,\n  placeholder,\n  autoFocus,\n}: {\n  label: string;\n  value: string;\n  onChange: (v: string) => void;\n  placeholder?: string;\n  autoFocus?: boolean;\n}) {\n  return (\n    <div>\n      <label className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-2\">\n        {label}\n      </label>\n      <input\n        value={value}\n        onChange={(e) => onChange(e.target.value)}\n        placeholder={placeholder}\n        autoFocus={autoFocus}\n        className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-3 text-sm text-white placeholder-[#4B5563] focus:border-[#FDB813] outline-none\"\n      />\n    </div>\n  );\n}\n\nfunction KV({ k, v }: { k: string; v: string }) {\n  return (\n    <div className=\"flex justify-between items-baseline\">\n      <span className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em]\">{k}</span>\n      <span className=\"text-xs font-mono font-bold text-white\">{v}</span>\n    </div>\n  );\n}\n\nfunction Panel({ title, children }: { title?: string; children: React.ReactNode }) {\n  return (\n    <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-5\">\n      {title && (\n        <p className=\"text-[9px] font-mono text-[#FDB813] uppercase tracking-[0.2em] mb-4\">\n          {title}\n        </p>\n      )}\n      {children}\n    </div>\n  );\n}\n");

write("app/markets/page.tsx", "\"use client\";\n\nimport React, { useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport { ArrowLeft, TrendingUp, AlertTriangle, Check } from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\nimport AppMenu from \"../components/AppMenu\";\nimport { Toaster } from \"react-hot-toast\";\n\n// This page used to be four hardcoded rows: KPC/GHS at 13.50, KPC/NGN at\n// 1,650, KPC/ETH at 0.00031, each with an invented 24h change and volume.\n//\n// The GHS one was the problem. fx_rates holds 12.40, and that is what\n// payment_quote_for_user charges against — so a customer could read 13.50\n// here and be charged at 12.40 one tap later.\n//\n// NGN and ETH are gone rather than corrected. NGN has no rate in fx_rates,\n// and nothing quotes KPC against ether. A pair with no market behind it is a\n// made-up price however convincing the row looks.\n//\n// There is also no 24h change column any more, because KPC does not move\n// against the dollar — that is the entire design — and the rates that do move\n// are the fiat ones, which are an input to pricing rather than a market.\n\ntype Rate = {\n  code: string;\n  name: string;\n  symbol: string;\n  kpc_price: number;\n  source: string;\n  pegged: boolean;\n  hours_old: number;\n  stale: boolean;\n  chargeable: boolean;\n};\n\nconst n = (v: unknown) => (typeof v === \"number\" ? v : Number(v ?? 0));\n\nexport default function MarketsPage() {\n  const [rates, setRates] = useState<Rate[] | null>(null);\n\n  useEffect(() => {\n    supabase.rpc(\"public_rates\").then(({ data }) => {\n      setRates(Array.isArray(data) ? (data as Rate[]) : []);\n    });\n  }, []);\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white p-5 lg:p-10 font-sans\">\n      <Toaster position=\"top-center\" />\n      <div className=\"max-w-[1000px] mx-auto\">\n        <div className=\"flex items-center gap-3 lg:gap-4 mb-6 lg:mb-10\">\n          <Link\n            href=\"/\"\n            className=\"text-[#94A3B8] hover:text-[#10B981] p-2.5 lg:p-3 bg-[#111827] rounded-xl border border-[#1F2937]\"\n          >\n            <ArrowLeft size={18} />\n          </Link>\n          <AppMenu />\n          <h1 className=\"text-xl lg:text-3xl font-black uppercase tracking-widest flex items-center gap-3\">\n            <TrendingUp className=\"text-[#10B981]\" /> Rates\n          </h1>\n        </div>\n\n        <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] mb-5 leading-relaxed\">\n          What one KPC costs in each currency. These are the live rates the app\n          charges against — not a market quote.\n        </p>\n\n        <div className=\"bg-[#111827]/80 border border-[#1F2937] rounded-2xl lg:rounded-3xl p-4 lg:p-8\">\n          <div className=\"hidden sm:grid grid-cols-4 gap-4 px-4 pb-3 text-[9px] text-[#94A3B8] uppercase tracking-[0.2em] border-b border-[#1F2937] mb-2\">\n            <div>Currency</div>\n            <div>1 KPC costs</div>\n            <div>Updated</div>\n            <div className=\"text-right\">Can top up</div>\n          </div>\n\n          {rates === null ? (\n            <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-10 text-center\">\n              Loading...\n            </p>\n          ) : rates.length === 0 ? (\n            <p className=\"text-[10px] font-mono text-[#4B5563] uppercase tracking-[0.15em] py-10 text-center\">\n              No rates published yet\n            </p>\n          ) : (\n            rates.map((r) => (\n              <div\n                key={r.code}\n                className=\"grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-4 items-center px-2 sm:px-4 py-4 border-b border-[#1F2937] last:border-0\"\n              >\n                <div>\n                  <p className=\"font-black text-sm\">{r.code}</p>\n                  <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em]\">\n                    {r.name}\n                  </p>\n                </div>\n\n                <div className=\"text-right sm:text-left\">\n                  <p className=\"font-mono font-bold text-sm\">\n                    {r.symbol}\n                    {n(r.kpc_price).toLocaleString(undefined, {\n                      minimumFractionDigits: 2,\n                      maximumFractionDigits: 4,\n                    })}\n                  </p>\n                </div>\n\n                <div className=\"text-[10px] font-mono uppercase tracking-[0.12em]\">\n                  {r.pegged ? (\n                    <span className=\"text-[#10B981]\">Pegged · never moves</span>\n                  ) : r.stale ? (\n                    <span className=\"text-[#EF4444] flex items-center gap-1.5\">\n                      <AlertTriangle size={11} /> Out of date\n                    </span>\n                  ) : (\n                    <span className=\"text-[#94A3B8]\">\n                      {n(r.hours_old) < 1\n                        ? \"just now\"\n                        : `${Math.round(n(r.hours_old))}h ago`}\n                    </span>\n                  )}\n                </div>\n\n                <div className=\"text-right text-[10px] font-mono uppercase tracking-[0.12em]\">\n                  {r.chargeable && !r.stale ? (\n                    <span className=\"text-[#10B981] inline-flex items-center gap-1.5\">\n                      <Check size={11} /> Yes\n                    </span>\n                  ) : (\n                    <span className=\"text-[#4B5563]\">Not yet</span>\n                  )}\n                </div>\n              </div>\n            ))\n          )}\n        </div>\n\n        <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] mt-5 leading-relaxed\">\n          1 KPC = $1.00 by design. Rates against other currencies move with the\n          market and are refreshed daily.\n        </p>\n      </div>\n    </div>\n  );\n}\n");

write("app/merchant/page.tsx", "\"use client\";\n\nimport React, { useCallback, useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport {\n  ArrowLeft, Store, Plus, Copy, Check, Power, Link2,\n  TrendingUp, RotateCcw, X,\n} from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\nimport AppMenu from \"../components/AppMenu\";\nimport { formatKpcAsUsd } from \"../lib/kpcPeg\";\nimport toast, { Toaster } from \"react-hot-toast\";\n\ntype Merchant = { user_id: string; business_name: string; slug: string; active: boolean };\n\ntype PayLink = {\n  id: string;\n  reference: string;\n  title: string;\n  description: string | null;\n  amount: number | null;\n  currency: string;\n  active: boolean;\n  max_uses: number | null;\n  uses: number;\n  expires_at: string | null;\n  open_amount: boolean;\n  taken: number;\n  payments: number;\n  expired: boolean;\n  used_up: boolean;\n};\n\ntype Sale = {\n  id: string;\n  reference: string;\n  amount: number;\n  fee: number;\n  net: number;\n  note: string | null;\n  refunded_amount: number;\n  created_at: string;\n  i_sold_it: boolean;\n  title: string | null;\n  other_party: string | null;\n};\n\nconst num = (v: unknown) => (typeof v === \"number\" ? v : Number(v ?? 0));\n\nexport default function MerchantPage() {\n  const [userId, setUserId] = useState<string | null>(null);\n  const [checking, setChecking] = useState(true);\n  const [merchant, setMerchant] = useState<Merchant | null>(null);\n  const [links, setLinks] = useState<PayLink[]>([]);\n  const [sales, setSales] = useState<Sale[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [showNew, setShowNew] = useState(false);\n  const [busy, setBusy] = useState<string | null>(null);\n  const [refunding, setRefunding] = useState<Sale | null>(null);\n\n  const load = useCallback(async (uid: string) => {\n    const [m, l, s] = await Promise.all([\n      supabase.from(\"merchants\").select(\"*\").eq(\"user_id\", uid).maybeSingle(),\n      supabase.from(\"my_payment_links\").select(\"*\").order(\"created_at\", { ascending: false }),\n      supabase.from(\"my_merchant_sales\").select(\"*\").order(\"created_at\", { ascending: false }).limit(50),\n    ]);\n    setMerchant((m.data as Merchant) ?? null);\n    setLinks((l.data as PayLink[]) ?? []);\n    setSales(((s.data as Sale[]) ?? []).filter((x) => x.i_sold_it));\n    setLoading(false);\n  }, []);\n\n  useEffect(() => {\n    supabase.auth.getSession().then(({ data }) => {\n      const uid = data.session?.user.id ?? null;\n      setUserId(uid);\n      setChecking(false);\n      if (uid) load(uid);\n      else setLoading(false);\n    });\n  }, [load]);\n\n  const call = async (fn: string, args: Record<string, unknown>, ok: string, key: string) => {\n    setBusy(key);\n    const { error } = await supabase.rpc(fn, args);\n    setBusy(null);\n    if (error) {\n      toast.error(error.message.replace(/^.*?:\\s*/, \"\"));\n      return false;\n    }\n    toast.success(ok);\n    if (userId) await load(userId);\n    return true;\n  };\n\n  const takenTotal = sales.reduce((s, x) => s + num(x.net) - num(x.refunded_amount), 0);\n  const feesPaid = sales.reduce((s, x) => s + num(x.fee), 0);\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white font-sans selection:bg-[#AA771C]/30 relative overflow-hidden\">\n      <Toaster position=\"top-center\" reverseOrder={false} />\n      <div className=\"absolute top-0 left-1/2 -translate-x-1/2 w-[900px] h-[900px] bg-gradient-to-br from-[#FDB813]/5 to-transparent rounded-full blur-[120px] pointer-events-none\" />\n\n      <div className=\"relative z-10 max-w-3xl mx-auto px-5 py-8 sm:px-8\">\n        <div className=\"flex justify-between items-start mb-8\">\n          <Link\n            href=\"/wallet\"\n            className=\"text-[#94A3B8] hover:text-[#FDB813] transition-colors p-2 bg-[#1F2937] rounded-lg border border-[#374151]\"\n          >\n            <ArrowLeft size={20} />\n          </Link>\n          <AppMenu />\n          <div className=\"flex items-center gap-2 text-[10px] font-mono tracking-widest uppercase bg-[#0A0E14] px-3 py-1.5 rounded-full border border-[#1F2937]\">\n            <Store size={12} className=\"text-[#FDB813]\" />\n            <span className=\"text-[#FDB813]\">Business</span>\n          </div>\n        </div>\n\n        <h1 className=\"text-3xl font-black uppercase tracking-widest mb-1\">\n          {merchant?.business_name ?? \"Take payments\"}\n        </h1>\n        <p className=\"text-[10px] font-mono text-[#94A3B8] tracking-widest uppercase mb-8\">\n          {merchant ? `kobpay.app/m/${merchant.slug}` : \"A link is all you need — no terminal, no contract\"}\n        </p>\n\n        {checking ? (\n          <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-10 text-center\">\n            Loading...\n          </p>\n        ) : !userId ? (\n          <div className=\"bg-[#EF4444]/10 border border-[#EF4444]/30 p-6 rounded-xl\">\n            <p className=\"text-xs font-mono text-[#EF4444] leading-relaxed uppercase\">\n              Please{\" \"}\n              <Link href=\"/auth\" className=\"underline\">\n                sign in\n              </Link>{\" \"}\n              to take payments.\n            </p>\n          </div>\n        ) : loading ? (\n          <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-10 text-center\">\n            Loading...\n          </p>\n        ) : !merchant ? (\n          <SetUp\n            busy={busy === \"setup\"}\n            onDone={(name, slug) =>\n              call(\"become_merchant\", { p_business_name: name, p_slug: slug }, \"You're open\", \"setup\")\n            }\n          />\n        ) : (\n          <>\n            <div className=\"grid grid-cols-3 gap-3 mb-6\">\n              <Stat label=\"Taken\" value={takenTotal} />\n              <Stat label=\"Sales\" value={sales.length} plain />\n              <Stat label=\"Fees paid\" value={feesPaid} muted />\n            </div>\n\n            <button\n              onClick={() => setShowNew((v) => !v)}\n              className=\"w-full mb-6 flex items-center justify-center gap-2 bg-[#FDB813] hover:bg-[#E0A411] text-[#0A0E14] font-black uppercase tracking-widest text-xs py-4 rounded-xl transition-colors\"\n            >\n              <Plus size={14} /> New payment link\n            </button>\n\n            {showNew && (\n              <NewLink\n                busy={busy === \"link\"}\n                onCancel={() => setShowNew(false)}\n                onCreate={async (title, amount, desc, maxUses, days) => {\n                  const okay = await call(\n                    \"create_payment_link\",\n                    {\n                      p_title: title,\n                      p_amount: amount,\n                      p_description: desc,\n                      p_max_uses: maxUses,\n                      p_expires_days: days,\n                    },\n                    \"Link ready — share it\",\n                    \"link\",\n                  );\n                  if (okay) setShowNew(false);\n                }}\n              />\n            )}\n\n            {links.length === 0 ? (\n              <div className=\"bg-[#111827]/80 border border-[#1F2937] rounded-2xl p-8 text-center mb-6\">\n                <Link2 size={28} className=\"text-[#374151] mx-auto mb-3\" />\n                <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest mb-2\">\n                  No links yet\n                </p>\n                <p className=\"text-[10px] font-mono text-[#4B5563] leading-relaxed\">\n                  Make one, paste it wherever you sell. Anyone who opens it can\n                  pay you.\n                </p>\n              </div>\n            ) : (\n              <div className=\"space-y-3 mb-8\">\n                {links.map((l) => (\n                  <LinkCard\n                    key={l.id}\n                    l={l}\n                    busy={busy}\n                    onToggle={() =>\n                      call(\n                        \"set_payment_link_active\",\n                        { p_link: l.id, p_active: !l.active },\n                        l.active ? \"Closed\" : \"Open again\",\n                        l.id + \":t\",\n                      )\n                    }\n                  />\n                ))}\n              </div>\n            )}\n\n            {sales.length > 0 && (\n              <>\n                <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.2em] mb-2 px-1\">\n                  Recent sales\n                </p>\n                <div className=\"bg-[#111827]/80 backdrop-blur-xl border border-[#1F2937] rounded-2xl overflow-hidden\">\n                  {sales.map((s, i) => (\n                    <SaleRow\n                      key={s.id}\n                      s={s}\n                      first={i === 0}\n                      onRefund={() => setRefunding(s)}\n                    />\n                  ))}\n                </div>\n              </>\n            )}\n\n            <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.2em] text-center mt-10 leading-relaxed\">\n              1 KPC = $1.00 · paid straight to your wallet, no settlement wait\n              <br />\n              {formatKpcAsUsd(takenTotal)} taken\n            </p>\n          </>\n        )}\n      </div>\n\n      {refunding && (\n        <RefundSheet\n          s={refunding}\n          onClose={() => setRefunding(null)}\n          onDone={async () => {\n            setRefunding(null);\n            if (userId) await load(userId);\n          }}\n        />\n      )}\n    </div>\n  );\n}\n\nfunction Stat({\n  label,\n  value,\n  plain,\n  muted,\n}: {\n  label: string;\n  value: number;\n  plain?: boolean;\n  muted?: boolean;\n}) {\n  return (\n    <div className=\"bg-[#0A0E14] border border-[#1F2937] p-4 rounded-xl\">\n      <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n        {label}\n      </span>\n      <span className={`text-lg font-black ${muted ? \"text-[#94A3B8]\" : \"text-[#FDB813]\"}`}>\n        {value.toLocaleString(undefined, { maximumFractionDigits: 2 })}\n        {!plain && <span className=\"text-[9px] text-[#94A3B8] ml-1\">KPC</span>}\n      </span>\n    </div>\n  );\n}\n\nfunction SetUp({\n  busy,\n  onDone,\n}: {\n  busy: boolean;\n  onDone: (name: string, slug: string) => void;\n}) {\n  const [name, setName] = useState(\"\");\n  const slug = name\n    .toLowerCase()\n    .replace(/[^a-z0-9]+/g, \"-\")\n    .replace(/^-+|-+$/g, \"\");\n\n  return (\n    <div className=\"bg-[#111827]/80 backdrop-blur-xl border border-[#1F2937] rounded-2xl p-5 space-y-4\">\n      <div>\n        <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1.5\">\n          What is the business called?\n        </span>\n        <input\n          value={name}\n          onChange={(e) => setName(e.target.value)}\n          placeholder=\"Ama Fabrics\"\n          className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#FDB813] outline-none\"\n        />\n      </div>\n\n      {slug.length >= 3 && (\n        <div className=\"bg-[#FDB813]/10 border border-[#FDB813]/30 rounded-lg p-3\">\n          <p className=\"text-[10px] font-mono text-[#FDB813] uppercase tracking-[0.1em]\">\n            kobpay.app/m/{slug}\n          </p>\n        </div>\n      )}\n\n      <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.15em] leading-relaxed\">\n        No contract, no terminal, no waiting for a settlement run. Money from a\n        link lands in your wallet immediately.\n      </p>\n\n      <button\n        disabled={busy || slug.length < 3}\n        onClick={() => onDone(name.trim(), slug)}\n        className=\"w-full bg-[#FDB813] hover:bg-[#E0A411] disabled:opacity-40 text-[#0A0E14] font-black uppercase tracking-widest text-xs py-3.5 rounded-xl transition-colors\"\n      >\n        {busy ? \"Opening...\" : \"Open for business\"}\n      </button>\n    </div>\n  );\n}\n\nfunction NewLink({\n  busy,\n  onCreate,\n  onCancel,\n}: {\n  busy: boolean;\n  onCreate: (\n    title: string,\n    amount: number | null,\n    desc: string | null,\n    maxUses: number | null,\n    days: number | null,\n  ) => void;\n  onCancel: () => void;\n}) {\n  const [title, setTitle] = useState(\"\");\n  const [amount, setAmount] = useState(\"\");\n  const [open, setOpen] = useState(false);\n  const [once, setOnce] = useState(false);\n\n  const n = Number(amount) || 0;\n\n  return (\n    <div className=\"bg-[#111827]/80 backdrop-blur-xl border border-[#1F2937] rounded-2xl p-5 mb-6 space-y-4\">\n      <div>\n        <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1.5\">\n          What are they paying for\n        </span>\n        <input\n          value={title}\n          onChange={(e) => setTitle(e.target.value)}\n          placeholder=\"2 yards wax print\"\n          className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#FDB813] outline-none\"\n        />\n      </div>\n\n      <label className=\"flex items-center gap-2.5 cursor-pointer\">\n        <input\n          type=\"checkbox\"\n          checked={open}\n          onChange={(e) => setOpen(e.target.checked)}\n          className=\"w-4 h-4 accent-[#FDB813]\"\n        />\n        <span className=\"text-[10px] font-mono uppercase tracking-[0.15em] text-[#94A3B8]\">\n          Let them choose the amount\n        </span>\n      </label>\n\n      {!open && (\n        <div>\n          <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1.5\">\n            Price\n          </span>\n          <input\n            value={amount}\n            onChange={(e) => setAmount(e.target.value)}\n            inputMode=\"decimal\"\n            placeholder=\"120\"\n            className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#FDB813] outline-none\"\n          />\n        </div>\n      )}\n\n      <label className=\"flex items-center gap-2.5 cursor-pointer\">\n        <input\n          type=\"checkbox\"\n          checked={once}\n          onChange={(e) => setOnce(e.target.checked)}\n          className=\"w-4 h-4 accent-[#FDB813]\"\n        />\n        <span className=\"text-[10px] font-mono uppercase tracking-[0.15em] text-[#94A3B8]\">\n          One payment only, then close it\n        </span>\n      </label>\n\n      <div className=\"flex gap-2\">\n        <button\n          onClick={onCancel}\n          className=\"flex-1 bg-[#1F2937] hover:bg-[#374151] text-[#94A3B8] font-black uppercase tracking-widest text-xs py-3.5 rounded-xl transition-colors\"\n        >\n          Cancel\n        </button>\n        <button\n          disabled={busy || !title || (!open && n <= 0)}\n          onClick={() =>\n            onCreate(title.trim(), open ? null : n, null, once ? 1 : null, null)\n          }\n          className=\"flex-[2] bg-[#FDB813] hover:bg-[#E0A411] disabled:opacity-40 text-[#0A0E14] font-black uppercase tracking-widest text-xs py-3.5 rounded-xl transition-colors\"\n        >\n          {busy ? \"Making...\" : \"Make the link\"}\n        </button>\n      </div>\n    </div>\n  );\n}\n\nfunction LinkCard({ l, busy, onToggle }: { l: PayLink; busy: string | null; onToggle: () => void }) {\n  const [copied, setCopied] = useState(false);\n  const dead = !l.active || l.expired || l.used_up;\n\n  const url =\n    typeof window !== \"undefined\"\n      ? `${window.location.origin}/m/${l.reference}`\n      : `/m/${l.reference}`;\n\n  const copy = async () => {\n    try {\n      await navigator.clipboard.writeText(url);\n      setCopied(true);\n      setTimeout(() => setCopied(false), 1600);\n    } catch {\n      toast.error(\"Could not copy — the code is \" + l.reference);\n    }\n  };\n\n  return (\n    <div\n      className={`bg-[#111827]/80 backdrop-blur-xl border rounded-2xl p-4 ${\n        dead ? \"border-[#1F2937] opacity-60\" : \"border-[#1F2937]\"\n      }`}\n    >\n      <div className=\"flex justify-between items-start mb-3 gap-2\">\n        <div className=\"min-w-0\">\n          <h3 className=\"font-black uppercase tracking-wide text-sm truncate\">{l.title}</h3>\n          <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mt-1\">\n            {l.open_amount ? \"They choose\" : `${num(l.amount).toLocaleString()} KPC`} ·{\" \"}\n            {l.payments} paid · {num(l.taken).toLocaleString(undefined, { maximumFractionDigits: 2 })} KPC in\n          </p>\n        </div>\n        <button\n          onClick={onToggle}\n          disabled={busy === l.id + \":t\"}\n          title={l.active ? \"Close this link\" : \"Open it again\"}\n          className={`shrink-0 p-2 rounded-lg border transition-colors ${\n            l.active\n              ? \"border-[#10B981]/40 text-[#10B981] hover:bg-[#10B981]/10\"\n              : \"border-[#374151] text-[#94A3B8] hover:bg-[#1F2937]\"\n          }`}\n        >\n          <Power size={13} />\n        </button>\n      </div>\n\n      {l.used_up && (\n        <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mb-2\">\n          Used up\n        </p>\n      )}\n      {l.expired && (\n        <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mb-2\">\n          Expired\n        </p>\n      )}\n\n      <button\n        onClick={copy}\n        className=\"w-full flex items-center justify-between bg-[#0A0E14] border border-[#1F2937] hover:border-[#FDB813]/50 rounded-lg px-3 py-2.5 transition-colors group\"\n      >\n        <span className=\"font-mono text-[11px] tracking-[0.1em] text-[#FDB813] truncate\">\n          /m/{l.reference}\n        </span>\n        <span className=\"flex items-center gap-1.5 shrink-0 ml-2 text-[9px] font-mono uppercase tracking-[0.15em] text-[#94A3B8] group-hover:text-[#FDB813]\">\n          {copied ? <Check size={12} /> : <Copy size={12} />}\n          {copied ? \"Copied\" : \"Copy\"}\n        </span>\n      </button>\n    </div>\n  );\n}\n\nfunction SaleRow({ s, first, onRefund }: { s: Sale; first: boolean; onRefund: () => void }) {\n  const refunded = num(s.refunded_amount);\n  const full = refunded >= num(s.amount);\n\n  return (\n    <div className={`px-4 py-3 ${first ? \"\" : \"border-t border-[#1F2937]\"}`}>\n      <div className=\"flex items-center justify-between gap-3\">\n        <div className=\"min-w-0\">\n          <p className=\"text-sm font-bold truncate\">\n            {s.title ?? \"Payment\"}\n            {s.other_party ? ` · ${s.other_party}` : \"\"}\n          </p>\n          <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em]\">\n            {new Date(s.created_at).toLocaleDateString()} · fee{\" \"}\n            {num(s.fee).toLocaleString(undefined, { maximumFractionDigits: 2 })}\n            {refunded > 0 &&\n              ` · refunded ${refunded.toLocaleString(undefined, { maximumFractionDigits: 2 })}`}\n          </p>\n        </div>\n        <div className=\"shrink-0 text-right\">\n          <p className={`text-sm font-black ${full ? \"text-[#94A3B8] line-through\" : \"text-[#10B981]\"}`}>\n            +{num(s.net).toLocaleString(undefined, { maximumFractionDigits: 2 })}\n          </p>\n          {!full && (\n            <button\n              onClick={onRefund}\n              className=\"text-[9px] font-mono uppercase tracking-[0.15em] text-[#4B5563] hover:text-[#EF4444] transition-colors\"\n            >\n              Refund\n            </button>\n          )}\n        </div>\n      </div>\n    </div>\n  );\n}\n\nfunction RefundSheet({\n  s,\n  onClose,\n  onDone,\n}: {\n  s: Sale;\n  onClose: () => void;\n  onDone: () => void;\n}) {\n  const left = num(s.amount) - num(s.refunded_amount);\n  const [amount, setAmount] = useState(String(left));\n  const [why, setWhy] = useState(\"\");\n  const [busy, setBusy] = useState(false);\n\n  const n = Number(amount) || 0;\n\n  const submit = async () => {\n    setBusy(true);\n    const { error } = await supabase.rpc(\"refund_merchant_payment\", {\n      p_payment: s.id,\n      p_amount: n,\n      p_why: why.trim() || null,\n    });\n    setBusy(false);\n    if (error) {\n      toast.error(error.message.replace(/^.*?:\\s*/, \"\"));\n      return;\n    }\n    toast.success(\"Refunded\");\n    onDone();\n  };\n\n  return (\n    <div className=\"fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/70 backdrop-blur-sm p-0 sm:p-5\">\n      <div className=\"w-full sm:max-w-md bg-[#111827] border border-[#1F2937] rounded-t-2xl sm:rounded-2xl p-5 space-y-4\">\n        <div className=\"flex justify-between items-start\">\n          <div className=\"min-w-0\">\n            <h3 className=\"font-black uppercase tracking-wide text-sm\">Refund</h3>\n            <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mt-1 truncate\">\n              {s.title ?? \"Payment\"} · {left.toLocaleString()} KPC left\n            </p>\n          </div>\n          <button onClick={onClose} className=\"text-[#94A3B8] hover:text-white p-1\" aria-label=\"Close\">\n            <X size={18} />\n          </button>\n        </div>\n\n        {/* The fee is not returned, because KobPay already paid to process it.\n            Saying so here avoids a second argument later. */}\n        <div className=\"bg-[#1F2937] border border-[#374151] rounded-lg p-3\">\n          <p className=\"text-[10px] font-mono text-[#94A3B8] leading-relaxed uppercase\">\n            This comes out of your wallet, not from KobPay. The{\" \"}\n            {num(s.fee).toLocaleString(undefined, { maximumFractionDigits: 2 })} KPC\n            fee is not returned.\n          </p>\n        </div>\n\n        <div>\n          <span className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1.5\">\n            How much\n          </span>\n          <input\n            value={amount}\n            onChange={(e) => setAmount(e.target.value)}\n            inputMode=\"decimal\"\n            className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white focus:border-[#EF4444] outline-none\"\n          />\n        </div>\n\n        <input\n          value={why}\n          onChange={(e) => setWhy(e.target.value)}\n          placeholder=\"Why (optional)\"\n          className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-2.5 text-sm text-white placeholder-[#4B5563] focus:border-[#EF4444] outline-none\"\n        />\n\n        <div className=\"flex gap-2\">\n          <button\n            onClick={onClose}\n            className=\"flex-1 bg-[#1F2937] hover:bg-[#374151] text-[#94A3B8] font-black uppercase tracking-widest text-xs py-3.5 rounded-xl transition-colors\"\n          >\n            Cancel\n          </button>\n          <button\n            disabled={busy || n <= 0 || n > left}\n            onClick={submit}\n            className=\"flex-[2] bg-[#EF4444] hover:bg-[#DC2626] disabled:opacity-40 text-white font-black uppercase tracking-widest text-xs py-3.5 rounded-xl transition-colors\"\n          >\n            {busy ? \"Refunding...\" : `Refund ${n > 0 ? n.toLocaleString() : \"\"}`}\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n}\n");

write("app/send/page.tsx", "\"use client\";\n\nimport React, { Suspense, useState, useEffect } from \"react\";\nimport Link from \"next/link\";\nimport { useSearchParams } from \"next/navigation\";\nimport { ArrowLeft, Send, Zap, AlertCircle, CheckCircle2, Loader2 } from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\nimport AppMenu from \"../components/AppMenu\";\nimport { useKpcBalance } from \"../lib/useKpcBalance\";\n\n// Renamed so the default export can wrap it in Suspense. useSearchParams\n// forces a client bailout without one, and Next fails the build rather than\n// shipping a page that cannot prerender.\nfunction SendForm() {\n  const [currentUser, setCurrentUser] = useState<{ id: string; accessToken: string } | null>(null);\n  // Filled in by a scanned QR: /send?to=233244123456&amount=50. The payer\n  // still sees and confirms both before anything moves.\n  const params = useSearchParams();\n  const [recipientPhone, setRecipientPhone] = useState(params.get(\"to\") ?? \"\");\n  const [amount, setAmount] = useState(params.get(\"amount\") ?? \"\");\n  const [isSending, setIsSending] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [success, setSuccess] = useState(false);\n\n  const { balance } = useKpcBalance(currentUser?.id ?? null);\n\n  useEffect(() => {\n    supabase.auth.getSession().then(({ data }) => {\n      if (data.session) {\n        setCurrentUser({ id: data.session.user.id, accessToken: data.session.access_token });\n      }\n    });\n  }, []);\n\n  const handleSend = async (e: React.FormEvent) => {\n    e.preventDefault();\n    if (!currentUser) return;\n\n    setIsSending(true);\n    setError(null);\n    setSuccess(false);\n\n    try {\n      const res = await fetch(\"/api/transfer\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({\n          accessToken: currentUser.accessToken,\n          recipientPhone,\n          amount: Number(amount),\n        }),\n      });\n\n      const data = await res.json();\n\n      if (!res.ok) {\n        throw new Error(data.error || \"Transfer failed\");\n      }\n\n      setSuccess(true);\n      setRecipientPhone(\"\");\n      setAmount(\"\");\n    } catch (err: any) {\n      setError(err.message);\n    } finally {\n      setIsSending(false);\n    }\n  };\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white flex flex-col items-center justify-center p-5 lg:p-8 font-sans selection:bg-[#AA771C]/30 relative overflow-hidden\">\n      <div className=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] bg-gradient-to-tr from-[#10B981]/5 via-transparent to-[#FDB813]/5 rounded-full blur-[100px] pointer-events-none\" />\n\n      <div className=\"bg-[#111827]/80 backdrop-blur-xl border border-[#1F2937] p-8 lg:p-10 rounded-[2rem] shadow-[0_0_80px_rgba(0,0,0,0.8)] max-w-lg w-full relative z-10\">\n        <div className=\"flex justify-between items-center mb-10\">\n          <Link href=\"/\" className=\"text-[#94A3B8] hover:text-[#FDB813] transition-colors p-2 bg-[#1F2937] rounded-lg border border-[#374151]\">\n            <ArrowLeft size={20} />\n          </Link>\n          <AppMenu />\n          <div className=\"flex items-center gap-2 text-[10px] font-mono tracking-widest uppercase bg-[#0A0E14] px-3 py-1.5 rounded-full border border-[#1F2937]\">\n            <Zap size={12} className=\"text-[#FDB813]\" /> Transfer Protocol\n          </div>\n        </div>\n\n        <h1 className=\"text-3xl font-black uppercase tracking-widest mb-2 text-white\">Send KPC</h1>\n        <p className=\"text-xs font-mono text-[#94A3B8] tracking-widest uppercase mb-4\">\n          Instant, $1-pegged transfer to any KobPay user, anywhere.\n        </p>\n\n        {currentUser && balance !== null && (\n          <div className=\"bg-[#0A0E14] border border-[#1F2937] p-4 rounded-xl flex justify-between items-center mb-6\">\n            <span className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-widest\">Your Balance</span>\n            <span className=\"text-lg font-black font-mono text-[#FDB813]\">{balance.toLocaleString()} KPC</span>\n          </div>\n        )}\n\n        {!currentUser ? (\n          <div className=\"bg-[#EF4444]/10 border border-[#EF4444]/30 p-6 rounded-xl flex items-start gap-4 mb-6\">\n            <AlertCircle className=\"text-[#EF4444] shrink-0\" size={24} />\n            <p className=\"text-xs font-mono text-[#EF4444] leading-relaxed uppercase\">\n              Connection Required. Please <Link href=\"/auth\" className=\"font-bold underline\">sign in</Link> before sending KPC.\n            </p>\n          </div>\n        ) : (\n          <form onSubmit={handleSend} className=\"space-y-6\">\n            <div className=\"space-y-2\">\n              <label className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] ml-1\">\n                Recipient's Phone Number\n              </label>\n              <input\n                type=\"tel\"\n                placeholder=\"+233...\"\n                value={recipientPhone}\n                onChange={(e) => setRecipientPhone(e.target.value)}\n                disabled={isSending}\n                className=\"w-full bg-[#0A0E14] border border-[#374151] rounded-xl px-4 py-4 text-sm font-mono text-white outline-none focus:border-[#FDB813] transition-colors placeholder:text-[#374151]\"\n                required\n              />\n            </div>\n\n            <div className=\"space-y-2\">\n              <label className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] ml-1\">\n                Amount (KPC)\n              </label>\n              <div className=\"relative\">\n                <input\n                  type=\"number\"\n                  step=\"0.01\"\n                  placeholder=\"0.00\"\n                  value={amount}\n                  onChange={(e) => setAmount(e.target.value)}\n                  disabled={isSending}\n                  className=\"w-full bg-[#0A0E14] border border-[#374151] rounded-xl pl-4 pr-16 py-4 text-xl font-black font-mono text-white outline-none focus:border-[#FDB813] transition-colors placeholder:text-[#374151]\"\n                  required\n                />\n                <div className=\"absolute right-4 top-1/2 -translate-y-1/2 text-xs font-mono font-bold text-[#FDB813] tracking-widest\">\n                  KPC\n                </div>\n              </div>\n            </div>\n\n            <button\n              type=\"submit\"\n              disabled={isSending || !recipientPhone || !amount}\n              className=\"w-full mt-4 flex items-center justify-center gap-3 py-4 bg-[#FDB813] disabled:bg-[#374151] disabled:text-[#94A3B8] text-[#0A0E14] hover:bg-[#F59E0B] transition-all rounded-xl font-mono text-xs uppercase font-black tracking-[0.2em] shadow-[0_0_20px_rgba(253,184,19,0.2)] disabled:shadow-none\"\n            >\n              {isSending ? (\n                <>\n                  <Loader2 size={18} className=\"animate-spin\" /> Sending...\n                </>\n              ) : (\n                <>\n                  <Send size={18} /> Send KPC\n                </>\n              )}\n            </button>\n\n            {success && (\n              <div className=\"bg-[#10B981]/10 border border-[#10B981]/30 p-4 rounded-xl flex items-center gap-3 text-[#10B981]\">\n                <CheckCircle2 size={20} />\n                <span className=\"text-[10px] font-mono uppercase tracking-widest\">Transfer Successful!</span>\n              </div>\n            )}\n\n            {error && (\n              <div className=\"bg-[#EF4444]/10 border border-[#EF4444]/30 p-4 rounded-xl flex items-start gap-3 text-[#EF4444]\">\n                <AlertCircle size={20} className=\"shrink-0 mt-0.5\" />\n                <span className=\"text-[10px] font-mono uppercase tracking-widest\">{error}</span>\n              </div>\n            )}\n\n            {/* The moment of hesitation is here, right above the button, not\n                buried in a menu. A plain send stays plain; the people who need\n                protection are the ones already pausing. */}\n            <Link\n              href=\"/safe\"\n              className=\"block text-center pt-2 text-[9px] font-mono uppercase tracking-[0.2em] text-[#4B5563] hover:text-[#10B981] transition-colors leading-relaxed\"\n            >\n              Paying someone you don&apos;t know?\n              <br />\n              <span className=\"text-[#10B981]\">Hold it until it arrives &rarr;</span>\n            </Link>\n          </form>\n        )}\n      </div>\n    </div>\n  );\n}\n\nexport default function SendPage() {\n  return (\n    <Suspense fallback={<div className=\"min-h-[100dvh] bg-[#0A0E14]\" />}>\n      <SendForm />\n    </Suspense>\n  );\n}\n");

write("app/withdraw/page.tsx", "\"use client\";\n\nimport React, { useState, useEffect } from \"react\";\nimport Link from \"next/link\";\nimport { ArrowLeft, Wallet, AlertCircle, CheckCircle2, Loader2, Smartphone, Landmark } from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\nimport AppMenu from \"../components/AppMenu\";\nimport { useKpcBalance } from \"../lib/useKpcBalance\";\n\nconst COUNTRY_PROVIDERS: Record<string, { label: string; code: string; wired: boolean }[]> = {\n  Ghana: [\n    { label: \"MTN Mobile Money\", code: \"MTN\", wired: true },\n    { label: \"Vodafone Cash / Telecel\", code: \"VOD\", wired: true },\n    { label: \"AirtelTigo Money\", code: \"ATL\", wired: true },\n  ],\n  Nigeria: [{ label: \"Bank Transfer\", code: \"NUBAN\", wired: true }],\n  Kenya: [{ label: \"M-Pesa\", code: \"MPESA\", wired: false }],\n  Philippines: [{ label: \"GCash\", code: \"GCASH\", wired: false }],\n  \"Côte d'Ivoire\": [\n    { label: \"Orange Money\", code: \"ORANGE\", wired: false },\n    { label: \"MTN Mobile Money\", code: \"MTN_CI\", wired: false },\n  ],\n  Other: [{ label: \"Contact support for your region\", code: \"OTHER\", wired: false }],\n};\n\nexport default function WithdrawPage() {\n  const [currentUser, setCurrentUser] = useState<{ id: string; accessToken: string } | null>(null);\n  const [payoutType, setPayoutType] = useState<\"mobile_money\" | \"nuban\">(\"mobile_money\");\n  const [country, setCountry] = useState(\"Ghana\");\n  const [amount, setAmount] = useState(\"\");\n  const [phone, setPhone] = useState(\"\");\n  const [provider, setProvider] = useState(\"MTN\");\n  const [accountNumber, setAccountNumber] = useState(\"\");\n  const [bankCode, setBankCode] = useState(\"\");\n  const [isSubmitting, setIsSubmitting] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [success, setSuccess] = useState(false);\n\n  const { balance } = useKpcBalance(currentUser?.id ?? null);\n\n  const providersForCountry = COUNTRY_PROVIDERS[country] ?? COUNTRY_PROVIDERS.Other;\n  const selectedProviderInfo = providersForCountry.find((p) => p.code === provider);\n  const isProviderWired = selectedProviderInfo?.wired ?? false;\n\n  useEffect(() => {\n    setProvider(providersForCountry[0]?.code ?? \"\");\n  }, [country]);\n\n  useEffect(() => {\n    supabase.auth.getSession().then(({ data }) => {\n      if (data.session) {\n        setCurrentUser({ id: data.session.user.id, accessToken: data.session.access_token });\n      }\n    });\n  }, []);\n\n  const handleWithdraw = async (e: React.FormEvent) => {\n    e.preventDefault();\n    if (!currentUser) return;\n\n    if (payoutType === \"mobile_money\" && !isProviderWired) {\n      setError(\"This region isn't connected to a live payout processor yet.\");\n      return;\n    }\n\n    setIsSubmitting(true);\n    setError(null);\n    setSuccess(false);\n\n    const accountDetails =\n      payoutType === \"mobile_money\" ? { phone, provider } : { accountNumber, bankCode };\n\n    try {\n      const res = await fetch(\"/api/withdrawals/initialize\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({\n          accessToken: currentUser.accessToken,\n          amountUsd: Number(amount),\n          payoutType,\n          accountDetails,\n        }),\n      });\n\n      const data = await res.json();\n\n      if (!res.ok) {\n        throw new Error(data.error || \"Withdrawal failed\");\n      }\n\n      setSuccess(true);\n      setAmount(\"\");\n      setPhone(\"\");\n      setAccountNumber(\"\");\n      setBankCode(\"\");\n    } catch (err: any) {\n      setError(err.message);\n    } finally {\n      setIsSubmitting(false);\n    }\n  };\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white flex flex-col items-center justify-center p-5 lg:p-8 font-sans selection:bg-[#AA771C]/30 relative overflow-hidden\">\n      <div className=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] bg-gradient-to-tr from-[#10B981]/5 via-transparent to-[#FDB813]/5 rounded-full blur-[100px] pointer-events-none\" />\n\n      <div className=\"bg-[#111827]/80 backdrop-blur-xl border border-[#1F2937] p-8 lg:p-10 rounded-[2rem] shadow-[0_0_80px_rgba(0,0,0,0.8)] max-w-lg w-full relative z-10\">\n        <div className=\"flex justify-between items-center mb-10\">\n          <Link href=\"/\" className=\"text-[#94A3B8] hover:text-[#FDB813] transition-colors p-2 bg-[#1F2937] rounded-lg border border-[#374151]\">\n            <ArrowLeft size={20} />\n          </Link>\n          <AppMenu />\n          <div className=\"flex items-center gap-2 text-[10px] font-mono tracking-widest uppercase bg-[#0A0E14] px-3 py-1.5 rounded-full border border-[#1F2937]\">\n            <Wallet size={12} className=\"text-[#FDB813]\" /> Cash Out\n          </div>\n        </div>\n\n        <h1 className=\"text-3xl font-black uppercase tracking-widest mb-2 text-white\">Withdraw KPC</h1>\n        <p className=\"text-xs font-mono text-[#94A3B8] tracking-widest uppercase mb-4\">\n          Convert KPC back to real cash, delivered to mobile money or bank.\n        </p>\n\n        {currentUser && balance !== null && (\n          <div className=\"bg-[#0A0E14] border border-[#1F2937] p-4 rounded-xl flex justify-between items-center mb-6\">\n            <span className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-widest\">Available Balance</span>\n            <span className=\"text-lg font-black font-mono text-[#FDB813]\">{balance.toLocaleString()} KPC</span>\n          </div>\n        )}\n\n        {!currentUser ? (\n          <div className=\"bg-[#EF4444]/10 border border-[#EF4444]/30 p-6 rounded-xl flex items-start gap-4 mb-6\">\n            <AlertCircle className=\"text-[#EF4444] shrink-0\" size={24} />\n            <p className=\"text-xs font-mono text-[#EF4444] leading-relaxed uppercase\">\n              Connection Required. Please <Link href=\"/auth\" className=\"font-bold underline\">sign in</Link> before withdrawing.\n            </p>\n          </div>\n        ) : (\n          <form onSubmit={handleWithdraw} className=\"space-y-6\">\n            <div className=\"flex p-1.5 bg-[#0A0E14] rounded-2xl border border-[#1F2937]\">\n              <button\n                type=\"button\"\n                onClick={() => setPayoutType(\"mobile_money\")}\n                className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-mono text-[11px] font-bold uppercase tracking-widest transition-all ${\n                  payoutType === \"mobile_money\" ? \"bg-[#1F2937] text-[#FDB813]\" : \"text-[#94A3B8] hover:text-white\"\n                }`}\n              >\n                <Smartphone size={14} /> Mobile Money\n              </button>\n              <button\n                type=\"button\"\n                onClick={() => setPayoutType(\"nuban\")}\n                className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-mono text-[11px] font-bold uppercase tracking-widest transition-all ${\n                  payoutType === \"nuban\" ? \"bg-[#1F2937] text-[#FDB813]\" : \"text-[#94A3B8] hover:text-white\"\n                }`}\n              >\n                <Landmark size={14} /> Bank Account\n              </button>\n            </div>\n\n            {payoutType === \"mobile_money\" ? (\n              <>\n                <div className=\"space-y-2\">\n                  <label className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] ml-1\">\n                    Country\n                  </label>\n                  <select\n                    value={country}\n                    onChange={(e) => setCountry(e.target.value)}\n                    className=\"w-full bg-[#0A0E14] border border-[#374151] rounded-xl px-4 py-4 text-sm font-mono text-white outline-none focus:border-[#FDB813] transition-colors\"\n                  >\n                    {Object.keys(COUNTRY_PROVIDERS).map((c) => (\n                      <option key={c} value={c}>\n                        {c}\n                      </option>\n                    ))}\n                  </select>\n                </div>\n                <div className=\"space-y-2\">\n                  <label className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] ml-1\">\n                    Mobile Money Network\n                  </label>\n                  <select\n                    value={provider}\n                    onChange={(e) => setProvider(e.target.value)}\n                    className=\"w-full bg-[#0A0E14] border border-[#374151] rounded-xl px-4 py-4 text-sm font-mono text-white outline-none focus:border-[#FDB813] transition-colors\"\n                  >\n                    {providersForCountry.map((p) => (\n                      <option key={p.code} value={p.code}>\n                        {p.label}\n                      </option>\n                    ))}\n                  </select>\n                </div>\n                {!isProviderWired && (\n                  <div className=\"bg-[#FDB813]/10 border border-[#FDB813]/30 p-4 rounded-xl flex items-start gap-3\">\n                    <AlertCircle className=\"text-[#FDB813] shrink-0\" size={16} />\n                    <p className=\"text-[10px] font-mono text-[#FDB813] leading-relaxed uppercase\">\n                      This network isn't connected to a live payout processor yet. Submitting will not actually send money — support for this region is coming soon.\n                    </p>\n                  </div>\n                )}\n                <div className=\"space-y-2\">\n                  <label className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] ml-1\">\n                    Mobile Money Number\n                  </label>\n                  <input\n                    type=\"tel\"\n                    placeholder=\"+233...\"\n                    value={phone}\n                    onChange={(e) => setPhone(e.target.value)}\n                    disabled={isSubmitting}\n                    className=\"w-full bg-[#0A0E14] border border-[#374151] rounded-xl px-4 py-4 text-sm font-mono text-white outline-none focus:border-[#FDB813] transition-colors placeholder:text-[#374151]\"\n                    required\n                  />\n                </div>\n              </>\n            ) : (\n              <>\n                <div className=\"space-y-2\">\n                  <label className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] ml-1\">\n                    Bank Account Number\n                  </label>\n                  <input\n                    type=\"text\"\n                    placeholder=\"0123456789\"\n                    value={accountNumber}\n                    onChange={(e) => setAccountNumber(e.target.value)}\n                    disabled={isSubmitting}\n                    className=\"w-full bg-[#0A0E14] border border-[#374151] rounded-xl px-4 py-4 text-sm font-mono text-white outline-none focus:border-[#FDB813] transition-colors placeholder:text-[#374151]\"\n                    required\n                  />\n                </div>\n                <div className=\"space-y-2\">\n                  <label className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] ml-1\">\n                    Bank Code\n                  </label>\n                  <input\n                    type=\"text\"\n                    placeholder=\"e.g. 300302 (GCB)\"\n                    value={bankCode}\n                    onChange={(e) => setBankCode(e.target.value)}\n                    disabled={isSubmitting}\n                    className=\"w-full bg-[#0A0E14] border border-[#374151] rounded-xl px-4 py-4 text-sm font-mono text-white outline-none focus:border-[#FDB813] transition-colors placeholder:text-[#374151]\"\n                    required\n                  />\n                  <p className=\"text-[9px] font-mono text-[#374151] uppercase tracking-widest ml-1\">\n                    Find your bank's code via Paystack's public bank list API — not hardcoded here since it changes.\n                  </p>\n                </div>\n              </>\n            )}\n\n            <div className=\"space-y-2\">\n              <label className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] ml-1\">\n                Amount (USD)\n              </label>\n              <div className=\"relative\">\n                <input\n                  type=\"number\"\n                  step=\"0.01\"\n                  placeholder=\"0.00\"\n                  value={amount}\n                  onChange={(e) => setAmount(e.target.value)}\n                  disabled={isSubmitting}\n                  className=\"w-full bg-[#0A0E14] border border-[#374151] rounded-xl pl-4 pr-16 py-4 text-xl font-black font-mono text-white outline-none focus:border-[#FDB813] transition-colors placeholder:text-[#374151]\"\n                  required\n                />\n                <div className=\"absolute right-4 top-1/2 -translate-y-1/2 text-xs font-mono font-bold text-[#FDB813] tracking-widest\">\n                  KPC\n                </div>\n              </div>\n            </div>\n\n            <button\n              type=\"submit\"\n              disabled={isSubmitting}\n              className=\"w-full mt-4 flex items-center justify-center gap-3 py-4 bg-[#FDB813] disabled:bg-[#374151] disabled:text-[#94A3B8] text-[#0A0E14] hover:bg-[#F59E0B] transition-all rounded-xl font-mono text-xs uppercase font-black tracking-[0.2em] shadow-[0_0_20px_rgba(253,184,19,0.2)] disabled:shadow-none\"\n            >\n              {isSubmitting ? (\n                <>\n                  <Loader2 size={18} className=\"animate-spin\" /> Processing...\n                </>\n              ) : (\n                <>\n                  <Wallet size={18} /> Withdraw\n                </>\n              )}\n            </button>\n\n            {success && (\n              <div className=\"bg-[#10B981]/10 border border-[#10B981]/30 p-4 rounded-xl flex items-center gap-3 text-[#10B981]\">\n                <CheckCircle2 size={20} />\n                <span className=\"text-[10px] font-mono uppercase tracking-widest\">\n                  Withdrawal initiated — funds will arrive shortly.\n                </span>\n              </div>\n            )}\n\n            {error && (\n              <div className=\"bg-[#EF4444]/10 border border-[#EF4444]/30 p-4 rounded-xl flex items-start gap-3 text-[#EF4444]\">\n                <AlertCircle size={20} className=\"shrink-0 mt-0.5\" />\n                <span className=\"text-[10px] font-mono uppercase tracking-widest\">{error}</span>\n              </div>\n            )}\n          </form>\n        )}\n      </div>\n    </div>\n  );\n}");

write("app/pay/page.tsx", "\"use client\";\n\nimport React, { useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport AppMenu from \"../components/AppMenu\";\nimport { useRouter } from \"next/navigation\";\nimport {\n  ArrowLeft,\n  QrCode,\n  ScanLine,\n  Copy,\n  CheckCircle2,\n  Loader2,\n  Keyboard,\n  CameraOff,\n} from \"lucide-react\";\nimport QRCode from \"react-qr-code\";\nimport { Scanner } from \"@yudiel/react-qr-scanner\";\nimport { supabase } from \"../lib/supabaseClient\";\nimport toast, { Toaster } from \"react-hot-toast\";\n\n// WHAT THIS PAGE USED TO DO\n//\n// Receive generated a QR of the user's wagmi wallet address, falling back to\n// 0x0000…0000 when none was connected — which is almost always, because\n// KobPay users sign in with a phone number. Anyone scanning it was shown a\n// dead destination.\n//\n// Scan read a hex string and raised a toast. No payment followed.\n//\n// And every camera failure collapsed into \"Camera currently unavailable\",\n// which is the one message that tells you nothing you can act on.\n//\n// WHAT IT DOES NOW\n//\n// Receive encodes a link to /send addressed to the user's phone, optionally\n// with an amount. Scan decodes a KobPay link and goes where it points — a\n// merchant payment link opens that invoice, a personal link opens Send with\n// the recipient filled in.\n//\n// And there is a typed fallback, because a desktop with no camera is not an\n// error state, it is Tuesday.\n\nconst SITE =\n  typeof window !== \"undefined\" ? window.location.origin : \"https://www.kobpay.app\";\n\nexport default function PayTerminal() {\n  const router = useRouter();\n  const [activeTab, setActiveTab] = useState<\"scan\" | \"receive\">(\"scan\");\n  const [mounted, setMounted] = useState(false);\n  const [copied, setCopied] = useState(false);\n\n  const [phone, setPhone] = useState<string | null>(null);\n  const [askAmount, setAskAmount] = useState(\"\");\n\n  const [cameraError, setCameraError] = useState<string | null>(null);\n  const [typing, setTyping] = useState(false);\n  const [typed, setTyped] = useState(\"\");\n  const [resolving, setResolving] = useState(false);\n\n  useEffect(() => {\n    setMounted(true);\n    supabase.auth.getSession().then(({ data }) => {\n      setPhone(data.session?.user.phone ?? null);\n    });\n  }, []);\n\n  // The link a payer lands on. /send reads these and fills itself in.\n  const receiveLink = phone\n    ? `${SITE}/send?to=${encodeURIComponent(phone)}${\n        Number(askAmount) > 0 ? `&amount=${encodeURIComponent(askAmount)}` : \"\"\n      }`\n    : null;\n\n  const handleCopy = () => {\n    if (!receiveLink) return;\n    navigator.clipboard.writeText(receiveLink);\n    setCopied(true);\n    toast.success(\"Link copied\");\n    setTimeout(() => setCopied(false), 2000);\n  };\n\n  // Decode anything a KobPay QR might reasonably contain, and refuse the\n  // rest rather than guessing. A wrong guess here sends money somewhere.\n  const route = async (raw: string) => {\n    const text = (raw ?? \"\").trim();\n    if (!text) return;\n\n    // A full KobPay link: take the path, ignore the host so a link shared\n    // from a preview deployment still works.\n    try {\n      const u = new URL(text);\n      const m = u.pathname.match(/^\\/m\\/([A-Za-z0-9_-]+)$/);\n      if (m) return router.push(`/m/${m[1]}`);\n      if (u.pathname === \"/send\") {\n        const to = u.searchParams.get(\"to\");\n        const amt = u.searchParams.get(\"amount\");\n        if (to) {\n          return router.push(\n            `/send?to=${encodeURIComponent(to)}${amt ? `&amount=${encodeURIComponent(amt)}` : \"\"}`,\n          );\n        }\n      }\n      toast.error(\"That link is not a KobPay payment code\");\n      return;\n    } catch {\n      // Not a URL — fall through to treat it as a phone number or tag.\n    }\n\n    // A bare phone number or @tag. Resolve it before navigating, so a typo\n    // fails here with a clear message rather than on the Send screen.\n    setResolving(true);\n    const { data, error } = await supabase.rpc(\"find_recipient\", { p_identifier: text });\n    setResolving(false);\n\n    if (error || !data || (Array.isArray(data) && data.length === 0)) {\n      toast.error(\"No KobPay account matches that\");\n      return;\n    }\n    router.push(`/send?to=${encodeURIComponent(text)}`);\n  };\n\n  // Each failure gets the sentence that tells you what to do about it.\n  const describeCameraError = (err: unknown) => {\n    const name = (err as { name?: string })?.name ?? \"\";\n    switch (name) {\n      case \"NotAllowedError\":\n      case \"PermissionDeniedError\":\n        return \"Camera permission was declined. Allow it for this site in your browser settings, then reload.\";\n      case \"NotFoundError\":\n      case \"DevicesNotFoundError\":\n        return \"No camera on this device. Type the code instead.\";\n      case \"NotReadableError\":\n      case \"TrackStartError\":\n        return \"Another app is using the camera. Close it and reload.\";\n      case \"OverconstrainedError\":\n        return \"No camera matched what the scanner asked for. Type the code instead.\";\n      case \"SecurityError\":\n        return \"The camera needs a secure connection. Open this page over https.\";\n      default:\n        return name\n          ? `The camera could not start (${name}). Type the code instead.`\n          : \"The camera could not start. Type the code instead.\";\n    }\n  };\n\n  if (!mounted) return <div className=\"min-h-[100dvh] bg-[#0A0E14]\" />;\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-[#F9FAFB] font-sans selection:bg-[#AA771C]/30 flex flex-col\">\n      <Toaster position=\"top-center\" />\n\n      <header className=\"h-16 lg:h-20 border-b border-[#1F2937] bg-[#111827]/80 backdrop-blur-xl sticky top-0 z-40 flex items-center px-4 lg:px-8\">\n        <Link\n          href=\"/wallet\"\n          className=\"flex items-center gap-3 text-[#94A3B8] hover:text-[#FDB813] transition-colors group\"\n        >\n          <div className=\"p-2 bg-[#1F2937] rounded-lg group-hover:bg-[#FDB813]/20 transition-colors\">\n            <ArrowLeft size={18} />\n          </div>\n          <span className=\"font-mono font-bold tracking-widest uppercase text-[10px] lg:text-xs\">\n            Back\n          </span>\n        </Link>\n        <div className=\"ml-auto\">\n          <AppMenu />\n        </div>\n      </header>\n\n      <main className=\"flex-1 flex items-start justify-center p-4 lg:p-6\">\n        <div className=\"w-full max-w-md bg-[#111827] border border-[#1F2937] rounded-3xl shadow-2xl overflow-hidden flex flex-col\">\n          <div className=\"flex p-2 bg-[#0A0E14] m-3 lg:m-4 rounded-2xl border border-[#1F2937]\">\n            <button\n              onClick={() => setActiveTab(\"scan\")}\n              className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-mono text-[10px] lg:text-[11px] font-bold uppercase tracking-widest transition-all ${\n                activeTab === \"scan\"\n                  ? \"bg-[#1F2937] text-[#FDB813] shadow-lg\"\n                  : \"text-[#94A3B8] hover:text-white\"\n              }`}\n            >\n              <ScanLine size={15} /> Scan to pay\n            </button>\n            <button\n              onClick={() => setActiveTab(\"receive\")}\n              className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-mono text-[10px] lg:text-[11px] font-bold uppercase tracking-widest transition-all ${\n                activeTab === \"receive\"\n                  ? \"bg-[#1F2937] text-[#10B981] shadow-lg\"\n                  : \"text-[#94A3B8] hover:text-white\"\n              }`}\n            >\n              <QrCode size={15} /> Get paid\n            </button>\n          </div>\n\n          {activeTab === \"scan\" ? (\n            <div className=\"px-5 pb-6\">\n              <h2 className=\"text-lg font-black uppercase tracking-widest text-center\">\n                Scan a code\n              </h2>\n              <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] text-center mt-1 mb-5\">\n                Point at a KobPay QR to pay it\n              </p>\n\n              {typing || cameraError ? (\n                <div className=\"bg-[#0A0E14] border border-[#1F2937] rounded-2xl p-5\">\n                  {cameraError && !typing && (\n                    <div className=\"flex gap-3 mb-4\">\n                      <CameraOff size={16} className=\"text-[#94A3B8] shrink-0 mt-0.5\" />\n                      <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.1em] leading-relaxed\">\n                        {cameraError}\n                      </p>\n                    </div>\n                  )}\n\n                  <label className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-2\">\n                    Phone number, @tag or payment link\n                  </label>\n                  <input\n                    value={typed}\n                    onChange={(e) => setTyped(e.target.value)}\n                    onKeyDown={(e) => e.key === \"Enter\" && route(typed)}\n                    autoFocus\n                    placeholder=\"233244123456\"\n                    className=\"w-full bg-[#111827] border border-[#1F2937] rounded-lg px-3 py-3 text-sm font-mono text-white placeholder-[#4B5563] focus:border-[#FDB813] outline-none\"\n                  />\n                  <button\n                    disabled={resolving || !typed.trim()}\n                    onClick={() => route(typed)}\n                    className=\"w-full mt-3 py-3.5 bg-[#FDB813] hover:bg-[#E0A411] disabled:opacity-40 text-[#0A0E14] font-black font-mono text-[10px] uppercase tracking-[0.2em] rounded-xl flex items-center justify-center gap-2\"\n                  >\n                    {resolving && <Loader2 size={13} className=\"animate-spin\" />}\n                    Continue\n                  </button>\n\n                  {cameraError && (\n                    <button\n                      onClick={() => {\n                        setCameraError(null);\n                        setTyping(false);\n                      }}\n                      className=\"w-full mt-3 text-[9px] font-mono uppercase tracking-[0.15em] text-[#4B5563] hover:text-[#94A3B8]\"\n                    >\n                      Try the camera again\n                    </button>\n                  )}\n                  {!cameraError && (\n                    <button\n                      onClick={() => setTyping(false)}\n                      className=\"w-full mt-3 text-[9px] font-mono uppercase tracking-[0.15em] text-[#4B5563] hover:text-[#94A3B8]\"\n                    >\n                      Back to the camera\n                    </button>\n                  )}\n                </div>\n              ) : (\n                <>\n                  <div className=\"relative rounded-2xl overflow-hidden border border-[#1F2937] bg-black aspect-square\">\n                    <Scanner\n                      onScan={(result: Array<{ rawValue: string }>) => {\n                        if (result?.[0]?.rawValue) route(result[0].rawValue);\n                      }}\n                      onError={(error: unknown) => setCameraError(describeCameraError(error))}\n                      constraints={{ facingMode: \"environment\" }}\n                      styles={{ container: { width: \"100%\", height: \"100%\" } }}\n                    />\n                    <div className=\"absolute inset-0 pointer-events-none flex items-center justify-center\">\n                      <div className=\"w-2/3 aspect-square border-2 border-[#FDB813]/70 rounded-2xl\" />\n                    </div>\n                  </div>\n\n                  {/* Not a fallback for failure — a lot of people would simply\n                      rather type, and a desktop with no camera is normal. */}\n                  <button\n                    onClick={() => setTyping(true)}\n                    className=\"w-full mt-4 flex items-center justify-center gap-2 py-3 bg-[#1F2937] hover:bg-[#374151] border border-[#374151] rounded-lg text-[9px] font-mono uppercase tracking-[0.15em] text-[#94A3B8]\"\n                  >\n                    <Keyboard size={13} /> Type it instead\n                  </button>\n                </>\n              )}\n            </div>\n          ) : (\n            <div className=\"px-5 pb-6\">\n              <h2 className=\"text-lg font-black uppercase tracking-widest text-center\">\n                Get paid\n              </h2>\n              <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] text-center mt-1 mb-5\">\n                Let someone scan this to send you KPC\n              </p>\n\n              {!phone ? (\n                <div className=\"bg-[#0A0E14] border border-[#1F2937] rounded-2xl p-6 text-center\">\n                  <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] leading-relaxed\">\n                    Please{\" \"}\n                    <Link href=\"/auth\" className=\"text-[#FDB813] underline\">\n                      sign in\n                    </Link>{\" \"}\n                    to show your code.\n                  </p>\n                </div>\n              ) : (\n                <>\n                  <div className=\"bg-white p-5 rounded-2xl flex items-center justify-center\">\n                    <QRCode value={receiveLink ?? \"\"} size={200} />\n                  </div>\n\n                  <div className=\"mt-4\">\n                    <label className=\"block text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-2\">\n                      Ask for a set amount (optional)\n                    </label>\n                    <input\n                      value={askAmount}\n                      onChange={(e) => setAskAmount(e.target.value)}\n                      inputMode=\"decimal\"\n                      placeholder=\"Any amount\"\n                      className=\"w-full bg-[#0A0E14] border border-[#1F2937] rounded-lg px-3 py-3 text-sm font-mono text-white placeholder-[#4B5563] focus:border-[#10B981] outline-none text-center\"\n                    />\n                  </div>\n\n                  <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] text-center mt-4\">\n                    {phone.startsWith(\"+\") ? phone : `+${phone}`}\n                  </p>\n\n                  <button\n                    onClick={handleCopy}\n                    className=\"w-full mt-3 flex items-center justify-center gap-2 py-3 bg-[#1F2937] hover:bg-[#374151] border border-[#374151] rounded-lg text-[9px] font-mono uppercase tracking-[0.15em] text-[#94A3B8]\"\n                  >\n                    {copied ? (\n                      <>\n                        <CheckCircle2 size={13} className=\"text-[#10B981]\" /> Copied\n                      </>\n                    ) : (\n                      <>\n                        <Copy size={13} /> Copy link\n                      </>\n                    )}\n                  </button>\n\n                  <Link\n                    href=\"/merchant\"\n                    className=\"block text-center text-[9px] font-mono uppercase tracking-[0.15em] text-[#4B5563] hover:text-[#FDB813] mt-4\"\n                  >\n                    Taking payments for a business? Make a payment link\n                  </Link>\n                </>\n              )}\n            </div>\n          )}\n        </div>\n      </main>\n    </div>\n  );\n}\n");

write("app/ecosystem/page.tsx", "\"use client\";\n\nimport React, { useEffect, useState } from 'react';\nimport Link from 'next/link';\nimport AppMenu from '../components/AppMenu';\nimport { motion, AnimatePresence } from 'framer-motion';\nimport { \n  ArrowLeft, Layers, Plus, Bot, Gamepad2, \n  Store, Home, Zap, X, Code, Rocket, LucideIcon \n} from 'lucide-react';\nimport toast, { Toaster } from 'react-hot-toast';\nimport { supabase } from '../lib/supabaseClient';\n\n// --- TYPE DEFINITION ---\ninterface DApp {\n  id: number;\n  name: string;\n  desc: string;\n  icon: LucideIcon; // This tells TS to expect a Lucide Component\n  color: string;\n  border: string;\n}\n\n// These four were hardcoded: KobBot AI, KobPlay, Ready Markets, AegisProp.\n// None of them exist. Two apps are registered on the rail and neither was\n// named here — the same invention the scrolling banner was doing before 033,\n// except a directory is a stronger claim, because somebody may try to go and\n// use one. The list now comes from public_apps(). (036)\nconst INITIAL_DAPPS: DApp[] = [];\n\nexport default function EcosystemPage() {\n  const [dapps, setDapps] = useState<DApp[]>(INITIAL_DAPPS);\n  const [loading, setLoading] = useState(true);\n  const [isAdminOpen, setIsAdminOpen] = useState(false);\n  const [newAppName, setNewAppName] = useState(\"\");\n\n  useEffect(() => {\n    supabase.rpc(\"public_apps\").then(({ data }) => {\n      const list = (data as { apps?: { name: string; since: string }[] } | null)?.apps ?? [];\n      setDapps(\n        list.map((a, i) => ({\n          id: i + 1,\n          name: a.name,\n          desc: \"On the KobPay rail since \" + new Date(a.since).toLocaleDateString(),\n          icon: Rocket,\n          color: \"text-[#FDB813]\",\n          border: \"hover:border-[#FDB813]\",\n        })),\n      );\n      setLoading(false);\n    });\n  }, []);\n\n  const addApp = () => {\n    if (!newAppName) return;\n    const newApp: DApp = {\n      id: Date.now(),\n      name: newAppName,\n      desc: \"Your app is now live on KobPay.\",\n      icon: Rocket,\n      color: \"text-[#8B5CF6]\",\n      border: \"hover:border-[#8B5CF6]\"\n    };\n    setDapps([...dapps, newApp]);\n    setNewAppName(\"\");\n    setIsAdminOpen(false);\n    toast.success(`${newApp.name} added to this session`, {\n      style: { background: '#10B981', color: '#0A0E14', fontWeight: 'bold', fontSize: '12px', fontFamily: 'monospace' }\n    });\n  };\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white p-4 lg:p-6 lg:p-10 font-sans relative\">\n      <Toaster position=\"top-center\" />\n\n      {/* --- HEADER SECTION --- */}\n      <div className=\"max-w-[1400px] mx-auto\">\n        <div className=\"flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-12\">\n          <div className=\"flex items-center gap-4\">\n            <Link href=\"/\" className=\"p-3 bg-[#111827] rounded-xl border border-[#1F2937] hover:border-[#FDB813] transition-colors\">\n              <ArrowLeft size={20} />\n            </Link>\n            <AppMenu />\n            <div>\n              <h1 className=\"text-3xl font-black uppercase tracking-widest flex items-center gap-3\">\n                <Layers className=\"text-[#FDB813]\" size={28} /> Apps that take KPC\n              </h1>\n              <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.3em] mt-1\">Verified Protocol Directory</p>\n            </div>\n          </div>\n\n          <button \n            onClick={() => setIsAdminOpen(true)}\n            className=\"flex items-center gap-2 px-5 py-2.5 bg-[#111827] border border-[#1F2937] rounded-full text-[10px] font-mono font-bold uppercase tracking-widest hover:bg-[#1F2937] hover:border-[#FDB813] transition-all shadow-[0_0_20px_rgba(253,184,19,0.1)]\"\n          >\n            <Plus size={14} className=\"text-[#FDB813]\" /> Register Protocol\n          </button>\n        </div>\n\n        {/* --- DYNAMIC APP GRID --- */}\n        <div className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-4 gap-6\">\n          <AnimatePresence>\n            {!loading && dapps.length === 0 && (\n              <div className=\"col-span-full bg-[#111827] border border-[#1F2937] rounded-2xl p-8 text-center\">\n                <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] leading-relaxed\">\n                  No apps have joined yet. When one does, it appears here.\n                </p>\n              </div>\n            )}\n            {dapps.map((app) => {\n              const Icon = app.icon; // Standard component reference\n              return (\n                <motion.div \n                  key={app.id}\n                  layout\n                  initial={{ opacity: 0, y: 20 }}\n                  animate={{ opacity: 1, y: 0 }}\n                  exit={{ opacity: 0, scale: 0.9 }}\n                  className={`bg-[#111827]/60 backdrop-blur-xl border border-[#1F2937] p-8 rounded-[2rem] transition-all duration-300 group cursor-pointer hover:-translate-y-2 ${app.border} relative overflow-hidden shadow-2xl`}\n                >\n                  {/* Background Watermark Icon */}\n                  <div className=\"absolute top-0 right-0 p-6 opacity-[0.03] group-hover:opacity-10 transition-opacity\">\n                    <Icon size={120} />\n                  </div>\n                  \n                  {/* Primary Icon */}\n                  <div className={`w-14 h-14 bg-[#0A0E14] rounded-2xl flex items-center justify-center mb-6 border border-[#374151] group-hover:scale-110 transition-transform ${app.color}`}>\n                    <Icon size={28} />\n                  </div>\n\n                  <h3 className=\"text-lg font-black text-white tracking-widest uppercase mb-2\">{app.name}</h3>\n                  <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase leading-relaxed mb-8 h-10 line-clamp-2\">\n                    {app.desc}\n                  </p>\n                  \n                  <div className=\"flex items-center justify-between pt-6 border-t border-[#1F2937]\">\n                    <span className=\"text-[9px] font-mono text-[#10B981] flex items-center gap-1.5 uppercase tracking-widest\">\n                      <Zap size={10} className=\"fill-[#10B981]\" /> Live\n                    </span>\n                    <button\n                      onClick={() => toast(`${app.name} isn't connected yet — launch coming soon.`, {\n                        icon: '🚧',\n                        style: { background: '#111827', color: '#fff', border: '1px solid #FDB813', fontSize: '12px', fontFamily: 'monospace' }\n                      })}\n                      className=\"text-[9px] font-mono font-bold text-[#FDB813] uppercase tracking-[0.2em] group-hover:underline\"\n                    >\n                      Launch App\n                    </button>\n                  </div>\n                </motion.div>\n              );\n            })}\n          </AnimatePresence>\n        </div>\n      </div>\n\n      {/* --- ADMIN SLIDE-OUT PANEL --- */}\n      <AnimatePresence>\n        {isAdminOpen && (\n          <>\n            <motion.div \n              initial={{ opacity: 0 }} \n              animate={{ opacity: 1 }} \n              exit={{ opacity: 0 }} \n              className=\"fixed inset-0 bg-[#0A0E14]/80 backdrop-blur-sm z-[100]\" \n              onClick={() => setIsAdminOpen(false)} \n            />\n            <motion.div \n              initial={{ x: '100%' }} \n              animate={{ x: 0 }} \n              exit={{ x: '100%' }} \n              className=\"fixed right-0 top-0 bottom-0 w-full max-w-md bg-[#111827] border-l border-[#1F2937] z-[101] p-10 shadow-2xl\"\n            >\n              <div className=\"flex justify-between items-center mb-10\">\n                <h2 className=\"text-sm font-black uppercase tracking-[0.3em] flex items-center gap-3\">\n                  <Code className=\"text-[#FDB813]\" /> Deployment Registry\n                </h2>\n                <button onClick={() => setIsAdminOpen(false)} className=\"text-[#94A3B8] hover:text-white transition-colors\">\n                  <X size={20} />\n                </button>\n              </div>\n              \n              <div className=\"space-y-8\">\n                <div>\n                  <label className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.3em] block mb-4\">Protocol Identifier</label>\n                  <input \n                    autoFocus\n                    value={newAppName}\n                    onChange={(e) => setNewAppName(e.target.value)}\n                    placeholder=\"E.G. KOB-LENDING\"\n                    className=\"w-full bg-[#0A0E14] border border-[#374151] rounded-xl px-5 py-4 text-xs font-mono text-white focus:border-[#FDB813] outline-none transition-all placeholder:text-[#374151]\"\n                  />\n                </div>\n                \n                <div className=\"p-6 bg-[#0A0E14] border border-dashed border-[#374151] rounded-2xl\">\n                  <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase leading-relaxed tracking-widest\">\n                    This adds a preview card to your current session only. It is not yet submitted anywhere or visible to other users.\n                  </p>\n                </div>\n\n                <button \n                  onClick={addApp}\n                  className=\"w-full py-5 bg-[#FDB813] text-[#0A0E14] font-black font-mono text-[11px] uppercase tracking-[0.2em] rounded-xl hover:bg-[#F59E0B] transition-all shadow-[0_0_30px_rgba(253,184,19,0.2)]\"\n                >\n                  Add this app\n                </button>\n              </div>\n            </motion.div>\n          </>\n        )}\n      </AnimatePresence>\n    </div>\n  );\n}");

